/**
 * Gated C-vs-TS differential for Seismic: the TS generator reproduces the
 * upstream description **byte for byte** for every recorded `(params, seed)`.
 *
 * This is the strongest bar available here, and it validates far more than the
 * codec. Generation is solver-gated twice over — a clue is stripped only while
 * the board still solves at the target difficulty, and the finished board is
 * kept only if it solves at that difficulty and *not* one tier easier — so a
 * matching description proves the TS solver reaches C's verdict on every
 * intermediate board, that the region-merge draws the same RNG values in the
 * same order, and that the two-part run-length codec agrees. One assertion,
 * generator + solver + codec (playbook §4.4).
 *
 * The fixtures span all twelve of upstream's presets, both modes, both
 * difficulties and a non-square size sweep. They stop at 7×7 because upstream's
 * generator does: its region stage succeeds roughly once in 200,000 attempts
 * there and never above ~50 cells.
 *
 * **These run against the retained upstream region grower, not the shipped
 * one.** `replace-seismic-region-generator` replaced upstream's fill-then-merge
 * stages (the cause of that 1-in-200,000), but kept them reachable behind
 * `upstreamRegionGrower` precisely so this differential survives: everything
 * downstream of the regions — the solver's verdict on every intermediate board,
 * the clue-stripping loop, the codec — keeps its byte-exact oracle. The shipped
 * partition-and-fill is covered by property tests in `seismic.test.ts` instead,
 * along with an assertion that this flag still *changes* the output, so the
 * oracle cannot decay into re-testing the shipped path.
 *
 * Regenerate while `puzzles/unreleased/seismic.c` still exists (it is deleted at
 * owner acceptance; the fixture stays as this test's frozen baseline):
 *   cmake -B build/native -S puzzles -DUSE_TS_RANDOM=0
 *   (cd build/native && make seismic-trace)
 *   build/native/auxiliary/seismic-trace \
 *     > src/native/games/seismic/__fixtures__/seismic-c-reference.json
 */
import { describeDescDifferential } from "../../engine/testing/differential.ts";
import cReference from "./__fixtures__/seismic-c-reference.json" with { type: "json" };
import { newSeismicDesc } from "./generator.ts";
import { MODE_NAMES, type SeismicParams, validateDesc } from "./state.ts";

interface Fixture {
  seed: string;
  desc: string;
  w: number;
  h: number;
  diff: number;
  mode: number;
  /** Milliseconds the C build took for this board — recorded so the port's own
   * cost can be compared against upstream's rather than guessed at. Not
   * asserted on: a wall-clock assertion would measure the box, not the code
   * (playbook §5.2). */
  genMs: number;
}

const data = cReference as { fixtures: Fixture[] };

/** 7×7 boards legitimately cost upstream (and this port) tens of seconds to
 * generate — that is the documented weakness of the algorithm, not slow code,
 * and this port is measurably *faster* than the C on every fixture. They are
 * split into their own block purely so the suite's slow cases are named rather
 * than hidden inside a 28-case loop. */
const isSlow = (f: Fixture) => f.w * f.h >= 49;

/** The differential — and *only* the differential — runs upstream's region
 * grower, so the frozen descs stay reproducible byte-for-byte. */
const newDesc = (p: SeismicParams, rng: Parameters<typeof newSeismicDesc>[1]) =>
  newSeismicDesc(p, rng, { upstreamRegionGrower: true });

const label = (f: Fixture) =>
  `${MODE_NAMES[f.mode]} ${f.w}x${f.h} diff=${f.diff} seed=${f.seed}`;
const params = (f: Fixture): SeismicParams => ({
  w: f.w,
  h: f.h,
  diff: f.diff,
  mode: f.mode,
});
/** The generated description must also survive the game's own validator — the
 * codec's two halves are exact inverses, or a fresh game would not load. */
const extra = (f: Fixture, p: SeismicParams) => {
  if (validateDesc(p, f.desc) !== null) {
    throw new Error(`validateDesc rejected the C description: ${f.desc}`);
  }
};

describeDescDifferential<Fixture, SeismicParams>({
  title: "seismic differential (frozen C reference)",
  fixtures: data.fixtures.filter((f) => !isSlow(f)),
  label,
  params,
  newDesc,
  extra,
});

// The 7x7s cost **272 s** — 23% of the entire suite — and every configuration
// they carry (mode 0/1 × difficulty 0/1) is already asserted above by the 4x4,
// 5x5 and 6x6 fixtures. What they add is board *size* over the same code paths,
// which is worth having but not on every commit: `npm run test:slow`.
describeDescDifferential<Fixture, SeismicParams>({
  title: "seismic differential, 7x7 (frozen C reference; slow by construction)",
  fixtures: data.fixtures.filter(isSlow),
  label,
  params,
  newDesc,
  extra,
  slow: true,
});

src/native/games/group/group-hint.test.t.source:
/**
 * Group hint tests (`add-group-hint`): the recorded deductions, the plan the
 * hint builds, its refusals, and the keep-track verdicts.
 *
 * The cross-game guards (`hint-resume` / `hint-quality` / `hint-overlay`) already
 * cover convergence, purity, narration form and overlay-reaches-cache once Group
 * is enrolled in `hint-games.ts`; this file covers the Group-specific techniques
 * — the associativity placement, the identity-row/column fill journey, and the
 * identity-hidden identity-mark elimination — which the shared first-leaf preset
 * (6×6 Normal, identity shown) never exercises.
 */

import { describe, expect, it } from "vitest";
import type { HintStep } from "../../engine/game.ts";
import { randomNew } from "../../random/index.ts";
import { groupGame } from "./index.ts";
import { type HintReason, recordGroupDeductions } from "./solver.ts";
import {
  DIFF_EXTREME,
  type GroupMove,
  type GroupParams,
  type GroupState,
  newState,
} from "./state.ts";

const NORMAL: GroupParams = { w: 6, diff: 1, id: true };
const HARD_HIDDEN: GroupParams = { w: 8, diff: 2, id: false };

function board(p: GroupParams, seed: string): GroupState {
  const { desc } = groupGame.newDesc(p, randomNew(seed));
  return newState(p, desc);
}

/** Walk hints from `state`, applying each plan's first step, collecting the
 * narrations seen and whether the board reached solved. */
function walk(
  p: GroupParams,
  seed: string,
): { texts: string[]; solved: boolean; states: GroupState[] } {
  let state = board(p, seed);
  const texts: string[] = [];
  const states: GroupState[] = [state];
  for (let i = 0; i < 500 && groupGame.status(state) === "ongoing"; i++) {
    const res = groupGame.hint?.(state, undefined);
    if (!res?.ok) break;
    for (const s of res.steps) texts.push(s.explanation);
    state = groupGame.executeMove(state, res.steps[0].move);
    states.push(state);
  }
  return { texts, solved: groupGame.status(state) === "solved", states };
}

describe("group hint — recorded deductions", () => {
  it("records each Group technique across generated boards", () => {
    const kinds = new Set<string>();
    for (const [p, seeds] of [
      [NORMAL, ["a1", "a2", "a3", "a4", "a5"]],
      [HARD_HIDDEN, ["h1", "h2", "h3", "h4", "h5", "h6"]],
    ] as const) {
      for (const seed of seeds) {
        const state = board(p, seed);
        const ops = recordGroupDeductions(
          state.grid.slice(),
          p.w,
          Math.min(p.diff, DIFF_EXTREME),
        );
        for (const op of ops) kinds.add((op.reason as HintReason).kind);
      }
    }
    // Group's own three deductions plus the generic Latin single are all fired.
    expect(kinds.has("associativity")).toBe(true);
    expect(kinds.has("identityFill")).toBe(true);
    expect(kinds.has("identityElim")).toBe(true);
    expect(kinds.has("single")).toBe(true);
  });

  it("an associativity record names its triple and the forced fourth product", () => {
    // Find any board whose plan surfaces an associativity step, and assert the
    // narration states the law with concrete element letters.
    let text: string | undefined;
    for (const seed of ["a1", "a2", "a3", "a4", "a5", "a6"]) {
      const { texts } = walk(NORMAL, seed);
      text = texts.find((t) => /in any group/.test(t));
      if (text) break;
    }
    expect(text).toBeDefined();
    // "…Because (a·b)·c = a·(b·c) in any group, <fourth> must also be <v>."
    expect(text).toMatch(/You've filled .+·.+ = .+, .+·.+ = .+ and/);
    expect(text).toMatch(/Because \(.+·.+\)·.+ = .+·\(.+·.+\) in any group/);
    expect(text).toMatch(/must also be [a-z]\./);
  });
});

describe("group hint — plan solves boards", () => {
  it("solves a Normal (identity-shown) board by following hints", () => {
    const { solved } = walk(NORMAL, "solve-normal");
    expect(solved).toBe(true);
  });

  it("solves an identity-hidden Hard board, teaching an identity-mark elimination", () => {
    // The identity-hidden Hard tier is the one that exercises solverHard — the
    // design D5 risk the shared first-leaf resume can't reach.
    let sawElim = false;
    let anySolved = false;
    for (const seed of ["h1", "h2", "h3", "h4", "h5", "h6"]) {
      const { texts, solved } = walk(HARD_HIDDEN, seed);
      if (solved) anySolved = true;
      if (texts.some((t) => /can't be the identity/.test(t)) && solved) {
        sawElim = true;
        break;
      }
    }
    expect(anySolved).toBe(true);
    expect(sawElim).toBe(true);
  });

  it("a hint resumes from a self-played mid-game position (identity-hidden)", () => {
    // Reach a mid-game position by following ~1/3 of a solve, then confirm a
    // fresh hint still makes progress and drives to solved.
    const { states } = walk(HARD_HIDDEN, "h2");
    const mid = states[Math.floor(states.length / 3)];
    let state = mid;
    let progressed = false;
    for (let i = 0; i < 500 && groupGame.status(state) === "ongoing"; i++) {
      const res = groupGame.hint?.(state, undefined);
      expect(res?.ok, `refused mid-game after ${i} moves`).toBe(true);
      if (!res?.ok) break;
      state = groupGame.executeMove(state, res.steps[0].move);
      progressed = true;
    }
    expect(progressed).toBe(true);
    expect(groupGame.status(state)).toBe("solved");
  });
});

describe("group hint — refusals", () => {
  it("refuses on a solved board", () => {
    const orig = board(NORMAL, "refuse-solved");
    const sr = groupGame.solve?.(orig, orig, undefined);
    expect(sr?.ok).toBe(true);
    if (!sr?.ok) return;
    const solved = groupGame.executeMove(orig, sr.move);
    const res = groupGame.hint?.(solved, undefined);
    expect(res?.ok).toBe(false);
  });

  it("refuses on a board with a mistake (and findMistakes flags it)", () => {
    const orig = board(NORMAL, "refuse-mistake");
    const sr = groupGame.solve?.(orig, orig, undefined);
    if (!sr?.ok || sr.move.type !== "solve") return;
    const soln = sr.move.grid;
    // Fill the first empty cell with a *wrong* value.
    const w = orig.w;
    let target = -1;
    for (let i = 0; i < w * w; i++)
      if (!orig.immutable[i]) {
        target = i;
        break;
      }
    expect(target).toBeGreaterThanOrEqual(0);
    const wrong = (soln[target] % w) + 1; // any value != the solution's
    const bad = groupGame.executeMove(orig, {
      type: "set",
      cells: [{ x: target % w, y: (target / w) | 0 }],
      n: wrong,
    });
    expect(groupGame.findMistakes?.(bad).length ?? 0).toBeGreaterThan(0);
    const res = groupGame.hint?.(bad, undefined);
    expect(res?.ok).toBe(false);
  });
});

describe("group hint — keepTrack", () => {
  it("a placement move completes a set step; a wrong one drops the plan", () => {
    const state = board(NORMAL, "kt-place");
    const res = groupGame.hint?.(state, undefined);
    expect(res?.ok).toBe(true);
    if (!res?.ok) return;
    // Find the first placement step in the plan.
    const step = res.steps.find((s) => (s.move as GroupMove).type === "set");
    expect(step).toBeDefined();
    if (!step) return;
    const m = step.move as Extract<GroupMove, { type: "set" }>;
    const cell = m.cells[0];
    expect(
      groupGame.hintKeepTrack?.(
        { type: "set", cells: [{ x: cell.x, y: cell.y }], n: m.n },
        step,
        state,
      ),
    ).toBe("completed");
    // A different value at the same cell is off-plan.
    expect(
      groupGame.hintKeepTrack?.(
        { type: "set", cells: [{ x: cell.x, y: cell.y }], n: (m.n % state.w) + 1 },
        step,
        state,
      ),
    ).toBe("off");
  });

  it("a pencil toggle clearing a strike mark tracks the plan", () => {
    // Reach a pencilStrike step on an identity-hidden Hard board whose first mark
    // is live against the current board, then follow it with a right-click toggle.
    let found: { state: GroupState; step: HintStep<GroupMove> } | null = null;
    for (const seed of ["h1", "h2", "h3", "h4", "h5"]) {
      let s = board(HARD_HIDDEN, seed);
      for (let i = 0; i < 500 && groupGame.status(s) === "ongoing" && !found; i++) {
        const res = groupGame.hint?.(s, undefined);
        if (!res?.ok) break;
        const strike = res.steps.find((st) => {
          const mv = st.move as GroupMove;
          if (mv.type !== "pencilStrike") return false;
          const k = mv.marks[0];
          return (s.pencil[k.y * s.w + k.x] & (1 << k.n)) !== 0;
        });
        if (strike) found = { state: s, step: strike };
        else s = groupGame.executeMove(s, res.steps[0].move);
      }
      if (found) break;
    }
    expect(found).not.toBeNull();
    if (!found) return;
    const mv = found.step.move as Extract<GroupMove, { type: "pencilStrike" }>;
    const k = mv.marks[0];
    const verdict = groupGame.hintKeepTrack?.(
      { type: "pencil", cells: [{ x: k.x, y: k.y }], n: k.n },
      found.step,
      found.state,
    );
    // Clearing one of several marks is onTrack; the sole mark would be completed.
    expect(verdict === "onTrack" || verdict === "completed").toBe(true);
  });

  it("a Mark-all completes a populate step", () => {
    // Force a populate step by taking an identity-hidden Hard plan that needs it.
    for (const seed of ["h1", "h2", "h3", "h4", "h5"]) {
      let s = board(HARD_HIDDEN, seed);
      for (let i = 0; i < 500 && groupGame.status(s) === "ongoing"; i++) {
        const res = groupGame.hint?.(s, undefined);
        if (!res?.ok) break;
        const pop = res.steps.find((st) => (st.move as GroupMove).type === "pencilAll");
        if (pop) {
          expect(groupGame.hintKeepTrack?.({ type: "pencilAll" }, pop, s)).toBe(
            "completed",
          );
          expect(
            groupGame.hintKeepTrack?.(
              { type: "set", cells: [{ x: 0, y: 0 }], n: 1 },
              pop,
              s,
            ),
          ).toBe("off");
          return;
        }
        s = groupGame.executeMove(s, res.steps[0].move);
      }
    }
    throw new Error("no populate step reached on any identity-hidden Hard seed");
  });
});

src/native/games/sixteen/sixteen-midend..source:
import { describe, expect, it } from "vitest";
import type { ChangeNotification } from "../../../puzzle/types.ts";
import { Midend } from "../../engine/midend.ts";
import {
  CURSOR_DOWN,
  CURSOR_LEFT,
  CURSOR_RIGHT,
  CURSOR_SELECT,
  LEFT_BUTTON,
  LEFT_DRAG,
  LEFT_RELEASE,
} from "../../engine/pointer.ts";
import { sixteenGame } from "./index.ts";
import type { SixteenMove } from "./state.ts";

/** The midend stores the hint plan privately; tests reach in to
 * assert the stored plan's shape and current step. */
interface PrivateHintView {
  activeHint: { steps: { move: SixteenMove }[]; index: number } | null;
  animLength: number;
}

function harness(game: typeof sixteenGame = sixteenGame) {
  const notes: ChangeNotification[] = [];
  let redraws = 0;
  const m = new Midend(game);
  m.setCallbacks(
    (n) => notes.push(n),
    () => {},
    () => {
      redraws++;
    },
  );
  const last = <T extends ChangeNotification["type"]>(type: T) =>
    [...notes].reverse().find((n) => n.type === type);
  const state = () =>
    last("game-state-change") as
      | Extract<ChangeNotification, { type: "game-state-change" }>
      | undefined;
  return { m, notes, state, redraws: () => redraws, last };
}

// --- lifecycle --------------------------------------------------------

describe("Sixteen midend integration — lifecycle", () => {
  it("newGame emits state notifications", () => {
    const h = harness();
    h.m.newGame();
    const types = new Set(h.notes.map((n) => n.type));
    expect(types).toContain("game-id-change");
    expect(types).toContain("params-change");
    expect(types).toContain("game-state-change");
    expect(h.state()?.status).toBe("ongoing");
  });

  it("restartGame resets to initial state", () => {
    const h = harness();
    h.m.newGame();
    const initialMoveCount = h.state()?.currentMove ?? 0;
    // Show cursor first, then make a move.
    h.m.processInput(0, 0, CURSOR_SELECT);
    h.m.processInput(0, 0, 0x2000 | CURSOR_RIGHT); // shift + cursor_right
    const afterMove = h.state()?.currentMove ?? 0;
    expect(afterMove).toBeGreaterThan(initialMoveCount);
    h.m.restartGame();
    expect(h.state()?.currentMove).toBe(0);
  });

  it("newGameFromId creates a game from a known id", () => {
    const h = harness();
    const err = h.m.newGameFromId("3x3:1,2,3,4,5,6,7,8,9");
    expect(err).toBeUndefined();
    expect(h.state()?.status).toBe("ongoing");
  });
});

// --- keyboard input ---------------------------------------------------

describe("Sixteen midend integration — keyboard input", () => {
  it("cursor keys move the cursor (UI update)", () => {
    const h = harness();
    h.m.newGame();
    // Show cursor.
    h.m.processInput(0, 0, CURSOR_SELECT);
    // Move cursor right.
    h.m.processInput(0, 0, CURSOR_RIGHT);
    // Just verify no crash — the cursor position is internal UI state.
  });

  it("shift+cursor makes a slide move", () => {
    const h = harness();
    h.m.newGame();
    const before = h.state()?.currentMove ?? 0;
    // Show cursor first.
    h.m.processInput(0, 0, CURSOR_SELECT);
    // Shift+cursor_right = slide row right.
    h.m.processInput(0, 0, 0x2000 | CURSOR_RIGHT);
    const after = h.state()?.currentMove ?? 0;
    expect(after).toBeGreaterThan(before);
  });
});

// --- undo -------------------------------------------------------------

describe("Sixteen midend integration — undo", () => {
  it("undo reverses a move", () => {
    const h = harness();
    h.m.newGame();
    const before = h.state()?.currentMove ?? 0;
    // Show cursor and make a move.
    h.m.processInput(0, 0, CURSOR_SELECT);
    h.m.processInput(0, 0, 0x2000 | CURSOR_RIGHT);
    const after = h.state()?.currentMove ?? 0;
    expect(after).toBeGreaterThan(before);
    // Undo.
    h.m.undo();
    expect(h.state()?.currentMove).toBe(before);
    expect(h.state()?.canUndo).toBe(false);
  });
});

// --- presets ----------------------------------------------------------

describe("Sixteen midend integration — presets", () => {
  it("getPresets returns 5 presets", () => {
    const h = harness();
    const p = h.m.getPresets();
    expect(p).toHaveLength(5);
  });

  it("setParams changes the game size", () => {
    const h = harness();
    const err = h.m.setParams("3x3");
    expect(err).toBeUndefined();
    h.m.newGame();
    // The game should now be 3×3 — check params-change notification.
    const params = h.last("params-change") as
      | Extract<ChangeNotification, { type: "params-change" }>
      | undefined;
    expect(params?.params).toContain("3x3");
  });
});

describe("Sixteen midend integration — drag-to-slide support", () => {
  it("dragging row 0 to the right by more than half a tile moves it", () => {
    const h = harness();
    h.m.newGame();
    const before = h.state()?.currentMove ?? 0;

    // Press on tile (0, 0), which is at x = 72, y = 72
    h.m.processInput(72, 72, LEFT_BUTTON);

    // Drag right by 30 pixels (72 + 30 = 102), which is more than half of 48 (24 pixels)
    h.m.processInput(102, 72, LEFT_DRAG);

    // Release the drag
    h.m.processInput(102, 72, LEFT_RELEASE);

    const after = h.state()?.currentMove ?? 0;
    expect(after).toBe(before + 1);
  });

  it("dragging row 0 to the right by less than half a tile does not move it", () => {
    const h = harness();
    h.m.newGame();
    const before = h.state()?.currentMove ?? 0;

    // Press on tile (0, 0)
    h.m.processInput(72, 72, LEFT_BUTTON);

    // Drag right by 10 pixels (72 + 10 = 82), which is less than half of 48 (24 pixels)
    h.m.processInput(82, 72, LEFT_DRAG);

    // Release the drag
    h.m.processInput(82, 72, LEFT_RELEASE);

    const after = h.state()?.currentMove ?? 0;
    expect(after).toBe(before);
  });
});

describe("Sixteen midend integration — hint persistence", () => {
  it("keeps target cell highlighted as long as user is on-track, and clears on finish or unrelated move", () => {
    const h = harness();
    h.m.newGameFromId("3x3:3,1,2,4,5,6,7,8,9"); // row 0 is shifted left by 1

    // Request a hint
    const exp = h.m.hint();
    expect(exp).toBeUndefined(); // Returns undefined on success

    // activeHint should hold a stored plan
    const mPrivate = h.m as unknown as PrivateHintView;
    expect(mPrivate.activeHint).not.toBeNull();

    // Verify the current step slides row 0
    const stepMove = mPrivate.activeHint?.steps[mPrivate.activeHint.index].move;
    if (stepMove?.type === "slide") {
      expect(stepMove.axis).toBe("row");
      expect(stepMove.index).toBe(0);
    } else {
      expect.fail("Expected the current hint step's move to be a slide");
    }

    // Make an on-track move: slide row 0 right by 1
    h.m.processInput(0, 0, CURSOR_SELECT); // Show cursor first at (0, 0)
    h.m.processInput(0, 0, 0x2000 | CURSOR_RIGHT); // Shift+CURSOR_RIGHT: slide row 0 right

    // Since it's on-track and hasn't landed the tile yet, the plan should STILL be active!
    expect(mPrivate.activeHint).not.toBeNull();

    // Now make an unrelated move: slide row 1 right.
    h.m.processInput(0, 0, CURSOR_DOWN); // Move cursor down to row 1
    h.m.processInput(0, 0, 0x2000 | CURSOR_RIGHT); // Shift+CURSOR_RIGHT: slide row 1 right

    // Now activeHint should be cleared because we manipulated an unrelated row!
    expect(mPrivate.activeHint).toBeNull();
  });

  it("keeps target cell highlighted as long as user is on-track, and clears when the hint is applied", () => {
    const h = harness();
    h.m.newGameFromId("3x3:3,1,2,4,5,6,7,8,9"); // row 0 is shifted left by 1

    // Request a hint
    const exp = h.m.hint();
    expect(exp).toBeUndefined(); // Returns undefined on success

    // activeHint should hold a stored plan
    const mPrivate = h.m as unknown as PrivateHintView;
    expect(mPrivate.activeHint).not.toBeNull();

    // Slide row 0 right by 1 step.
    h.m.processInput(0, 0, CURSOR_SELECT); // Show cursor first at (0, 0)
    h.m.processInput(0, 0, 0x2000 | CURSOR_RIGHT); // Shift+CURSOR_RIGHT: slide row 0 right

    // Still active
    expect(mPrivate.activeHint).not.toBeNull();

    // Slide row 0 right by 1 step again. Now tile 1 reaches the step's
    // target, completing the (single-step) plan: cleared.
    h.m.processInput(0, 0, 0x2000 | CURSOR_RIGHT); // Shift+CURSOR_RIGHT: slide row 0 right

    expect(mPrivate.activeHint).toBeNull();
  });

  it("a multi-leg journey stays displayed through its legs (owner board, 2026-06-10)", () => {
    // Owner-reported: landing the tile on the intermediate target made
    // the hint "reset" — the display hid mid-journey. A journey is one
    // hint: its flagged continuation steps must stay displayed; only
    // the step after the journey waits for a fresh request.
    const h = harness();
    h.m.newGameFromId(
      "5x5:1,2,3,4,6,7,13,8,9,5,11,12,18,14,15,16,17,24,19,20,21,22,23,10,25",
    );
    const banner = () => {
      const n = h.last("status-bar-change") as
        | Extract<ChangeNotification, { type: "status-bar-change" }>
        | undefined;
      return n?.activeHintExplanation;
    };
    expect(h.m.hint()).toBeUndefined();
    expect(banner()).toBe(
      "Working on tile 6: move it to column 4, then row 2 (setting up)",
    );

    // Leg 1: slide row 0 left by 1 (cursor at (0,0), shift+left).
    h.m.processInput(0, 0, CURSOR_SELECT);
    h.m.processInput(0, 0, 0x2000 | CURSOR_LEFT);
    // The journey continues: leg 2 is displayed without a new request.
    expect(banner()).toBe("Working on tile 6: then to row 2, then column 5");

    // Leg 2: slide column 3 down by 1 (cursor right ×3, shift+down).
    h.m.processInput(0, 0, CURSOR_RIGHT);
    h.m.processInput(0, 0, CURSOR_RIGHT);
    h.m.processInput(0, 0, CURSOR_RIGHT);
    h.m.processInput(0, 0, 0x2000 | CURSOR_DOWN);
    expect(banner()).toBe("Working on tile 6: then to column 5");

    // Leg 3 ends the journey: slide row 1 right by 1.
    h.m.processInput(0, 0, CURSOR_DOWN);
    h.m.processInput(0, 0, 0x2000 | CURSOR_RIGHT);
    // Tile 6 is home; the next (unrelated) step waits to be asked for.
    expect(banner()).toBeUndefined();
    const mPrivate = h.m as unknown as PrivateHintView;
    expect(mPrivate.activeHint).not.toBeNull();
  });
});

// --- executeHint ------------------------------------------------------

describe("Sixteen midend integration — executeHint auto-play", () => {
  it("sequential executeHint calls solve a generated 3x3 board", () => {
    const h = harness();
    h.m.setParams("3x3");
    h.m.newGame();
    expect(h.state()?.status).toBe("ongoing");

    let steps = 0;
    const maxSteps = 100;
    while (h.state()?.status === "ongoing" && steps < maxSteps) {
      const hintErr = h.m.executeHint();
      expect(hintErr).toBeUndefined();
      steps++;
    }

    expect(h.state()?.status).toBe("solved");
    expect(steps).toBeGreaterThan(0);
  });

  it("keeps the executed step displayed through the animation, then advances", () => {
    const h = harness();
    h.m.setParams("3x3");
    h.m.newGame();
    expect(h.state()?.status).toBe("ongoing");

    const err = h.m.executeHint();
    expect(err).toBeUndefined();

    const mPrivate = h.m as unknown as PrivateHintView;
    expect(mPrivate.activeHint).not.toBeNull();
    const planLength = mPrivate.activeHint?.steps.length ?? 0;
    expect(planLength).toBeGreaterThan(0);
    expect(mPrivate.activeHint?.index).toBe(0);

    // Hint-executed moves animate in slow motion, stretched to the uniform
    // HINT_ANIM_S (1.0s) regardless of the game's own ANIM_TIME (0.4s here).
    expect(mPrivate.animLength).toBeCloseTo(1.0);

    // Still animating well past the normal 0.4s settle point — the
    // executed step stays on display, describing the move in flight.
    h.m.timer(0.45);
    expect(mPrivate.activeHint?.index).toBe(0);

    // Settle the stretched animation (total 1.05 > 1.0): the plan
    // advances so the *next* step is previewed during the auto-play
    // rest period (or clears when the plan had a single step).
    h.m.timer(0.6);
    if (planLength > 1) {
      expect(mPrivate.activeHint?.index).toBe(1);
    } else {
      expect(mPrivate.activeHint).toBeNull();
    }

    // A manual move is NOT stretched: it settles at the game's own 0.4s.
    h.m.processInput(0, 0, CURSOR_SELECT);
    h.m.processInput(0, 0, 0x2000 | CURSOR_RIGHT); // shift + cursor_right
    expect(mPrivate.animLength).toBeCloseTo(0.4);
  });

  // The bidirectional search itself takes a few seconds when it
  // engages — that is the very cost this test pins to once-per-plan.
  // Slow by nature (the bidirectional search below), and deliberately not
  // clock-gated: the guarantee is the mechanism — hintCalls === 1 — not the
  // milliseconds. One generous ceiling lives in vitest.config.ts.
  it("crosses the two-swap 5x5 endgame on one stored plan (no per-step recompute)", () => {
    // Regression guard for the cost model: the exact bidirectional
    // fallback (~0.5-2s when it engages) must run once for the whole
    // endgame, not once per auto-played step — and executing one
    // stored plan verbatim is also what eliminates replan wobble.
    let hintCalls = 0;
    const countingGame: typeof sixteenGame = {
      ...sixteenGame,
      hint: (s) => {
        hintCalls += 1;
        const base = sixteenGame.hint;
        if (!base) throw new Error("sixteenGame.hint missing");
        return base(s);
      },
    };
    const h = harness(countingGame);
    // Tiles 1↔6 and 16↔20 swapped, everything else solved: a strict
    // local minimum the forward search cannot cross.
    const err = h.m.newGameFromId(
      "5x5:6,2,3,4,5,1,7,8,9,10,11,12,13,14,15,20,17,18,19,16,21,22,23,24,25",
    );
    expect(err).toBeUndefined();

    let guard = 0;
    while (h.state()?.status === "ongoing" && guard < 30) {
      expect(h.m.executeHint()).toBeUndefined();
      h.m.timer(1.5); // settle the slow-motion animation (1.0s) + flash
      guard++;
    }
    expect(h.state()?.status).toBe("solved");
    expect(hintCalls).toBe(1);
  });
});

