      }
    }
  });
});

describe("Sixteen hint track and direction fixes", () => {
  function recordingDrawing() {
    const ops: Array<{ op: string; colour?: number }> = [];
    const rec = (op: string, colour?: number) => ops.push({ op, colour });
    const dr: GameDrawing = {
      startDraw: () => rec("startDraw"),
      endDraw: () => rec("endDraw"),
      drawUpdate: () => rec("drawUpdate"),
      clip: () => rec("clip"),
      unclip: () => rec("unclip"),
      drawRect: (_r, c) => rec("drawRect", c),
      drawLine: (_a, _b, c) => rec("drawLine", c),
      drawPolygon: (_p, f) => rec("drawPolygon", f),
      drawCircle: (_p, _r, f) => rec("drawCircle", f),
      drawText: (_p, _o, c) => rec("drawText", c),
      blitterNew: () => ({}),
      blitterFree: () => rec("blitterFree"),
      blitterSave: () => rec("blitterSave"),
      blitterLoad: () => rec("blitterLoad"),
    };
    return { dr, ops };
  }

  it("always overrides arrow direction to point in-grid (avoiding wrapping arrow)", () => {
    // Case 1: tile 1 at col 0, target at col 2.
    // Recommended move was left (delta: -1), but in-grid direction is right (delta: 1).
    const s1 = solvedState(3, 3); // Tile 1 is at index 0 (col 0, row 0).
    const ui1 = sixteenGame.newUi(s1);
    const ds1 = sixteenGame.newDrawState?.(s1);
    expect(ds1).toBeDefined();
    if (!ds1) return;
    sixteenGame.setTileSize?.(ds1, 32);

    const activeHint1: HintStep<SixteenMove, SixteenHintHighlights> = {
      move: { type: "slide", axis: "row", index: 0, delta: -1 },
      explanation: "",
      highlights: {
        tile: 1,
        targetPos: 2, // col 2, row 0
      },
    };

    const { dr: dr1 } = recordingDrawing();
    sixteenGame.redraw?.(dr1, ds1, null, s1, 1, ui1, 0, 0, activeHint1);
    // Since curCol (0) < targetCol (2), it should point right (ds1.hintArrowX = 3)
    const ds1Typed = ds1 as unknown as {
      hintArrowX: number | null;
      hintArrowY: number | null;
    };
    expect(ds1Typed.hintArrowX).toBe(3);
    expect(ds1Typed.hintArrowY).toBe(0);

    // Case 2: tile 1 at col 2, target at col 0.
    // Recommended move was right (delta: 1), but in-grid direction is left (delta: -1).
    const s2 = solvedState(3, 3);
    // Move tile 1 to index 2 (col 2, row 0)
    s2.tiles[0] = 3;
    s2.tiles[1] = 2;
    s2.tiles[2] = 1;

    const ui2 = sixteenGame.newUi(s2);
    const ds2 = sixteenGame.newDrawState?.(s2);
    expect(ds2).toBeDefined();
    if (!ds2) return;
    sixteenGame.setTileSize?.(ds2, 32);

    const activeHint2: HintStep<SixteenMove, SixteenHintHighlights> = {
      move: { type: "slide", axis: "row", index: 0, delta: 1 },
      explanation: "",
      highlights: {
        tile: 1,
        targetPos: 0, // col 0, row 0
      },
    };

    const { dr: dr2 } = recordingDrawing();
    sixteenGame.redraw?.(dr2, ds2, null, s2, 1, ui2, 0, 0, activeHint2);
    // Since curCol (2) > targetCol (0), it should point left (ds2.hintArrowX = -1)
    const ds2Typed = ds2 as unknown as {
      hintArrowX: number | null;
      hintArrowY: number | null;
    };
    expect(ds2Typed.hintArrowX).toBe(-1);
    expect(ds2Typed.hintArrowY).toBe(0);
  });

  it("hintKeepTrack classifies moves against the current step", () => {
    const step = (): HintStep<SixteenMove, SixteenHintHighlights> => ({
      move: { type: "slide", axis: "row", index: 0, delta: 2 },
      explanation: "",
      highlights: {
        tile: 1,
        targetPos: 2,
      },
    });

    // Case 1: same line, target not reached yet — onTrack, and the
    // step's move shrinks in place to the remaining in-grid distance
    // (tile 1: col 0 → col 1, one more column to go).
    const s = solvedState(3, 3); // Tile 1 is at index 0 (col 0, row 0).
    const m1: SixteenMove = { type: "slide", axis: "row", index: 0, delta: 1 };
    const h1 = step();
    expect(sixteenGame.hintKeepTrack?.(m1, h1, s)).toBe("onTrack");
    expect(h1.move).toEqual({ type: "slide", axis: "row", index: 0, delta: 1 });

    // Case 2: same line and the move lands the tile on the target —
    // completed.
    const sWithTileAt1 = solvedState(3, 3);
    sWithTileAt1.tiles[0] = 2;
    sWithTileAt1.tiles[1] = 1; // Tile 1 is at index 1
    const m2: SixteenMove = { type: "slide", axis: "row", index: 0, delta: 1 };
    expect(sixteenGame.hintKeepTrack?.(m2, step(), sWithTileAt1)).toBe("completed");

    // Case 3: a different line (unrelated move) — off.
    const m3: SixteenMove = { type: "slide", axis: "row", index: 1, delta: 1 };
    expect(sixteenGame.hintKeepTrack?.(m3, step(), s)).toBe("off");

    // Case 4: same line but sliding *away* — still onTrack, with the
    // remaining delta grown to compensate (tile 1: col 0 → col 2 is
    // the target… sliding left puts it at col 2 via wrap, which IS
    // the target on a 3-wide row, so use a 4-wide board instead).
    const s4 = solvedState(4, 4); // tile 1 at col 0
    const h4: HintStep<SixteenMove, SixteenHintHighlights> = {
      move: { type: "slide", axis: "row", index: 0, delta: 2 },
      explanation: "",
      highlights: { tile: 1, targetPos: 2 },
    };
    const m4: SixteenMove = { type: "slide", axis: "row", index: 0, delta: -1 };
    expect(sixteenGame.hintKeepTrack?.(m4, h4, s4)).toBe("onTrack");
    // tile 1 now at col 3; target col 2 ⇒ remaining in-grid delta -1.
    expect(h4.move).toEqual({ type: "slide", axis: "row", index: 0, delta: -1 });
  });
});

describe("the hint marks while the hinted slide animates", () => {
  // Netslide's owner-reported defect class (edadec1): once the hinted slide
  // starts animating, a mark on the *moving tile* must ride the slide and a
  // mark on a *fixed cell* must stay put — the midend advances the plan only
  // at animation end, so the displayed step's indices refer to the board the
  // move left behind. Sixteen holds both properties by construction (the
  // tile mark is keyed by tile *number*, so it follows the tile through the
  // interpolated draw; the target border is drawn after the tile loop at the
  // cell's own coordinates). These tests pin that down at an actual
  // mid-slide frame, which the settled-frame snapshots cannot see.
  const TS = 48;
  const BORDER = TS; // sixteen's border(ts) = ts
  const HW = Math.max(1, Math.floor(TS / 20)); // HIGHLIGHT_WIDTH_DIV = 20
  const px = (cell: number) => cell * TS + BORDER;

  interface Op {
    op: string;
    colour?: number;
    x?: number;
    y?: number;
    w?: number;
    h?: number;
  }

  function coordRecordingDrawing(): { dr: GameDrawing; ops: Op[] } {
    const ops: Op[] = [];
    const dr = {
      startDraw: () => {},
      endDraw: () => {},
      drawUpdate: () => {},
      clip: () => {},
      unclip: () => {},
      drawRect: (r: { x: number; y: number; w: number; h: number }, c: number) =>
        ops.push({ op: "rect", colour: c, x: r.x, y: r.y, w: r.w, h: r.h }),
      drawLine: () => {},
      drawPolygon: (p: { x: number; y: number }[], f: number) =>
        ops.push({ op: "polygon", colour: f, x: p[0].x, y: p[0].y }),
      drawCircle: () => {},
      drawText: (p: { x: number; y: number }, _o: unknown, c: number) =>
        ops.push({ op: "text", colour: c, x: p.x, y: p.y }),
      blitterNew: () => ({}),
      blitterFree: () => {},
      blitterSave: () => {},
      blitterLoad: () => {},
    } as unknown as GameDrawing;
    return { dr, ops };
  }

  /** A mid-slide frame of the hinted move, on the first board whose hint step
   * slides its tile one straight (unwrapped) cell and aims the target border
   * at a cell on the line being slid — the only case where a border wrongly
   * painted in the shifted tile pass would visibly move. */
  function animatingFrame() {
    for (let i = 0; i < 60; i++) {
      const rng = randomNew(`hint-anim-${i}`);
      const params = defaultParams();
      const { desc } = newDesc(params, rng);
      const state = newState(params, desc);
      const res = sixteenGame.hint?.(state);
      if (!res?.ok) continue;
      const step = res.steps[0];
      if (step.move.type !== "slide") continue;
      const m = step.move;
      const hl = step.highlights as SixteenHintHighlights;
      if (hl.ultimatePos !== undefined) continue; // want the solid target border
      const after = executeMove(state, m);
      const w = state.w;
      const from = state.tiles.indexOf(hl.tile);
      const to = after.tiles.indexOf(hl.tile);
      // The hinted tile must move without wrapping round the torus, so the
      // expected mid-slide position is closed-form.
      const straight =
        m.axis === "row"
          ? Math.floor(to / w) === Math.floor(from / w) &&
            (to % w) - (from % w) === m.delta
          : to % w === from % w &&
            Math.floor(to / w) - Math.floor(from / w) === m.delta;
      if (!straight) continue;
      const onLine =
        m.axis === "row"
          ? Math.floor(hl.targetPos / w) === m.index
          : hl.targetPos % w === m.index;
      if (!onLine) continue;

      const ds = sixteenGame.newDrawState?.(state);
      if (!ds) throw new Error("no draw state");
      sixteenGame.setTileSize?.(ds, TS);
      const ui = sixteenGame.newUi(state);

      // Paint the still pre-move frame first, so the cache is warm exactly
      // as in the app when the hinted slide begins.
      sixteenGame.redraw?.(
        coordRecordingDrawing().dr,
        ds,
        null,
        state,
        1,
        ui,
        0,
        0,
        step,
      );

      // Halfway through the slide.
      const anim = sixteenGame.animLength?.(state, after, 1, ui) ?? 0;
      const { dr, ops } = coordRecordingDrawing();
      sixteenGame.redraw?.(dr, ds, state, after, 1, ui, anim / 2, 0, step);
      return { state, after, m, hl, from, ops };
    }
    throw new Error(
      "no board in 60 gave a straight hinted slide aimed along its own line",
    );
  }

  it("carries the tile mark along with the tile it is marking", () => {
    const { state, m, from, ops } = animatingFrame();
    const w = state.w;

    // Half a slide in, the tile sits half a tile from its origin toward its
    // landing cell; the hint fill is drawTile's centre rect, inset by HW.
    const shift = Math.round(0.5 * TS * m.delta);
    const ex = px(from % w) + (m.axis === "row" ? shift : 0) + HW;
    const ey = px(Math.floor(from / w)) + (m.axis === "column" ? shift : 0) + HW;

    const fills = ops.filter(
      (o) =>
        o.op === "rect" && o.colour === 4 && o.w === TS - 2 * HW && o.h === TS - 2 * HW,
    );
    expect(
      fills.length,
      "the hinted tile is not painted in the hint colour",
    ).toBeGreaterThan(0);
    for (const f of fills) {
      expect({ x: f.x, y: f.y }).toEqual({ x: ex, y: ey });
    }
  });

  it("leaves the target border where the target cell is", () => {
    const { state, hl, ops } = animatingFrame();
    const w = state.w;

    // The target is a *cell*; the line slides under it. The solid border's
    // top edge is a full-width, 3px-tall rect at the cell's own corner.
    const top = ops.find(
      (o) => o.op === "rect" && o.colour === 4 && o.w === TS && o.h === 3,
    );
    expect(top, "the target cell is not outlined at all").toBeDefined();
    expect(top).toMatchObject({
      x: px(hl.targetPos % w),
      y: px(Math.floor(hl.targetPos / w)),
    });
  });
});

src/native/games/towers/towers-different.source:
/**
 * Gated C-vs-TS differential for the Towers port. Reads the committed fixture
 * recorded from upstream towers.c (puzzles/auxiliary/towers-trace.c) and
 * asserts:
 *
 *  1. TS `newTowersDesc` over the same seed reproduces the C desc
 *     byte-for-byte — the whole generation chain (Latin square → clue
 *     derivation → solver-gated removal) is a faithful port and the RNG is
 *     bit-identical, so the streams must agree exactly.
 *  2. The TS solver grades the C-generated board at the C-recorded difficulty
 *     (and does not solve it one level below).
 *
 * Regenerate the fixture (while towers.c still exists):
 *   cmake -B build/native -S puzzles -DUSE_TS_RANDOM=0
 *   (cd build/native && make towers-trace)
 *   build/native/auxiliary/towers-trace \
 *     > src/native/games/towers/__fixtures__/towers-c-reference.json
 */
import { describe, expect, it } from "vitest";
import { describeDescDifferential } from "../../engine/testing/differential.ts";
import cReference from "./__fixtures__/towers-c-reference.json" with { type: "json" };
import { newTowersDesc } from "./generator.ts";
import { DIFF_AMBIGUOUS, DIFF_IMPOSSIBLE, solveTowers } from "./solver.ts";
import { diffFromLevel, newState, type TowersParams } from "./state.ts";

interface Fixture {
  w: number;
  diff: number;
  seed: string;
  desc: string;
  solverDiff: number;
}

const data = cReference as { fixtures: Fixture[] };

const params = (f: Fixture): TowersParams => ({ w: f.w, diff: diffFromLevel(f.diff) });
const label = (f: Fixture) => `${f.w}d${f.diff} seed=${f.seed}`;

// 1. Byte-for-byte desc match — the shared faithful-generator bar.
describeDescDifferential<Fixture, TowersParams>({
  title: "Towers C-vs-TS differential — desc byte-match (gated)",
  fixtures: data.fixtures,
  label,
  params,
  newDesc: (p, rng) => newTowersDesc(p, rng),
});

// 2. Solver agreement — game-specific (decode + grade), inline.
describe("Towers C-vs-TS differential — solver agreement (gated)", () => {
  for (const f of data.fixtures) {
    const p = params(f);
    it(`${label(f)}: TS solver grades the C board at the recorded difficulty`, () => {
      const s = newState(p, f.desc);
      // Grades exactly at the recorded difficulty.
      const soln = Uint8Array.from(s.immutable);
      expect(solveTowers(f.w, s.clues, soln, f.solverDiff)).toBe(f.solverDiff);
      // Not solvable one level below.
      if (f.solverDiff > 0) {
        const below = Uint8Array.from(s.immutable);
        const r = solveTowers(f.w, s.clues, below, f.solverDiff - 1);
        expect(
          r === DIFF_IMPOSSIBLE || r === DIFF_AMBIGUOUS || r > f.solverDiff - 1,
        ).toBe(true);
      }
    });
  }
});

src/native/games/solo/solo-differential..source:
/**
 * Gated C-vs-TS differential for solo (`add-solo-ts-port`).
 *
 * Solo's generator is RNG-driven over the bit-identical `random.ts` with no
 * `qsort`/order-dependent step in any of the four variants' paths (design D5),
 * so a faithful port reproduces the C desc **byte-for-byte** for the same seed —
 * the strongest bar (playbook §4.3). On top of that we decode each C-published
 * board and assert the TS solver reaches the *same* (diff, kdiff) the C solver
 * recorded — the solver-gated minimiser depends on that exact agreement
 * (playbook §4.4), so it is the real proof the solver is faithful.
 *
 * Regenerate the frozen fixture while `puzzles/solo.c` still exists:
 *   cmake -B build/native -S puzzles -DUSE_TS_RANDOM=0
 *   (cd build/native && make solo-trace)
 *   build/native/auxiliary/solo-trace \
 *     > src/native/games/solo/__fixtures__/solo-c-reference.json
 */
import { describe, expect, it } from "vitest";
import { randomNew } from "../../random/index.ts";
import cReference from "./__fixtures__/solo-c-reference.json" with { type: "json" };
import { newSoloDesc } from "./generator.ts";
import { solveSolo } from "./solver.ts";
import {
  DIFF_KINTERSECT,
  DIFF_RECURSIVE,
  newState,
  type SoloParams,
  validateDesc,
} from "./state.ts";

interface Fixture {
  c: number;
  r: number;
  symm: number;
  diff: number;
  kdiff: number;
  xtype: boolean;
  killer: boolean;
  seed: string;
  desc: string;
  solverDiff: number;
  solverKdiff: number;
}

const data = cReference as { fixtures: Fixture[] };

function paramsOf(f: Fixture): SoloParams {
  return {
    c: f.c,
    r: f.r,
    symm: f.symm,
    diff: f.diff,
    kdiff: f.kdiff,
    xtype: f.xtype,
    killer: f.killer,
  };
}

function label(f: Fixture): string {
  const v = `${f.c}x${f.r}${f.xtype ? "X" : ""}${f.killer ? "K" : ""}`;
  return `${v} diff=${f.diff} kdiff=${f.kdiff} seed=${f.seed}`;
}

describe("solo differential (frozen C reference)", () => {
  for (const f of data.fixtures) {
    it(`${label(f)}: TS desc matches C byte-for-byte`, () => {
      const { desc } = newSoloDesc(paramsOf(f), randomNew(f.seed));
      expect(desc).toBe(f.desc);
      expect(validateDesc(paramsOf(f), desc)).toBeNull();
    });

    it(`${label(f)}: TS solver grades the published board as C did`, () => {
      const p = paramsOf(f);
      const s = newState(p, f.desc);
      const { diff, kdiff } = solveSolo(s, DIFF_RECURSIVE, DIFF_KINTERSECT);
      expect(diff).toBe(f.solverDiff);
      expect(kdiff).toBe(f.solverKdiff);
    });
  }
});

src/native/games/sticks/sticks-different.source:
/**
 * Gated C-vs-TS differential for Sticks (design D6 of add-sticks-ts-port):
 * for each frozen fixture recorded from `puzzles/unreleased/sticks.c` via
 * `puzzles/auxiliary/sticks-trace.c`, the TS `newSticksDesc` over the
 * bit-identical RNG must reproduce the C desc byte-for-byte.
 *
 * Because generation gates every fill attempt and every clue removal on
 * `sticksSolveGame`, one byte-match validates the generator (the symmetric
 * black placement, the fill/clue draws, the minimisation shuffle), the
 * contradiction solver's exact deductive power, and the run-length codec
 * together. The `extra` check also round-trips each C desc through
 * `validateDesc` + `newState` + `encodeDesc` (codec inverse property).
 */
import { expect } from "vitest";
import { describeDescDifferential } from "../../engine/testing/differential.ts";
import cReference from "./__fixtures__/sticks-c-reference.json" with { type: "json" };
import { newSticksDesc } from "./generator.ts";
import { encodeDesc, newState, type SticksParams, validateDesc } from "./state.ts";

interface Fixture {
  seed: string;
  desc: string;
  w: number;
  h: number;
  blackpc: number;
  symm: number;
}
const data = cReference as { fixtures: Fixture[] };

describeDescDifferential<Fixture, SticksParams>({
  title: "sticks differential (frozen C reference)",
  fixtures: data.fixtures,
  label: (f) => `${f.w}x${f.h}b${f.blackpc}s${f.symm} seed=${f.seed}`,
  params: (f) => ({ w: f.w, h: f.h, blackpc: f.blackpc, symm: f.symm }),
  newDesc: newSticksDesc,
  extra: (f, p) => {
    expect(validateDesc(p, f.desc)).toBeNull();
    const state = newState(p, f.desc);
    expect(encodeDesc(state.grid, state.numbers, p.w, p.h)).toBe(f.desc);
  },
});

src/native/games/keen/keen-differential..source:
/**
 * Gated byte-match differential for the Keen port.
 *
 * For each frozen C-reference fixture (each difficulty × the multiplication-only
 * flag), assert the TS generator reproduces the C desc byte-for-byte over the
 * bit-identical RNG, and that the TS solver grades the board at the same minimal
 * difficulty the C solver recorded. Faithful generation + a faithful solver
 * verdict — the strongest available bar (playbook §4.3/§4.4).
 *
 * Regenerate the fixture from `puzzles/auxiliary/keen-trace.c` (pure-C):
 *   cmake -B build/native -S puzzles -DUSE_TS_RANDOM=0
 *   (cd build/native && make keen-trace)
 *   build/native/auxiliary/keen-trace > __fixtures__/keen-c-reference.json
 */

import { describe, expect, it } from "vitest";
import { randomNew } from "../../random/index.ts";
import reference from "./__fixtures__/keen-c-reference.json" with { type: "json" };
import { newKeenDesc } from "./generator.ts";
import { solveKeen } from "./solver.ts";
import { diffFromLevel, type KeenParams, newState, validateDesc } from "./state.ts";

interface Fixture {
  w: number;
  diff: number;
  mult: boolean;
  seed: string;
  desc: string;
  solverDiff: number;
}

const FIXTURES = reference.fixtures as Fixture[];

function fixtureParams(f: Fixture): KeenParams {
  return { w: f.w, diff: diffFromLevel(f.diff), multiplicationOnly: f.mult };
}

describe("keen differential (byte-match + solver agreement)", () => {
  for (const f of FIXTURES) {
    const p = fixtureParams(f);
    const label = `${f.w}d${f.diff}${f.mult ? "m" : ""} (seed ${f.seed})`;

    it(`${label}: desc matches C byte-for-byte`, () => {
      const { desc } = newKeenDesc(p, randomNew(f.seed));
      expect(desc).toBe(f.desc);
      expect(validateDesc(p, desc)).toBeNull();
    });

    it(`${label}: TS solver grades at the C difficulty`, () => {
      const state = newState(p, f.desc);
      const soln = new Uint8Array(f.w * f.w);
      const ret = solveKeen(f.w, state.clues, soln, f.solverDiff);
      expect(ret).toBe(f.solverDiff);
    });
  }
});

src/native/games/unequal/unequal-hint.te.source:
/**
 * Unequal explained-hint tests.
 *
 * Tier 1 — the recording solver records a reason per technique in both modes and
 * its replayed placements complete a generated board; `hint` populates, strikes
 * (basic-Latin culls + the two-mode clue eliminations) and places with quality-bar
 * narration; refusal on solved / on mistakes; `hintKeepTrack` verdicts; resume to
 * solved in both modes. Tier 2.5 — a render-scenario snapshot of a clue-elimination
 * journey frame in each mode (struck candidate `COL_HINT`/strikethrough, evidence
 * `COL_HINT_CELL`, clue glyphs still drawn).
 */
import { describe, expect, it } from "vitest";
import {
  DEFAULT_BACKGROUND,
  renderScenario,
} from "../../engine/testing/render-scenario.ts";
import { randomNew } from "../../random/index.ts";
import { newUnequalDesc } from "./generator.ts";
import { unequalGame } from "./index.ts";
import { COL_HINT, COL_HINT_CELL, COL_PENCIL } from "./render.ts";
import { type HintReason, recordUnequalDeductions } from "./solver.ts";
import {
  DIFF_EXTREME,
  diffToLevel,
  encodeParams,
  newState,
  newUi,
  status,
  type UnequalMove,
  type UnequalParams,
  type UnequalState,
} from "./state.ts";

function gen(p: UnequalParams, seed: string) {
  const { desc, aux } = newUnequalDesc(p, randomNew(seed));
  return { p, desc, aux, st: newState(p, desc) };
}

// biome-ignore lint/suspicious/noExplicitAny: structural access to hint highlights/move in tests.
type AnyStep = any;

const UNEQ: UnequalParams = { order: 5, mode: "unequal", diff: "tricky" };
const ADJ: UnequalParams = { order: 5, mode: "adjacent", diff: "tricky" };

// --- tier 1: recording solver ----------------------------------------------

describe("unequal recording solver", () => {
  for (const [label, p, want] of [
    ["unequal", UNEQ, ["greater", "lesser"]],
    ["adjacent", ADJ, ["adjacent"]],
  ] as const) {
    it(`records ${label}-mode reasons and its placements complete the board`, () => {
      const { st } = gen(p, `rec-${label}`);
      const ops = recordUnequalDeductions(
        st.order,
        st.mode,
        st.clueFlags,
        Uint8Array.from(st.grid),
        Math.min(diffToLevel(p.diff), DIFF_EXTREME),
      );
      expect(ops.length).toBeGreaterThan(0);
      const kinds = new Set(ops.map((o) => (o.reason as HintReason).kind));
      // The mode's signature deduction is exercised.
      expect(want.some((k) => kinds.has(k as HintReason["kind"]))).toBe(true);

      // Replaying the placements reconstructs the full (unique) solution.
      const filled = Uint8Array.from(st.immutable);
      for (const op of ops)
        if (op.kind === "place") filled[op.y * st.order + op.x] = op.n;
      for (let i = 0; i < st.order * st.order; i++)
        expect(filled[i]).toBeGreaterThan(0);
    });
  }
});

// --- tier 1: hint plan ------------------------------------------------------

function firstHint(st: UnequalState) {
  const res = unequalGame.hint?.(st);
  if (!res) throw new Error("no hint method");
  return res;
}

describe("unequal hint", () => {
  it("populates before the first elimination", () => {
    const { st } = gen(UNEQ, "hint-empty");
    const res = firstHint(st);
    expect(res.ok).toBe(true);
    if (!res.ok) return;
    const moves = res.steps.map((s) => (s.move as UnequalMove).type);
    const populateAt = moves.indexOf("pencilAll");
    const firstStrike = moves.indexOf("pencilStrike");
    expect(populateAt).toBe(0);
    expect(firstStrike).toBeGreaterThan(0);
    expect(populateAt).toBeLessThan(firstStrike);
    expect(moves.includes("set")).toBe(true);
  });

  it("skips populate once notes are present", () => {
    const { st } = gen(UNEQ, "hint-pop");
    const populated = unequalGame.executeMove(st, { type: "pencilAll" });
    const res = firstHint(populated);
    expect(res.ok).toBe(true);
    if (!res.ok) return;
    expect((res.steps[0].move as UnequalMove).type).not.toBe("pencilAll");
  });

  it("surfaces a naked single as the next move ahead of any elimination", () => {
    const { st } = gen(UNEQ, "hint-naked");
    const r = unequalGame.solve?.(st, st);
    if (!r?.ok || r.move.type !== "solve") throw new Error("solve failed");
    const o = st.order;
    const i = [...st.immutable].indexOf(0);
    const x = i % o;
    const y = (i / o) | 0;
    const v = r.move.grid[i];
    const populated = unequalGame.executeMove(st, { type: "pencilAll" });
    // Narrow this one cell to a single candidate (its solution value).
    const marks = [];
    for (let n = 1; n <= o; n++) if (n !== v) marks.push({ x, y, n });
    const narrowed = unequalGame.executeMove(populated, {
      type: "pencilStrike",
      marks,
    });

    const res = unequalGame.hint?.(narrowed);
    expect(res?.ok).toBe(true);
    if (!res?.ok) return;
    // Auto-pencil defaults off → the placement carries `autoElim: false`.
    expect(res.steps[0].move).toEqual({
      type: "set",
      x,
      y,
      n: v,
      pencil: false,
      autoElim: false,
    });
    expect(res.steps[0].explanation).toMatch(/can only be/);
  });

  it("every deduction conclusion uses the necessity voice", () => {
    for (const p of [UNEQ, ADJ]) {
      const { st } = gen(p, `voice-${p.mode}`);
      const populated = unequalGame.executeMove(st, { type: "pencilAll" });
      const res = unequalGame.hint?.(populated);
      expect(res?.ok).toBe(true);
      if (!res?.ok) continue;
      // A strike concludes "we must cross out …"; a placement "it can only be N";
      // never a bare "is/are/stays". (The populate fill and the bulk obvious-clean
      // are setup instructions, not deductions, so they are exempt.)
      const modal = /can only|can't|must (be|cross out)/i;
      const isSetup = (s: (typeof res.steps)[number]) =>
        (s.move as UnequalMove).type === "pencilAll" ||
        /clear the easy ones|fill all pencil marks/.test(s.explanation);
      for (const s of res.steps) {
        if (isSetup(s)) continue;
        expect(s.explanation).toMatch(modal);
      }
    }
  });

  it("differ-by-1 narration reads correctly at the value extremes", () => {
    // §2.7: the adjacency clue must never say "N−1 or N+1" (wrong at N=1 or N=o);
    // it says "one away from N".
    const { st } = gen(ADJ, "adj-extreme");
    const populated = unequalGame.executeMove(st, { type: "pencilAll" });
    const res = unequalGame.hint?.(populated);
    expect(res?.ok).toBe(true);
    if (!res?.ok) return;
    for (const s of res.steps) {
      expect(s.explanation).not.toMatch(/-\s*1 or|\+\s*1/);
    }
  });

  it("auto-pencil on folds away the trivial row/column eliminations a placement implies", () => {
    const { st } = gen(UNEQ, "hint-autopencil");
    const populated = unequalGame.executeMove(st, { type: "pencilAll" });
    const dupRe = /from the other cells they pass through/;

    const uiOn = newUi(populated);
    uiOn.autoPencil = true;
    const on = unequalGame.hint?.(populated, undefined, uiOn);
    const uiOff = newUi(populated);
    uiOff.autoPencil = false;
    const off = unequalGame.hint?.(populated, undefined, uiOff);
    expect(on?.ok && off?.ok).toBe(true);
    if (!on?.ok || !off?.ok) return;

    // The basic-Latin opening culls (givens) use the same dup narration in both,
    // so compare the *count*: with auto-pencil off, each placement also teaches
    // its row/column cleanup, so there are strictly more dup steps.
    const dupCount = (r: typeof on) =>
      r.steps.filter((s) => dupRe.test(s.explanation)).length;
    expect(dupCount(off)).toBeGreaterThan(dupCount(on));
    expect(off.steps.length).toBeGreaterThan(on.steps.length);
  });

  it("a clue-strike step's marks all lie in its narrated cell (no bleed)", () => {
    let checked = 0;
    for (const p of [UNEQ, ADJ]) {
      for (let s = 0; s < 8; s++) {
        const { st } = gen(p, `bleed-${p.mode}-${s}`);
        const res = unequalGame.hint?.(st);
        if (!res?.ok) continue;
        for (const step of res.steps as AnyStep[]) {
          if (step.move.type !== "pencilStrike") continue;
          const marks = step.move.marks as { x: number; y: number; n: number }[];
          // A clue strike (greater/lesser/adjacent/adjacentSet) shades two evidence
          // cells and acts on exactly one of them; every mark is in that one cell.
          const area: { x: number; y: number }[] = step.highlights?.area ?? [];
          if (area.length !== 2) continue; // basic-Latin/dup steps shade ≤1
          const cells = new Set(marks.map((m) => `${m.x},${m.y}`));
          expect(cells.size).toBe(1);
          for (const m of marks) {
            expect(area.some((a) => a.x === m.x && a.y === m.y)).toBe(true);
            checked++;
          }
        }
      }
    }
    expect(checked).toBeGreaterThan(0);
  });

  it("refuses on a solved board and on a board with mistakes", () => {
    const { st } = gen(UNEQ, "hint-refuse");
    const r = unequalGame.solve?.(st, st);
    if (!r?.ok) throw new Error("solve failed");
    const solved = unequalGame.executeMove(st, r.move);
    expect(unequalGame.hint?.(solved).ok).toBe(false);

    const o = st.order;
    const empty = [...st.immutable].indexOf(0);
    const sol = (r.move as { type: "solve"; grid: number[] }).grid;
    const wrong = (sol[empty] % o) + 1;
    const bad = unequalGame.executeMove(st, {
      type: "set",
      x: empty % o,
      y: (empty / o) | 0,
      n: wrong,
      pencil: false,
    });
    expect(unequalGame.hint?.(bad).ok).toBe(false);
  });
});

// --- tier 1: keep-track -----------------------------------------------------

describe("unequal hintKeepTrack", () => {
  it("matches a populate step, rejects anything else", () => {
    const { st } = gen(UNEQ, "kt-pop");
    const res = firstHint(st);
    if (!res.ok) throw new Error("refused");
    const step = res.steps.find((s) => (s.move as UnequalMove).type === "pencilAll");
    if (!step) throw new Error("no populate step");
    expect(unequalGame.hintKeepTrack?.({ type: "pencilAll" }, step, st)).toBe(
      "completed",
    );
    expect(
      unequalGame.hintKeepTrack?.(
        { type: "set", x: 0, y: 0, n: 1, pencil: false },
        step,
        st,
      ),
    ).toBe("off");
  });

  it("shrinks then finishes a multi-mark strike journey", () => {
    const { st } = gen(UNEQ, "kt-strike");
    const populated = unequalGame.executeMove(st, { type: "pencilAll" });
    const res = unequalGame.hint?.(populated);
    if (!res?.ok) throw new Error("hint refused");
    const step = res.steps.find(
      (s) =>
        (s.move as UnequalMove).type === "pencilStrike" &&
        (s.move as { type: "pencilStrike"; marks: unknown[] }).marks.length >= 2,
    ) as AnyStep | undefined;
    if (!step) throw new Error("no multi-mark strike step");

    const marks = [...step.move.marks] as { x: number; y: number; n: number }[];
    // Clear the first mark via a pencil toggle (the production strike path).
    const first = marks[0];
    const v1 = unequalGame.hintKeepTrack?.(
      { type: "set", x: first.x, y: first.y, n: first.n, pencil: true },
      step,
      populated,
    );
    expect(v1).toBe("onTrack");
    expect((step.move as { marks: unknown[] }).marks.length).toBe(marks.length - 1);

    // Apply that toggle, then clear the remaining marks one by one to "completed".
    let cur = unequalGame.executeMove(populated, {
      type: "set",
      x: first.x,
      y: first.y,
      n: first.n,
      pencil: true,
    });
    for (let k = 1; k < marks.length; k++) {
      const mk = marks[k];
      const v = unequalGame.hintKeepTrack?.(
        { type: "set", x: mk.x, y: mk.y, n: mk.n, pencil: true },
        step,
        cur,
      );
      expect(v).toBe(k === marks.length - 1 ? "completed" : "onTrack");
      cur = unequalGame.executeMove(cur, {
        type: "set",
        x: mk.x,
        y: mk.y,
        n: mk.n,
        pencil: true,
      });
    }
  });
});

// --- tier 1: resume to solved (both modes) ----------------------------------

describe("unequal hint resumes to solved", () => {
  for (const p of [UNEQ, ADJ]) {
    it(`completes a fresh ${p.mode}-mode board one recomputed hint at a time`, () => {
      const { st: start, aux } = gen(p, `resume-${p.mode}`);
      let state = start;
      for (let moves = 0; moves < 600; moves++) {
        if (status(state) === "solved") return;
        const res = unequalGame.hint?.(state, aux);
        expect(res?.ok).toBe(true);
        if (!res?.ok) throw new Error(`gave up: ${res?.error}`);
        state = unequalGame.executeMove(state, res.steps[0].move);
      }
      throw new Error("did not converge");
    });
  }
});

// --- tier 2.5: render ------------------------------------------------------

/** Scan seeds for an id whose hint, after populating, reaches a clue-strike step
 * matching `pred` — so the render frame is deterministic without a known desc. */
function clueStrikeFrame(p: UnequalParams, pred: (s: string) => boolean): string {
  for (let s = 0; s < 30; s++) {
    const seed = `frame-${p.mode}-${s}`;
    const { st } = gen(p, seed);
    const populated = unequalGame.executeMove(st, { type: "pencilAll" });
    const res = unequalGame.hint?.(populated);
    if (!res?.ok) continue;
    if (
      res.steps.some(
        (step) =>
          (step.move as UnequalMove).type === "pencilStrike" && pred(step.explanation),
      )
    )
      return `${encodeParams(p, true)}#${seed}`;
  }
  throw new Error(`no clue-strike frame found for ${p.mode}`);
}

describe("unequal hint render", () => {
  it("an Unequal-mode link elimination shades the pair and strikes the candidate", () => {
    const id = clueStrikeFrame(UNEQ, (e) => /greater-than sign/.test(e));
    const { recording, hint } = renderScenario({
      game: unequalGame,
      id,
      defaultBackground: DEFAULT_BACKGROUND,
      moves: [{ type: "pencilAll" }],
      showHint: true,
      hintUntil: (s) => /greater-than sign/.test(s.explanation),
    });
    expect(hint?.explanation).toMatch(/greater-than sign/);
    // The two clue cells are shaded COL_HINT_CELL evidence.
    expect(
      recording.ops.some((o) => o.op === "rect" && o.colour === COL_HINT_CELL),
    ).toBe(true);
    // The struck candidate keeps its COL_PENCIL digit, crossed through in COL_PENCIL.
    expect(recording.ops.some((o) => o.op === "line" && o.colour === COL_PENCIL)).toBe(
      true,
    );
    expect(recording.ops.some((o) => o.op === "text" && o.colour === COL_PENCIL)).toBe(
      true,
    );
    // A strike cell is NOT solid-filled COL_HINT (that is the placement-target fill).
    expect(recording.ops.some((o) => o.op === "rect" && o.colour === COL_HINT)).toBe(
      false,
    );
    // Clue glyphs (the > polygons) are still drawn.
    expect(recording.ops.some((o) => o.op === "polygon")).toBe(true);
    expect(recording.ops).toMatchSnapshot();
  });

  it("an Adjacent-mode elimination shades the pair and strikes the candidate", () => {
    const id = clueStrikeFrame(ADJ, (e) => /bar/.test(e));
    const { recording, hint } = renderScenario({
      game: unequalGame,
      id,
      defaultBackground: DEFAULT_BACKGROUND,
      moves: [{ type: "pencilAll" }],
      showHint: true,
      hintUntil: (s) => /bar/.test(s.explanation),
    });
    expect(hint?.explanation).toMatch(/bar/);
    expect(
      recording.ops.some((o) => o.op === "rect" && o.colour === COL_HINT_CELL),
    ).toBe(true);
    expect(recording.ops.some((o) => o.op === "line" && o.colour === COL_PENCIL)).toBe(
      true,
    );
    expect(recording.ops).toMatchSnapshot();
  });
});

