/**
 * Behavioural tests for the hat aperiodic monotile.
 *
 * The heavy lifting is done by `grid-aperiodic-differential.test.ts`, which
 * byte-matches both the generated desc and the resulting grid against the C.
 * What is left for here is what a differential *cannot* see: that the generated
 * tables really contain what the C survey said they do, that malformed descs
 * are rejected with the right reason, and that the deterministic short-desc
 * replay path is actually deterministic.
 */

import { describe, expect, it } from "vitest";
import { randomNew } from "../../random/index.ts";
import { metatileCharToType } from "./hat.ts";
import { gridNewHats, hatsNewDesc, hatsValidateDesc } from "./hat-grid.ts";
import { children, hatsInMetatile, kitemap, metamap, nchildren } from "./hat-tables.ts";

const LETTERS = ["H", "T", "P", "F"];

describe("hat-tables.ts extraction", () => {
  // These figures were read off the C independently of the extraction script,
  // so they catch a formatting drift in `hat-tables.h` that silently truncated
  // a table — which would otherwise surface only as a wrong tiling deep in a
  // patch. Kept as literals on purpose: deriving them from the arrays under
  // test would make the check vacuous.
  it("has the expected shape per metatile type", () => {
    expect([...hatsInMetatile]).toEqual([4, 1, 2, 2]);
    expect([...nchildren]).toEqual([13, 7, 11, 11]);
    expect(children.map((c) => c.length)).toEqual([13, 7, 11, 11]);
  });

  it("has the expected number of kitemap and metamap entries", () => {
    // Stride 3 for kitemap (kite, hat, meta), 2 for metamap (meta, meta2).
    expect(kitemap.map((t) => t.length / 3)).toEqual([1664, 896, 1408, 1408]);
    expect(metamap.map((t) => t.length / 2)).toEqual([169, 91, 143, 143]);
  });

  it("has the expected number of impossible-step sentinels", () => {
    const kiteSentinels = kitemap.map((t) => {
      let n = 0;
      for (let i = 0; i < t.length; i += 3) {
        if (t[i] === -1 && t[i + 1] === -1 && t[i + 2] === -1) n++;
      }
      return n;
    });
    expect(kiteSentinels).toEqual([768, 456, 664, 662]);
    expect(kiteSentinels.reduce((a, b) => a + b, 0)).toBe(2550);

    const metaSentinels = metamap.map((t) => {
      let n = 0;
      for (let i = 0; i < t.length; i += 2) if (t[i] === -1) n++;
      return n;
    });
    expect(metaSentinels).toEqual([24, 12, 18, 18]);
    expect(metaSentinels.reduce((a, b) => a + b, 0)).toBe(72);
  });

  it("holds only values in [-1, 12]", () => {
    // Int8Array would accept anything up to 127, so a parse slip that read a
    // stray number would not be caught by the type alone.
    for (const table of [...kitemap, ...metamap, ...children]) {
      for (const v of table) expect(v).toBeGreaterThanOrEqual(-1);
      for (const v of table) expect(v).toBeLessThanOrEqual(12);
    }
  });

  it("names only real metatile types in every child list", () => {
    for (const list of children) {
      for (const t of list) expect(LETTERS[t]).toBeDefined();
    }
  });
});

describe("hat desc round-trip", () => {
  it("generates descs that validate and build", () => {
    for (let seed = 0; seed < 12; seed++) {
      const desc = hatsNewDesc(6, 6, randomNew(String(seed)));
      expect(hatsValidateDesc(6, 6, desc)).toBeNull();
      expect(desc).toMatch(/^(\d{1,2},)+[HTPF]$/);

      const g = gridNewHats(6, 6, desc);
      expect(g.faces.length).toBeGreaterThan(0);
      expect(g.dots.length).toBeGreaterThan(0);
      // Trimming keeps only the landlocked core, so every face is a whole hat.
      for (const f of g.faces) expect(f.order).toBe(14);
    }
  });

  it("builds the same grid twice from one desc", () => {
    const desc = hatsNewDesc(6, 6, randomNew("determinism"));
    const dump = (): string =>
      JSON.stringify(gridNewHats(6, 6, desc).dots.map((d) => [d.x, d.y]));
    expect(dump()).toBe(dump());
  });

  it("replays a short desc deterministically at a larger size", () => {
    // A desc records exactly the coordinate depth its own region demanded, so
    // replaying it at a *larger* size runs off the end of what it stored. The
    // C then invents nothing at random — it takes each type's first legal
    // parent — and this is the only path that exercises that branch, since no
    // ordinary fixture is ever replayed bigger than it was generated.
    const desc = hatsNewDesc(6, 6, randomNew("short"));
    const dump = (): string =>
      JSON.stringify(gridNewHats(12, 12, desc).dots.map((d) => [d.x, d.y]));
    const first = dump();
    expect(dump()).toBe(first);
    // And it must actually be a bigger patch than the desc was made for.
    expect(gridNewHats(12, 12, desc).faces.length).toBeGreaterThan(
      gridNewHats(6, 6, desc).faces.length,
    );
  });

  it("emits no negative-zero dot coordinate", () => {
    // -0 survives `===`, the dot-dedup key and `Map` lookup, so a grid carrying
    // it is structurally perfect and only `Object.is` disagrees.
    const g = gridNewHats(6, 6, hatsNewDesc(6, 6, randomNew("zero")));
    for (const d of g.dots) {
      expect(Object.is(d.x, -0)).toBe(false);
      expect(Object.is(d.y, -0)).toBe(false);
    }
  });
});

describe("hat desc validation", () => {
  it("rejects a missing desc", () => {
    expect(hatsValidateDesc(6, 6, null)).toBe("Missing grid description string.");
  });

  it.each([
    ["", "invalid character in grid description"],
    ["X", "invalid character in grid description"],
    ["0", "expected ',' in grid description"],
    ["0,3,0", "expected ',' in grid description"],
    ["0,3,0,0,6,Z", "invalid character in grid description"],
    ["000,3,0,0,6,F", "too-large coordinate in grid description"],
    ["0,3,F", "Grid parameters require at least three coordinates"],
    ["9,3,0,0,6,F", "Grid parameters contain an invalid kite index"],
    ["0,3,0,0,12,F", "Grid parameters contain an invalid metatile index"],
    ["0,4,0,0,6,F", "Grid parameters contain an invalid hat index"],
  ])("rejects %o", (desc, error) => {
    expect(hatsValidateDesc(6, 6, desc)).toBe(error);
  });

  it("accepts trailing junk after the metatile letter, as the C does", () => {
    // Upstream stops reading at the letter and never checks for a terminator.
    // Recorded rather than tightened: a stricter TS validator would reject
    // descs the C build happily accepts.
    expect(hatsValidateDesc(6, 6, "0,3,0,0,6,Fjunk")).toBeNull();
  });
});

describe("metatileCharToType", () => {
  it("maps the four letters and nothing else", () => {
    expect(LETTERS.map(metatileCharToType)).toEqual([0, 1, 2, 3]);
    // "" is the interesting one: `"HTPF".indexOf("")` is 0, so an unguarded
    // lookup would read a missing letter as H.
    for (const c of ["", "G", "h", "HH"]) expect(metatileCharToType(c)).toBe(-1);
  });
});

src/native/games/slant/slant-render-scen.source:
/**
 * Tier-2.5 render scenarios for the Slant hint: drive a real Midend to a
 * displayed hint step and capture `redraw`. Targeted op assertions (the blue
 * `COL_HINT` target fill, the recoloured clue digit, the `COL_HINT_CELL`
 * evidence shade) plus one snapshot so a render regression is a reviewable
 * text diff (`vitest -u` re-baselines an intended change; the targeted
 * assertions survive a careless `-u`).
 */
import { describe, expect, it } from "vitest";
import type { HintStep } from "../../engine/game.ts";
import { renderScenario } from "../../engine/testing/render-scenario.ts";
import { randomNew } from "../../random/index.ts";
import { type SlantHint, slantGame } from "./index.ts";
import { COL_GRID, COL_HINT, COL_HINT_CELL, COL_HINT_REF } from "./render.ts";
import { DIFF_EASY, DIFF_HARD, encodeParams, type SlantParams } from "./state.ts";

function boardId(params: SlantParams, seed: string): string {
  const { desc } = slantGame.newDesc(params, randomNew(seed));
  return `${encodeParams(params, true)}:${desc}`;
}

const hl = (step: HintStep<unknown> | undefined): SlantHint | undefined =>
  step?.highlights as SlantHint | undefined;

describe("Slant hint render scenarios", () => {
  it("opener frame: blue target(s), recoloured clue digit, board intact", () => {
    const { recording, hint, size } = renderScenario({
      game: slantGame,
      id: boardId({ w: 5, h: 5, diff: DIFF_EASY }, "srs-easy-0"),
      showHint: true,
    });

    const h = hl(hint);
    expect(h).toBeDefined();
    // The opener is a clue firing: it carries a driving clue.
    expect(h?.clue).toBeDefined();

    // At least one blue COL_HINT target fill (target + any siblings).
    const targetRects = recording.ops.filter(
      (o) => o.op === "rect" && o.colour === COL_HINT,
    );
    expect(targetRects.length).toBeGreaterThanOrEqual(1);
    // The driving clue's digit recolours COL_HINT (the clue↔move tie).
    expect(recording.ops.some((o) => o.op === "text" && o.colour === COL_HINT)).toBe(
      true,
    );
    // Other clue digits still drawn; the grid frame is present.
    expect(recording.ops.some((o) => o.op === "text")).toBe(true);
    expect(recording.ops.some((o) => "colour" in o && o.colour === COL_GRID)).toBe(
      true,
    );
    expect(size.w).toBeGreaterThan(0);

    expect(recording.ops).toMatchSnapshot();
  });

  it("loop frame: the closing chain shades COL_HINT_CELL under one blue target", () => {
    const { recording, hint } = renderScenario({
      game: slantGame,
      id: boardId({ w: 8, h: 8, diff: DIFF_HARD }, "srs-hard-0"),
      showHint: true,
      hintUntil: (step) => /already joined by a chain/.test(step.explanation ?? ""),
    });

    const h = hl(hint);
    expect(h).toBeDefined();
    expect(h?.area?.length ?? 0).toBeGreaterThan(0);
    // Exactly one blue target (loop firings force a single square).
    expect(
      recording.ops.filter((o) => o.op === "rect" && o.colour === COL_HINT).length,
    ).toBe(1);
    // The chain is shaded.
    expect(
      recording.ops.some((o) => o.op === "rect" && o.colour === COL_HINT_CELL),
    ).toBe(true);
  });

  it("equivalence frame: the cited anchor rings COL_HINT_REF", () => {
    const { recording, hint } = renderScenario({
      game: slantGame,
      id: boardId({ w: 12, h: 10, diff: DIFF_HARD }, "srs-hard-eq"),
      showHint: true,
      hintUntil: (step) => /locked to the same slant/.test(step.explanation ?? ""),
    });

    const h = hl(hint);
    expect(h?.ref).toBeDefined();
    expect(
      recording.ops.filter((o) => o.op === "rect" && o.colour === COL_HINT).length,
    ).toBe(1);
    expect(recording.ops.some((o) => "colour" in o && o.colour === COL_HINT_REF)).toBe(
      true,
    );
  });
});

src/native/games/undead/undead-deduction.source:
/**
 * The Undead deductive ladder (`strengthen-undead-deduction`): unit tests for
 * each rung (arc-consistency → exact counting → depth-1 forcing) and the
 * guess-free generation property.
 *
 * The counting rung is path-independent, so it is exercised in isolation with a
 * synthetic paths-free `UndeadCommon` (arc-consistency is then a no-op, isolating
 * counting). The forcing rung and the no-guess boundary use real generated /
 * constructed boards. The property test confirms the generation gate: every
 * accepted board is solved by the ladder with **zero recursion**, at the rung its
 * tier demands.
 */
import { describe, expect, it } from "vitest";
import { randomNew } from "../../random/index.ts";
import { newUndeadDesc } from "./generator.ts";
import {
  isUniquelySolvable,
  RUNG_ARC,
  RUNG_COUNTING,
  RUNG_FORCING,
  solveDeductive,
} from "./solver.ts";
import {
  type Difficulty,
  MON_GHOST,
  MON_NONE,
  MON_VAMPIRE,
  newState,
  type UndeadCommon,
  type UndeadParams,
} from "./state.ts";

/** A synthetic monster-only `common` with no sightlines, so arc-consistency is a
 * pure no-op and only the counting rung can make progress. */
function paintByNumbers(
  numTotal: number,
  g: number,
  v: number,
  z: number,
): UndeadCommon {
  return {
    params: { w: 1, h: 1, diff: "easy" },
    w: 1,
    h: 1,
    wh: 9,
    numGhosts: g,
    numVampires: v,
    numZombies: z,
    numTotal,
    grid: new Int32Array(9),
    xinfo: new Int32Array(9),
    fixed: new Uint8Array(numTotal),
    paths: [],
    numPaths: 0,
  };
}

describe("undead counting rung", () => {
  it("a fully-placed type strikes itself and Hall-forces the rest", () => {
    // Two cells, one ghost one vampire (no zombies). Cell 0 is a given ghost.
    // Arc-consistency (no paths) cannot touch cell 1; counting must finish it:
    // ghost fully placed ⇒ strike ghost from cell 1; vampire's last candidate
    // cell ⇒ force it; zombie total 0 ⇒ strike zombie everywhere.
    const common = paintByNumbers(2, 1, 1, 0);
    const start = Uint8Array.from([MON_GHOST, MON_NONE]);

    const arc = solveDeductive(common, start, RUNG_ARC);
    expect(arc.solved).toBe(false); // arc alone is stuck

    const counting = solveDeductive(common, start, RUNG_COUNTING);
    expect(counting.solved).toBe(true);
    expect(counting.rung).toBe(RUNG_COUNTING);
    expect(Array.from(counting.guess)).toEqual([MON_GHOST, MON_VAMPIRE]);
  });

  it("a zero-total monster type is struck from every cell", () => {
    // Three cells, two ghosts one vampire, no zombies. Counting strikes zombie
    // everywhere (total 0) and pins the vampire once both ghosts are forced.
    const common = paintByNumbers(3, 2, 1, 0);
    const start = Uint8Array.from([MON_GHOST, MON_GHOST, MON_NONE]);
    const counting = solveDeductive(common, start, RUNG_COUNTING);
    expect(counting.solved).toBe(true);
    expect(Array.from(counting.guess)).toEqual([MON_GHOST, MON_GHOST, MON_VAMPIRE]);
  });
});

describe("undead forcing rung", () => {
  it("is required for a Tricky board (counting alone stalls, forcing finishes)", () => {
    const params: UndeadParams = { w: 5, h: 5, diff: "tricky" };
    const { desc } = newUndeadDesc(params, randomNew("undead-forcing-rung"));
    const common = newState(params, desc).common;
    const start = new Uint8Array(common.numTotal).fill(MON_NONE);

    // Arc + counting cannot finish a Tricky board…
    expect(solveDeductive(common, start, RUNG_COUNTING).solved).toBe(false);
    // …but the depth-1 forcing rung does, with no recursion.
    const forcing = solveDeductive(common, start, RUNG_FORCING);
    expect(forcing.solved).toBe(true);
    expect(forcing.rung).toBe(RUNG_FORCING);
  });
});

describe("undead deduction/recursion boundary", () => {
  it("leaves a genuinely ambiguous board unsolved rather than guessing", () => {
    // Two cells, one ghost one vampire, no clues: both completions (G,V) and
    // (V,G) are consistent, so depth-1 forcing finds no contradiction either
    // way. The ladder must NOT nest hypotheses to pick one — it leaves the board
    // unsolved (= recursion needed), and the board is genuinely non-unique.
    const common = paintByNumbers(2, 1, 1, 0);
    const start = new Uint8Array(2).fill(MON_NONE);
    const result = solveDeductive(common, start, RUNG_FORCING);
    expect(result.solved).toBe(false);
    expect(result.inconsistent).toBe(false);
    expect(isUniquelySolvable(common)).toBe(false);
  });
});

describe("undead guess-free generation property", () => {
  const tiers: [number, number, Difficulty][] = [
    [4, 4, "easy"],
    [4, 4, "normal"],
    [4, 4, "tricky"],
    [5, 5, "normal"],
    [5, 5, "tricky"],
  ];
  for (const [w, h, diff] of tiers) {
    it(`every accepted ${w}x${h} ${diff} board is solved by the ladder with no recursion`, () => {
      const params: UndeadParams = { w, h, diff };
      for (let i = 0; i < 5; i++) {
        const { desc } = newUndeadDesc(
          params,
          randomNew(`prop-${w}x${h}-${diff}-${i}`),
        );
        const common = newState(params, desc).common;
        const start = new Uint8Array(common.numTotal).fill(MON_NONE);
        const grade = solveDeductive(common, start); // full ladder
        expect(grade.solved).toBe(true); // deductive, zero recursion
        expect(grade.inconsistent).toBe(false);
        if (diff === "easy") expect(grade.rung).toBe(RUNG_ARC);
        else if (diff === "normal")
          expect(grade.rung === RUNG_ARC || grade.rung === RUNG_COUNTING).toBe(true);
        else expect(grade.rung).toBe(RUNG_FORCING);
        // Independently unique.
        expect(isUniquelySolvable(common)).toBe(true);
      }
    }, 30_000);
  }
});

src/native/games/solo/solo-hint.test.ts.source:
/**
 * Solo explained-hint tests.
 *
 * Tier 1 — the recording solver records a reason per technique (incl. a killer
 * deduction and an X-diagonal deduction) and its replayed placements complete a
 * generated board; `hint` populates, strikes (deductive eliminations + basic
 * region culls) and places with quality-bar narration; refusal on solved / on
 * mistakes; `hintKeepTrack` verdicts. Tier 2.5 — a render-scenario snapshot of a
 * deductive elimination journey frame (struck candidate `COL_PENCIL`
 * strikethrough, evidence `COL_HINT_CELL`, grid/clues still drawn).
 */
import { describe, expect, it } from "vitest";
import {
  DEFAULT_BACKGROUND,
  renderScenario,
} from "../../engine/testing/render-scenario.ts";
import { randomNew } from "../../random/index.ts";
import { newSoloDesc } from "./generator.ts";
import { soloGame } from "./index.ts";
import { COL_HINT_CELL, COL_PENCIL } from "./render.ts";
import { type HintReason, recordSoloDeductions } from "./solver.ts";
import {
  DIFF_BLOCK,
  DIFF_INTERSECT,
  DIFF_KINTERSECT,
  DIFF_SET,
  DIFF_SIMPLE,
  defaultParams,
  encodeParams,
  newState,
  type SoloMove,
  type SoloParams,
  type SoloState,
  SYMM_NONE,
  status as soloStatus,
} from "./state.ts";

function gen(p: SoloParams, seed: string) {
  const { desc, aux } = newSoloDesc(p, randomNew(seed));
  return { p, desc, aux, st: newState(p, desc) };
}

// biome-ignore lint/suspicious/noExplicitAny: structural access to hint highlights/move in tests.
type AnyStep = any;

const BASIC: SoloParams = { ...defaultParams(), diff: DIFF_SIMPLE };
const INTER: SoloParams = { ...defaultParams(), diff: DIFF_INTERSECT };
const ADV: SoloParams = { ...defaultParams(), diff: DIFF_SET };
const XADV: SoloParams = { ...defaultParams(), diff: DIFF_SET, xtype: true };
const KILLER: SoloParams = {
  c: 3,
  r: 3,
  symm: SYMM_NONE,
  diff: DIFF_BLOCK,
  kdiff: DIFF_KINTERSECT,
  xtype: false,
  killer: true,
};

// --- tier 1: recording solver ----------------------------------------------

describe("solo recording solver", () => {
  it("records reasons and its placements complete the board (Basic)", () => {
    const { st } = gen(BASIC, "rec-basic");
    const ops = recordSoloDeductions(st, DIFF_SIMPLE);
    expect(ops.length).toBeGreaterThan(0);
    const cr = st.cr;
    const filled = new Int8Array(cr * cr);
    for (let i = 0; i < cr * cr; i++) if (st.immutable[i]) filled[i] = st.grid[i];
    for (const op of ops) if (op.kind === "place") filled[op.y * cr + op.x] = op.n;
    for (let i = 0; i < cr * cr; i++) expect(filled[i]).toBeGreaterThan(0);
  });

  it("records the intersect technique on Intermediate boards", () => {
    const kinds = new Set<string>();
    for (const s of ["i0", "i1", "i2", "i3", "i4", "i5"]) {
      const { st } = gen(INTER, s);
      for (const op of recordSoloDeductions(st, DIFF_INTERSECT))
        kinds.add((op.reason as HintReason).kind);
    }
    expect([...kinds]).toContain("intersect");
  });

  it("records the set technique on Advanced boards", () => {
    const kinds = new Set<string>();
    for (const s of ["s0", "s1", "s2", "s3", "s4", "s5", "s6", "s7"]) {
      const { st } = gen(ADV, s);
      for (const op of recordSoloDeductions(st, DIFF_SET))
        kinds.add((op.reason as HintReason).kind);
    }
    expect([...kinds]).toContain("set");
  });

  it("records killer-cage reasons on a killer board", () => {
    const kinds = new Set<string>();
    for (const s of ["k0", "k1", "k2"]) {
      const { st } = gen(KILLER, s);
      for (const op of recordSoloDeductions(st, DIFF_BLOCK, DIFF_KINTERSECT))
        kinds.add((op.reason as HintReason).kind);
    }
    expect([...kinds].some((k) => k.startsWith("cage"))).toBe(true);
  });
});

// --- tier 1: hint plan ------------------------------------------------------

describe("solo hint", () => {
  it("populates before the first elimination", () => {
    const { st } = gen(ADV, "hint-empty");
    const res = soloGame.hint?.(st);
    expect(res?.ok).toBe(true);
    if (!res?.ok) return;
    const moves = res.steps.map((s) => (s.move as SoloMove).type);
    const populateAt = moves.indexOf("pencilAll");
    const firstStrike = moves.indexOf("pencilStrike");
    expect(populateAt).toBe(0);
    expect(firstStrike).toBeGreaterThan(0);
  });

  it("skips populate once notes are present", () => {
    const { st } = gen(ADV, "hint-pop");
    const populated = soloGame.executeMove(st, { type: "pencilAll" });
    const res = soloGame.hint?.(populated);
    expect(res?.ok).toBe(true);
    if (!res?.ok) return;
    expect((res.steps[0].move as SoloMove).type).not.toBe("pencilAll");
  });

  it("surfaces a naked single as the next move ahead of any elimination", () => {
    const { st } = gen(ADV, "hint-naked");
    const r = soloGame.solve?.(st, st);
    if (!r?.ok || r.move.type !== "solve") throw new Error("solve failed");
    const cr = st.cr;
    // Pick a non-given cell, narrow it to its solution value.
    let x = 0;
    let y = 0;
    for (let i = 0; i < cr * cr; i++)
      if (!st.immutable[i]) {
        x = i % cr;
        y = (i / cr) | 0;
        break;
      }
    const v = r.move.grid[y * cr + x];
    const populated = soloGame.executeMove(st, { type: "pencilAll" });
    const marks = [];
    for (let n = 1; n <= cr; n++) if (n !== v) marks.push({ x, y, n });
    const narrowed = soloGame.executeMove(populated, { type: "pencilStrike", marks });
    const res = soloGame.hint?.(narrowed);
    expect(res?.ok).toBe(true);
    if (!res?.ok) return;
    // Auto-pencil defaults off → the placement carries `autoElim: false`.
    expect(res.steps[0].move).toEqual({
      type: "set",
      x,
      y,
      n: v,
      pencil: false,
      autoElim: false,
    });
    expect(res.steps[0].explanation).toMatch(/can only be/);
  });

  it("every deduction conclusion uses the necessity voice", () => {
    const { st } = gen(ADV, "voice");
    const populated = soloGame.executeMove(st, { type: "pencilAll" });
    const res = soloGame.hint?.(populated);
    expect(res?.ok).toBe(true);
    if (!res?.ok) return;
    const modal =
      /can only|can't|must (be|sit|cross out)|must be|cross out the|cross out/i;
    for (const s of res.steps) {
      if ((s.move as SoloMove).type === "pencilAll") continue;
      expect(s.explanation, s.explanation).toMatch(modal);
    }
  });

  it("a deductive strike step's marks all lie in one cell or all share one digit", () => {
    let checked = 0;
    for (const p of [INTER, ADV, KILLER]) {
      for (let s = 0; s < 6; s++) {
        const { st } = gen(p, `bleed-${p.diff}-${p.killer}-${s}`);
        const res = soloGame.hint?.(st);
        if (!res?.ok) continue;
        for (const step of res.steps as AnyStep[]) {
          if (step.move.type !== "pencilStrike") continue;
          // Skip the basic-region dup opening (one placed value across its groups)
          // and the bulk obvious-candidate cleanup at populate (a setup step, not a
          // deductive strike — multi-cell and multi-digit by design).
          if (/already placed in this cell/.test(step.explanation)) continue;
          if (/clear the easy ones|fill all pencil marks/.test(step.explanation)) {
            continue;
          }
          const marks = step.move.marks as { x: number; y: number; n: number }[];
          const cells = new Set(marks.map((m) => `${m.x},${m.y}`));
          const digits = new Set(marks.map((m) => m.n));
          // One firing's leg either acts on a single cell (cage/set split) or
          // crosses a single digit (intersect) — never a mixed bag.
          expect(cells.size === 1 || digits.size === 1).toBe(true);
          checked++;
        }
      }
    }
    expect(checked).toBeGreaterThan(0);
  });

  it("auto-pencil off teaches more cleanup steps than on", () => {
    const { st } = gen(ADV, "autopencil");
    const dupRe = /already placed in this cell/;
    const uiOn = soloGame.newUi(st);
    uiOn.autoPencil = true;
    const on = soloGame.hint?.(st, undefined, uiOn);
    const uiOff = soloGame.newUi(st);
    uiOff.autoPencil = false;
    const off = soloGame.hint?.(st, undefined, uiOff);
    expect(on?.ok && off?.ok).toBe(true);
    if (!on?.ok || !off?.ok) return;
    const dupCount = (r: typeof on) =>
      r.steps.filter((s) => dupRe.test(s.explanation)).length;
    expect(dupCount(off)).toBeGreaterThanOrEqual(dupCount(on));
    expect(off.steps.length).toBeGreaterThanOrEqual(on.steps.length);
  });

  it("narrates a hidden single by its region, never as a naked single", () => {
    let checked = 0;
    for (const seed of ["hs0", "hs1", "hs2", "hs3", "hs4", "hs5"]) {
      const { st, aux } = gen(ADV, seed);
      let state: SoloState = st;
      for (let i = 0; i < 3000 && soloStatus(state) !== "solved"; i++) {
        const res = soloGame.hint?.(state, aux);
        if (!res?.ok) break;
        const step = res.steps.find((s) =>
          /can go in only this cell/.test(s.explanation),
        ) as AnyStep | undefined;
        if (step) {
          const m = step.move as { type: string; x: number; y: number; n: number };
          expect(step.explanation).not.toMatch(/Every other number has been ruled out/);
          expect(step.explanation).toMatch(/In this (row|column|block|diagonal)/);
          const area = (step.highlights?.area ?? []) as { x: number; y: number }[];
          expect(area.some((a) => a.x === m.x && a.y === m.y)).toBe(true);
          checked++;
          break;
        }
        state = soloGame.executeMove(state, res.steps[0].move);
      }
    }
    expect(checked).toBeGreaterThan(0);
  });

  it("a naked-single narration only ever appears on a genuine one-candidate cell", () => {
    for (const seed of ["nk0", "nk1", "nk2", "nk3"]) {
      const { st, aux } = gen(ADV, seed);
      let state: SoloState = st;
      const cr = st.cr;
      for (let i = 0; i < 2000 && soloStatus(state) === "ongoing"; i++) {
        const res = soloGame.hint?.(state, aux);
        if (!res?.ok) break;
        const step = res.steps[0];
        const m = step.move as AnyStep;
        if (
          m.type === "set" &&
          !m.pencil &&
          /ruled out in this cell/.test(step.explanation)
        ) {
          const pen = state.pencil[m.y * cr + m.x];
          const ncand = Array.from({ length: cr }, (_, k) => k + 1).filter(
            (n) => pen & (1 << n),
          ).length;
          expect(ncand, `naked-single narration on a ${ncand}-candidate cell`).toBe(1);
        }
        state = soloGame.executeMove(state, step.move);
      }
    }
  });

  it("teaches an X-diagonal deduction on an X board", () => {
    let found = false;
    for (let s = 0; s < 30 && !found; s++) {
      const { st, aux } = gen(XADV, `xd-${s}`);
      let state: SoloState = st;
      for (let i = 0; i < 2000 && soloStatus(state) === "ongoing"; i++) {
        const res = soloGame.hint?.(state, aux);
        if (!res?.ok) break;
        if (res.steps.some((step) => /diagonal/.test(step.explanation))) {
          found = true;
          break;
        }
        state = soloGame.executeMove(state, res.steps[0].move);
      }
    }
    expect(found).toBe(true);
  });

  it("refuses on a solved board and on a board with mistakes", () => {
    const { st } = gen(BASIC, "refuse");
    const r = soloGame.solve?.(st, st);
    if (!r?.ok) throw new Error("solve failed");
    const solved = soloGame.executeMove(st, r.move);
    expect(soloGame.hint?.(solved)?.ok).toBe(false);

    const cr = st.cr;
    const sol = (r.move as { type: "solve"; grid: number[] }).grid;
    // Place a wrong digit in the first editable cell.
    let bx = 0;
    let by = 0;
    for (let i = 0; i < cr * cr; i++)
      if (!st.immutable[i]) {
        bx = i % cr;
        by = (i / cr) | 0;
        break;
      }
    const wrong = (sol[by * cr + bx] % cr) + 1;
    const bad = soloGame.executeMove(st, {
      type: "set",
      x: bx,
      y: by,
      n: wrong,
      pencil: false,
    });
    expect(soloGame.hint?.(bad)?.ok).toBe(false);
  });
});

// --- tier 1: keep-track -----------------------------------------------------

describe("solo hintKeepTrack", () => {
  it("matches a populate step, rejects anything else", () => {
    const { st } = gen(ADV, "kt-pop");
    const res = soloGame.hint?.(st);
    if (!res?.ok) throw new Error("refused");
    const step = res.steps.find((s) => (s.move as SoloMove).type === "pencilAll");
    if (!step) throw new Error("no populate step");
    expect(soloGame.hintKeepTrack?.({ type: "pencilAll" }, step, st)).toBe("completed");
    expect(
      soloGame.hintKeepTrack?.(
        { type: "set", x: 0, y: 0, n: 1, pencil: false },
        step,
        st,
      ),
    ).toBe("off");
  });

  it("shrinks then finishes a multi-mark strike journey", () => {
    const { st } = gen(ADV, "kt-strike");
    const populated = soloGame.executeMove(st, { type: "pencilAll" });
    const res = soloGame.hint?.(populated);
    if (!res?.ok) throw new Error("hint refused");
    const step = res.steps.find(
      (s) =>
        (s.move as SoloMove).type === "pencilStrike" &&
        (s.move as { type: "pencilStrike"; marks: unknown[] }).marks.length >= 2,
    ) as AnyStep | undefined;
    if (!step) throw new Error("no multi-mark strike step");

    const marks = [...step.move.marks] as { x: number; y: number; n: number }[];
    let cur = populated;
    for (let k = 0; k < marks.length; k++) {
      const mk = marks[k];
      const v = soloGame.hintKeepTrack?.(
        { type: "set", x: mk.x, y: mk.y, n: mk.n, pencil: true },
        step,
        cur,
      );
      expect(v).toBe(k === marks.length - 1 ? "completed" : "onTrack");
      cur = soloGame.executeMove(cur, {
        type: "set",
        x: mk.x,
        y: mk.y,
        n: mk.n,
        pencil: true,
      });
    }
  });
});

// --- tier 2.5: render ------------------------------------------------------

/** Scan seeds for an id whose from-populated plan reaches a deductive strike step
 * matching `pred` — so the render frame is deterministic without a known desc. */
function strikeFrame(p: SoloParams, pred: (s: string) => boolean): string {
  for (let s = 0; s < 40; s++) {
    const seed = `frame-${p.diff}-${s}`;
    const { st } = gen(p, seed);
    const populated = soloGame.executeMove(st, { type: "pencilAll" });
    const res = soloGame.hint?.(populated);
    if (!res?.ok) continue;
    if (
      res.steps.some(
        (step) =>
          (step.move as SoloMove).type === "pencilStrike" && pred(step.explanation),
      )
    )
      return `${encodeParams(p, true)}#${seed}`;
  }
  throw new Error(`no strike frame found for ${p.diff}`);
}

describe("solo hint render", () => {
  it("a deductive elimination shades the evidence and strikes the candidate", () => {
    const pred = (e: string) => /where they overlap|already accounts for/.test(e);
    const id = strikeFrame(ADV, pred);
    const { recording, hint } = renderScenario({
      game: soloGame,
      id,
      defaultBackground: DEFAULT_BACKGROUND,
      moves: [{ type: "pencilAll" }],
      showHint: true,
      hintUntil: (s) => pred(s.explanation),
    });
    expect(pred(hint?.explanation ?? "")).toBe(true);
    // The evidence region is shaded COL_HINT_CELL.
    expect(
      recording.ops.some((o) => o.op === "rect" && o.colour === COL_HINT_CELL),
    ).toBe(true);
    // The struck candidate keeps its COL_PENCIL digit, crossed through in COL_PENCIL.
    expect(recording.ops.some((o) => o.op === "line" && o.colour === COL_PENCIL)).toBe(
      true,
    );
    expect(recording.ops.some((o) => o.op === "text" && o.colour === COL_PENCIL)).toBe(
      true,
    );
    expect(recording.ops).toMatchSnapshot();
  });
});

