// Tier-1 logic tests for the Flood port: params/desc codecs, presets,
// generation (completable + par = solver + leniency), fill/solve move
// semantics and immutability, win/lose status, and input mapping.
import { describe, expect, it } from "vitest";
import { UI_UPDATE } from "../../engine/game.ts";
import { CURSOR_RIGHT, CURSOR_SELECT, LEFT_BUTTON } from "../../engine/pointer.ts";
import { randomNew } from "../../random/index.ts";
import { executeMove, floodGame } from "./index.ts";
import { completed, solveMoves } from "./solver.ts";
import {
  decodeParams,
  defaultParams,
  encodeParams,
  type FloodParams,
  type FloodState,
  newDesc,
  newState,
  status,
  textFormat,
  validateDesc,
  validateParams,
} from "./state.ts";

function gen(p: FloodParams, seed = "flood-test"): FloodState {
  const { desc } = newDesc(p, randomNew(seed));
  return newState(p, desc);
}

describe("Flood params", () => {
  it("round-trips and encodes the full form", () => {
    const p: FloodParams = { w: 12, h: 12, colours: 6, leniency: 5 };
    expect(encodeParams(p, true)).toBe("12x12c6m5");
    expect(encodeParams(p, false)).toBe("12x12");
    expect(decodeParams("12x12c6m5")).toEqual(p);
  });

  it("decodes a bare W as a square board with default colours/leniency", () => {
    expect(decodeParams("12")).toEqual({ w: 12, h: 12, colours: 6, leniency: 5 });
  });

  it("decodes c/m flags in either remainder order", () => {
    expect(decodeParams("8x10c4m0")).toEqual({ w: 8, h: 10, colours: 4, leniency: 0 });
    expect(decodeParams("16x16c6m2")).toEqual({
      w: 16,
      h: 16,
      colours: 6,
      leniency: 2,
    });
  });

  it("validateParams rejects bad params", () => {
    expect(validateParams({ w: 1, h: 1, colours: 6, leniency: 0 }, true)).toMatch(
      /two squares/,
    );
    expect(validateParams({ w: 4, h: 4, colours: 2, leniency: 0 }, true)).toMatch(
      /between 3 and 10/,
    );
    expect(validateParams({ w: 4, h: 4, colours: 11, leniency: 0 }, true)).toMatch(
      /between 3 and 10/,
    );
    expect(validateParams({ w: 4, h: 4, colours: 6, leniency: -1 }, true)).toMatch(
      /non-negative/,
    );
    expect(validateParams(defaultParams(), true)).toBeNull();
  });

  it("offers the seven upstream presets", () => {
    const menu = floodGame.presets();
    expect(menu.submenu).toHaveLength(7);
    expect(menu.submenu?.[0]).toEqual({
      title: "12x12 Easy",
      params: { w: 12, h: 12, colours: 6, leniency: 5 },
    });
  });
});

describe("Flood desc", () => {
  it("round-trips a generated description", () => {
    const p = defaultParams();
    const { desc } = newDesc(p, randomNew("desc-rt"));
    expect(validateDesc(p, desc)).toBeNull();
    const state = newState(p, desc);
    expect(state.grid).toHaveLength(p.w * p.h);
    // desc is wh colour chars + ",<movelimit>".
    expect(desc).toMatch(/^[0-9A-Z]+,\d+$/);
  });

  it("validateDesc rejects malformed descriptions", () => {
    const p: FloodParams = { w: 2, h: 2, colours: 3, leniency: 0 };
    expect(validateDesc(p, "012")).toMatch(/Not enough/); // 3 of 4 cells, no comma
    expect(validateDesc(p, "012!")).toMatch(/Bad character/);
    expect(validateDesc(p, "0123")).toMatch(/Expected ','/);
    expect(validateDesc(p, "0120,5")).toBeNull();
    expect(validateDesc(p, "0120,5x")).toMatch(/Badly formatted/);
  });
});

describe("Flood generation", () => {
  for (const p of [
    { w: 12, h: 12, colours: 6, leniency: 5 },
    { w: 12, h: 12, colours: 3, leniency: 0 },
    { w: 16, h: 16, colours: 6, leniency: 0 },
  ] as FloodParams[]) {
    it(`produces a non-trivial board whose limit is solver+leniency (${encodeParams(p, true)})`, () => {
      const { desc } = newDesc(p, randomNew(`gen-${encodeParams(p, true)}`));
      const state = newState(p, desc);
      expect(completed(state.grid)).toBe(false);
      const solverMoves = solveMoves(p.w, p.h, state.grid, state.colours);
      expect(state.movelimit).toBe(solverMoves.length + p.leniency);
    });
  }
});

describe("Flood fill move", () => {
  it("floods the corner region and leaves the source unmutated", () => {
    // A 3×3 board: corner colour 0, with a colour-1 cell adjacent.
    const p: FloodParams = { w: 3, h: 3, colours: 3, leniency: 0 };
    const state = newState(p, "011000222,9");
    const before = Uint8Array.from(state.grid);
    const next = executeMove(state, { type: "fill", colour: 1 });
    // The corner (0,0) and the two colour-1 cells (1,0),(2,0) become 1.
    expect(Array.from(next.grid.slice(0, 3))).toEqual([1, 1, 1]);
    expect(next.moves).toBe(1);
    // Source state untouched (immutability).
    expect(Array.from(state.grid)).toEqual(Array.from(before));
    expect(state.moves).toBe(0);
  });

  it("rejects a fill with the current corner colour", () => {
    const p: FloodParams = { w: 3, h: 3, colours: 3, leniency: 0 };
    const state = newState(p, "011000222,9");
    expect(() => executeMove(state, { type: "fill", colour: 0 })).toThrow();
  });
});

describe("Flood win / lose status", () => {
  it("reports solved when the grid completes within the limit", () => {
    // 1×2 board, corner colour 0, other cell colour 1, limit 5.
    const p: FloodParams = { w: 2, h: 1, colours: 3, leniency: 0 };
    const state = newState(p, "01,5");
    expect(status(state)).toBe("ongoing");
    const next = executeMove(state, { type: "fill", colour: 1 });
    expect(completed(next.grid)).toBe(true);
    expect(status(next)).toBe("solved");
  });

  it("reports lost when the move count reaches the limit unsolved", () => {
    // limit 1: a single fill that does not complete the board loses.
    const p: FloodParams = { w: 3, h: 1, colours: 3, leniency: 0 };
    const state = newState(p, "012,1");
    const next = executeMove(state, { type: "fill", colour: 1 });
    // grid is now 1,1,2 — not complete, and moves(1) >= limit(1).
    expect(completed(next.grid)).toBe(false);
    expect(status(next)).toBe("lost");
  });
});

describe("Flood solve", () => {
  it("snaps to a completed, cheated board", () => {
    const p = defaultParams();
    const state = gen(p, "solve-seed");
    const result = floodGame.solve?.(state, state);
    expect(result?.ok).toBe(true);
    if (!result?.ok) return;
    const solved = executeMove(state, result.move);
    expect(completed(solved.grid)).toBe(true);
    expect(solved.cheated).toBe(true);
    expect(solved.moves).toBeGreaterThan(0);
  });

  it("refuses to solve an already-complete board", () => {
    const p: FloodParams = { w: 2, h: 1, colours: 3, leniency: 0 };
    const state = executeMove(newState(p, "01,5"), { type: "fill", colour: 1 });
    expect(floodGame.solve?.(state, state).ok).toBe(false);
  });
});

describe("Flood input mapping", () => {
  const p: FloodParams = { w: 3, h: 3, colours: 3, leniency: 0 };
  const state = newState(p, "011000222,9");
  const ds = floodGame.newDrawState?.(state) ?? null;
  if (ds) floodGame.setTileSize?.(ds, 32);

  it("maps a left-click on a different-colour cell to a fill", () => {
    const fresh = floodGame.newUi(state);
    // Cell (1,0) holds colour 1; border = ts/2 = 16, ts = 32, so x in
    // [48,80) maps to column 1, y in [16,48) to row 0.
    const move = floodGame.interpretMove(
      state,
      fresh,
      ds,
      { x: 56, y: 24 },
      LEFT_BUTTON,
    );
    expect(move).toEqual({ type: "fill", colour: 1 });
  });

  it("ignores a left-click on a same-colour (corner) cell", () => {
    const fresh = floodGame.newUi(state);
    // Cell (0,0) is the corner colour 0.
    const move = floodGame.interpretMove(
      state,
      fresh,
      ds,
      { x: 24, y: 24 },
      LEFT_BUTTON,
    );
    expect(move).toBeNull();
  });

  it("moves the cursor on an arrow key (UI update)", () => {
    const fresh = floodGame.newUi(state);
    const r = floodGame.interpretMove(state, fresh, ds, { x: 0, y: 0 }, CURSOR_RIGHT);
    expect(r).toBe(UI_UPDATE);
    expect(fresh.cx).toBe(1);
    expect(fresh.cursorVisible).toBe(true);
  });

  it("fills the cursor cell on select when it differs", () => {
    const fresh = floodGame.newUi(state);
    floodGame.interpretMove(state, fresh, ds, { x: 0, y: 0 }, CURSOR_RIGHT); // cx=1
    const move = floodGame.interpretMove(
      state,
      fresh,
      ds,
      { x: 0, y: 0 },
      CURSOR_SELECT,
    );
    expect(move).toEqual({ type: "fill", colour: 1 });
  });
});

describe("Flood text format", () => {
  it("emits colour chars per row", () => {
    const p: FloodParams = { w: 3, h: 2, colours: 3, leniency: 0 };
    const state = newState(p, "012210,9");
    expect(textFormat(state)).toBe("012\n210\n");
  });
});

src/native/games/rome/rome-render.test.t.source:
/**
 * Rome rendering tests (tier 2 / 2.5): targeted draw-op assertions plus
 * snapshots of whole frames, driven either through a real `Midend`
 * (`renderScenario`) or by calling `redraw` directly where the frame depends
 * on `Ui` state a scenario cannot set (an in-flight drag, the keyboard mode).
 */
import { describe, expect, it } from "vitest";
import { Midend } from "../../engine/midend.ts";
import { RecordingDrawing } from "../../engine/testing/recording-drawing.ts";
import { renderScenario } from "../../engine/testing/render-scenario.ts";
import { randomNew } from "../../random/index.ts";
import { newRomeDesc } from "./generator.ts";
import { romeGame } from "./index.ts";
import {
  BORDER,
  COL_ARROW_ENTRY,
  COL_ARROW_ERROR,
  COL_ARROW_FIXED,
  COL_ARROW_GUESS,
  COL_ARROW_PENCIL,
  COL_BORDER,
  COL_ERRORBG,
  COL_GOAL,
  COL_GOALBG,
  COL_HIGHLIGHT,
  COL_LOWLIGHT,
  computeSize,
  newDrawState,
  PREFERRED_TILE_SIZE,
  type RomeDrawState,
  redraw,
  setTileSize,
} from "./render.ts";
import { romeSolve, validateGame } from "./solver.ts";
import {
  DIFF_EASY,
  DIFFCOUNT,
  EMPTY,
  FM_ARROWMASK,
  FM_DOWN,
  FM_FIXED,
  FM_LEFT,
  FM_RIGHT,
  FM_UP,
  KEYMODE_PENCIL,
  KEYMODE_PLACE,
  MOUSEMODE_PLACE,
  type RomeMove,
  type RomeParams,
  type RomeState,
  type RomeUi,
  readDesc,
  STATUS_COMPLETE,
  STATUS_INCOMPLETE,
} from "./state.ts";

const TS = PREFERRED_TILE_SIZE;
const PALETTE = romeGame.colours([0.827, 0.827, 0.827]);
/** A fixed board used by most frames — 6x6 Easy, one seed. */
const RENDER_ID = "6x6de#rome-render";

function board(w: number, h: number, desc: string): RomeState {
  const { board: b } = readDesc({ w, h, diff: DIFF_EASY }, desc);
  validateGame(b, true);
  return b;
}

function newUi(): RomeUi {
  return romeGame.newUi({} as RomeState);
}

/** Render one frame directly, so a test can set `Ui` fields a scenario can't. */
function frame(
  state: RomeState,
  ui: RomeUi,
  flashTime = 0,
): { dr: RecordingDrawing; ds: RomeDrawState } {
  const ds = newDrawState(state);
  setTileSize(ds, TS);
  const dr = new RecordingDrawing(PALETTE);
  redraw(dr, ds, null, state, 1, ui, 0, flashTime);
  return { dr, ds };
}

const ALL_WALLS_3 = "12";

// --- geometry ---------------------------------------------------------------

describe("geometry", () => {
  it("uses the NARROW_BORDERS arm, compensating for the outer outline", () => {
    // BORDER = GRIDEXTRA*2 = 2, and computeSize subtracts GRIDEXTRA*2 back off
    // because that outline is drawn inside the border area — not the desktop
    // `tilesize / 2` (playbook §3.2).
    expect(BORDER).toBe(2);
    expect(computeSize({ w: 6, h: 6, diff: 0 }, 40)).toEqual({ w: 242, h: 242 });
  });
});

// --- the grid is negative space ---------------------------------------------

describe("region outlines", () => {
  /** The background rect of the top-left square, whose inset encodes which of
   * its sides border another region. */
  function topLeftTile(desc: string): { w: number; h: number } {
    const { dr } = frame(board(3, 3, desc), newUi());
    const rect = dr.ops.find(
      (o) => o.op === "rect" && o.x === BORDER + 1 && o.y === BORDER + 1,
    );
    if (!rect || rect.op !== "rect") throw new Error("no top-left tile rect");
    return { w: rect.w, h: rect.h };
  }

  it("insets a square's fill on each side that meets a different region", () => {
    // Nothing draws a grid line: each square's rect is inset, and what shows
    // through the COL_BORDER flood is the outline. So a square whose right
    // neighbour shares its region draws *wider* than one whose doesn't.
    const merged = topLeftTile("a11,i"); // squares 0 and 1 share a region
    const separate = topLeftTile(`${ALL_WALLS_3},i`); // every square alone
    expect(merged.w).toBeGreaterThan(separate.w);
    // Vertically both are boundaries, so the heights agree.
    expect(merged.h).toBe(separate.h);
  });

  it("floods the grid colour once, on the first frame only", () => {
    const state = board(3, 3, `${ALL_WALLS_3},i`);
    const ds = newDrawState(state);
    setTileSize(ds, TS);

    const first = new RecordingDrawing(PALETTE);
    redraw(first, ds, null, state, 1, newUi(), 0, 0);
    expect(first.ops.some((o) => o.op === "rect" && o.colour === COL_BORDER)).toBe(
      true,
    );

    // A second redraw of an unchanged board repaints nothing at all.
    const second = new RecordingDrawing(PALETTE);
    redraw(second, ds, null, state, 1, newUi(), 0, 0);
    expect(second.ops).toHaveLength(0);
  });
});

// --- content ----------------------------------------------------------------

describe("board contents", () => {
  it("draws the opening frame: fixed arrows, a goal circle, stable snapshot", () => {
    const result = renderScenario({ game: romeGame, id: RENDER_ID });
    const { ops } = result.recording;
    expect(ops.some((o) => o.op === "line" && o.colour === COL_ARROW_FIXED)).toBe(true);
    expect(ops.some((o) => o.op === "circle" && o.fill === COL_GOAL)).toBe(true);
    expect(ops).toMatchSnapshot();
  });

  it("draws a player's own arrow in the guess colour, not the clue colour", () => {
    const state = board(3, 3, `${ALL_WALLS_3},i`);
    const placed = romeGame.executeMove(state, {
      kind: "place",
      x: 1,
      y: 1,
      dir: FM_UP,
    });
    const { dr } = frame(placed, newUi());
    expect(dr.ops.some((o) => o.op === "line" && o.colour === COL_ARROW_GUESS)).toBe(
      true,
    );
  });

  it("reds a duplicated arrow the player placed, but not the clue it repeats", () => {
    // Squares 0 and 1 share a region; 0 is a fixed down-arrow clue and the
    // player adds a second one at 1. Upstream's colour precedence puts
    // `FM_FIXED` ahead of `FE_DOUBLE`, so a clue never turns red however
    // wrong the region becomes — only the arrow the player can actually fix.
    const state = romeGame.executeMove(board(3, 3, "a11,Dh"), {
      kind: "place",
      x: 1,
      y: 0,
      dir: FM_DOWN,
    });
    const { dr } = frame(state, newUi());
    const red = dr.ops.filter((o) => o.op === "line" && o.colour === COL_ARROW_ERROR);
    // One arrow's worth of strokes: a shaft plus two head lines.
    expect(red).toHaveLength(3);
    expect(dr.ops.some((o) => o.op === "line" && o.colour === COL_ARROW_FIXED)).toBe(
      true,
    );
  });

  it("reddens the background of an arrow that leaves the grid", () => {
    const { dr } = frame(board(3, 3, `${ALL_WALLS_3},bRf`), newUi());
    expect(dr.ops.some((o) => o.op === "rect" && o.colour === COL_ERRORBG)).toBe(true);
  });

  it("draws pencil marks as small arrows in the four quadrants", () => {
    let state = board(3, 3, `${ALL_WALLS_3},i`);
    state = romeGame.executeMove(state, { kind: "pencil", x: 1, y: 1, dir: FM_UP });
    state = romeGame.executeMove(state, { kind: "pencil", x: 1, y: 1, dir: FM_RIGHT });
    const { dr } = frame(state, newUi());
    const pencilLines = dr.ops.filter(
      (o) => o.op === "line" && o.colour === COL_ARROW_PENCIL,
    );
    // Two marks × (one shaft + two head strokes).
    expect(pencilLines).toHaveLength(6);
  });

  it("hides pencil marks once the square holds an arrow", () => {
    let state = board(3, 3, `${ALL_WALLS_3},i`);
    state = romeGame.executeMove(state, { kind: "pencil", x: 1, y: 1, dir: FM_UP });
    state = romeGame.executeMove(state, { kind: "place", x: 1, y: 1, dir: FM_LEFT });
    const { dr } = frame(state, newUi());
    expect(dr.ops.some((o) => o.op === "line" && o.colour === COL_ARROW_PENCIL)).toBe(
      false,
    );
  });
});

// --- highlight preferences --------------------------------------------------

describe("highlight preferences", () => {
  it("tints the squares that reach a goal, and only while the pref is on", () => {
    // Goal at 4, an arrow at 1 pointing down into it.
    const state = board(3, 3, `${ALL_WALLS_3},aDbXd`);
    const goalBg = (sgoals: boolean): boolean =>
      frame(state, { ...newUi(), sgoals }).dr.ops.some(
        (o) => o.op === "rect" && o.colour === COL_GOALBG,
      );
    expect(goalBg(true)).toBe(true);
    expect(goalBg(false)).toBe(false);
  });

  it("tints loop squares only when the loop pref is turned on", () => {
    const state = board(3, 3, `${ALL_WALLS_3},RDaULd`);
    const loopBg = (sloops: boolean): number =>
      frame(state, { ...newUi(), sloops }).dr.ops.filter(
        (o) => o.op === "rect" && o.colour === COL_ERRORBG,
      ).length;
    // Four looping squares light up; with the pref off (upstream's default)
    // none do, since no arrow here leaves the grid.
    expect(loopBg(true)).toBe(4);
    expect(loopBg(false)).toBe(0);
  });
});

// --- cursor and drag --------------------------------------------------------

describe("cursor and drag", () => {
  it("distinguishes the armed-to-place cursor from the armed-to-pencil one", () => {
    const state = board(3, 3, `${ALL_WALLS_3},i`);
    const place = frame(state, { ...newUi(), hx: 1, hy: 1, kmode: KEYMODE_PLACE }).dr;
    const pencil = frame(state, { ...newUi(), hx: 1, hy: 1, kmode: KEYMODE_PENCIL }).dr;
    expect(place.ops.some((o) => o.op === "rect" && o.colour === COL_HIGHLIGHT)).toBe(
      true,
    );
    expect(pencil.ops.some((o) => o.op === "rect" && o.colour === COL_LOWLIGHT)).toBe(
      true,
    );
    // Pencil mode additionally shows a '?' prompt in the cursor square.
    expect(pencil.ops.some((o) => o.op === "text" && o.text === "?")).toBe(true);
  });

  it("previews the direction an in-flight drag currently points at", () => {
    const state = board(3, 3, `${ALL_WALLS_3},i`);
    const ui: RomeUi = {
      ...newUi(),
      hx: 1,
      hy: 1,
      mmode: MOUSEMODE_PLACE,
      mdir: FM_DOWN,
    };
    const { dr } = frame(state, ui);
    expect(dr.ops.some((o) => o.op === "line" && o.colour === COL_ARROW_ENTRY)).toBe(
      true,
    );
  });

  it("marks a grabbed square that has no direction yet with a dot", () => {
    const state = board(3, 3, `${ALL_WALLS_3},i`);
    const ui: RomeUi = {
      ...newUi(),
      hx: 1,
      hy: 1,
      mmode: MOUSEMODE_PLACE,
      mdir: EMPTY,
    };
    const { dr } = frame(state, ui);
    expect(
      dr.ops.some(
        (o) =>
          o.op === "rect" && o.colour === COL_ARROW_ENTRY && o.w === 4 && o.h === 4,
      ),
    ).toBe(true);
  });
});

// --- completion flash -------------------------------------------------------

describe("completion flash", () => {
  it("cycles three phases, so consecutive frames differ", () => {
    const state = board(3, 3, `${ALL_WALLS_3},i`);
    // Phase index is `floor(flashTime / 0.1) % 3`, so 0.65 and 0.55 are
    // different beats — a snapshot alone would not show the animation moving.
    const phase = (flashTime: number): string =>
      JSON.stringify(
        frame(state, newUi(), flashTime).dr.ops.filter((o) => o.op === "rect"),
      );
    expect(phase(0.65)).not.toBe(phase(0.55));
    const flashing = frame(state, newUi(), 0.65).dr;
    expect(
      flashing.ops.some((o) => o.op === "rect" && o.colour === COL_HIGHLIGHT),
    ).toBe(true);
    expect(flashing.ops.some((o) => o.op === "rect" && o.colour === COL_LOWLIGHT)).toBe(
      true,
    );
  });

  it("hides the keyboard cursor while the board celebrates", () => {
    const state = board(3, 3, `${ALL_WALLS_3},i`);
    const ui: RomeUi = { ...newUi(), hx: 1, hy: 1, kmode: KEYMODE_PENCIL };
    expect(frame(state, ui, 0.65).dr.ops.some((o) => o.op === "text")).toBe(false);
  });
});

// --- mistake overlay --------------------------------------------------------

describe("mistake overlay", () => {
  it("highlights a mistake even when the square was already drawn", () => {
    // Regression guard for playbook §3.2: the overlay isn't part of the tile
    // value, so it must be in the diff cache key. Check & Save runs a frame
    // *after* the move that drew the square, so a cold first frame proves
    // nothing — this asserts the highlight appears on the SECOND paint, and
    // disappears again on a third once the overlay is cleared.
    const { desc, index, wrong } = legalLookingMistake();
    const me = new Midend(romeGame);
    expect(me.newGameFromId(`6x6de:${desc}`)).toBeUndefined();
    const move: RomeMove = {
      kind: "place",
      x: index % 6,
      y: Math.floor(index / 6),
      dir: wrong,
    };
    me.playMoves([move]);

    const first = new RecordingDrawing(PALETTE);
    me.redraw(first);
    const errorOutline = (r: RecordingDrawing): boolean =>
      r.ops.some((o) => o.op === "line" && o.colour === COL_ARROW_ERROR);
    // No rule is broken yet, so nothing is red on the first paint.
    expect(errorOutline(first)).toBe(false);

    expect(me.findMistakes()).toBe(1);
    const second = new RecordingDrawing(PALETTE);
    me.redraw(second);
    expect(errorOutline(second)).toBe(true);

    // The overlay is ephemeral: the next move clears it, and the square
    // repaints without the ring.
    me.playMoves([{ ...move, dir: null }]);
    const third = new RecordingDrawing(PALETTE);
    me.redraw(third);
    expect(errorOutline(third)).toBe(false);
  });
});

/**
 * A fixed-seed scan for a 6x6 board with a square where a wrong arrow can be
 * placed that breaks no rule — the case only the re-solve layer of
 * `findMistakes` can catch.
 */
function legalLookingMistake(): {
  desc: string;
  index: number;
  wrong: 4 | 8 | 16 | 32;
} {
  const p: RomeParams = { w: 6, h: 6, diff: DIFF_EASY };
  for (let seed = 0; seed < 40; seed++) {
    const { desc } = newRomeDesc(p, randomNew(`rome-render-mistake-${seed}`));
    const state = board(p.w, p.h, desc);
    const solved = board(p.w, p.h, desc);
    if (romeSolve(solved, DIFFCOUNT) !== STATUS_COMPLETE) continue;

    for (let i = 0; i < state.grid.length; i++) {
      if (state.grid[i] !== EMPTY) continue;
      const right = solved.grid[i] & FM_ARROWMASK;
      for (const wrong of [FM_UP, FM_DOWN, FM_LEFT, FM_RIGHT] as const) {
        if (wrong === right) continue;
        const trial = romeGame.executeMove(state, {
          kind: "place",
          x: i % p.w,
          y: Math.floor(i / p.w),
          dir: wrong,
        });
        if (validateGame(trial, true) !== STATUS_INCOMPLETE) continue;
        if (state.grid[i] & FM_FIXED) continue;
        return { desc, index: i, wrong };
      }
    }
  }
  throw new Error("no legal-looking wrong placement found");
}

src/native/games/loopy/loopy-differentia.source:
/**
 * Byte-match differential for the Loopy generator, solver and codec.
 *
 * **This is the assertion that validates the whole port at once.** Loopy's
 * generator is solver-gated at every step — `gameHasUniqueSoln` decides each
 * clue removal, each board retry and the too-easy rejection — so the emitted
 * description depends on the solver's verdict about every intermediate board.
 * A single wrong deduction anywhere in the ~1,100 lines of `solver.ts`, a
 * single RNG draw out of order in `generator.ts` or `loopgen.ts`, or one
 * off-by-one in the run-length clue encoding, and the description differs.
 * Nothing else available is as strong.
 *
 * It is also this change's first real exercise of `extend-grid-tilings` and
 * `add-aperiodic-tilings`, which shipped with no user-visible surface and were
 * accepted on the explicit basis that Loopy would be their first acceptance
 * test. Hence the matrix is skewed to **breadth**: all 18 grid types appear.
 *
 * Regenerate the fixture with:
 *   scripts/build-native.sh loopy-trace && build/native/auxiliary/loopy-trace \
 *     > src/native/games/loopy/__fixtures__/loopy-c-reference.json
 *
 * **What this cannot cover**, and where to look instead: the C *aborts* on a
 * degenerate Penrose patch and *hangs* on an unfavourable one, so no fixture
 * can be recorded for either. Those paths are the TS port's own recovery (see
 * `grid-build.ts` and `generator.ts`) and are covered by `loopy.test.ts`.
 */
import { describe, expect, it } from "vitest";
import { randomNew } from "../../random/index.ts";
import reference from "./__fixtures__/loopy-c-reference.json" with { type: "json" };
import { newDesc } from "./generator.ts";
import { encodeParams, LOOPY_DIFFS, LOOPY_GRIDS, type LoopyParams } from "./params.ts";
import { solveGame } from "./solver.ts";
import { newState, validateDesc } from "./state.ts";

interface LoopyFixture {
  /** Loopy's own grid-type index — not `grid.ts`'s `GRIDGEN_LIST` ordering. */
  type: number;
  typeName: string;
  w: number;
  h: number;
  /** The difficulty's params character (`e`/`n`/`t`/`h`). */
  diff: string;
  diffIndex: number;
  /** The C's `encode_params(params, true)`. */
  params: string;
  seed: string;
  /** The C's generated game description. */
  desc: string;
}

const fixtures = (reference as { fixtures: LoopyFixture[] }).fixtures;

const paramsOf = (f: LoopyFixture): LoopyParams => ({
  w: f.w,
  h: f.h,
  diff: f.diffIndex,
  type: f.type,
});

describe("loopy C differential", () => {
  it("covers every grid type and every difficulty", () => {
    // The point of the matrix, asserted rather than assumed: a fixture file
    // regenerated with a narrower matrix should fail loudly, not silently
    // weaken the guarantee.
    expect(new Set(fixtures.map((f) => f.type)).size).toBe(LOOPY_GRIDS.length);
    expect(new Set(fixtures.map((f) => f.diff)).size).toBe(LOOPY_DIFFS.length);
  });

  for (const f of fixtures) {
    describe(`${f.typeName} ${f.w}x${f.h} ${f.diff} (${f.seed})`, () => {
      it("encodes the same params string as the C", () => {
        expect(encodeParams(paramsOf(f), true)).toBe(f.params);
      });

      it("generates the same description, byte for byte", () => {
        const { desc } = newDesc(paramsOf(f), randomNew(f.seed));
        expect(desc).toBe(f.desc);
      });

      it("accepts and grades the C's board at exactly its recorded difficulty", () => {
        // Independent of the byte-match above: this checks the solver against a
        // board the C built, so it still says something if the generator and
        // the solver ever diverged together.
        const p = paramsOf(f);
        expect(validateDesc(p, f.desc)).toBeNull();
        const state = newState(p, f.desc);
        expect(solveGame(state, p.diff).status).toBe("solved");
        if (p.diff > 0) {
          // The generator rejects a board solvable one rung easier, so the C's
          // board must genuinely need the difficulty it claims.
          expect(solveGame(state, p.diff - 1).status).not.toBe("solved");
        }
      });
    });
  }
});

