/**
 * Gated byte-match differential for the Group port.
 *
 * For each frozen C-reference fixture (sizes 4..12, both identity modes, every
 * difficulty each size admits), assert the TS generator reproduces the C desc
 * byte-for-byte over the bit-identical RNG, and that the TS solver grades the
 * board at the same minimal difficulty the C solver recorded. Because the
 * generator is solver-gated, that single byte-match validates the generator,
 * the solver's every deduction, the group data table and the codec together —
 * the strongest available bar (playbook §4.3/§4.4, design D8).
 *
 * Regenerate the fixture from `puzzles/auxiliary/group-trace.c` (pure-C):
 *   cmake -B build/native -S puzzles -DUSE_TS_RANDOM=0
 *   (cd build/native && make group-trace)
 *   build/native/auxiliary/group-trace \
 *     > src/native/games/group/__fixtures__/group-c-reference.json
 */

import { describe, expect, it } from "vitest";
import { randomNew } from "../../random/index.ts";
import reference from "./__fixtures__/group-c-reference.json" with { type: "json" };
import { newGameDesc } from "./generator.ts";
import { solveGroup } from "./solver.ts";
import { type GroupParams, newState, validateDesc } from "./state.ts";

interface Fixture {
  w: number;
  diff: number;
  id: boolean;
  seed: string;
  desc: string;
  solverDiff: number;
}

const FIXTURES = reference.fixtures as Fixture[];

const params = (f: Fixture): GroupParams => ({ w: f.w, diff: f.diff, id: f.id });

describe("group differential (byte-match + solver agreement)", () => {
  for (const f of FIXTURES) {
    const label = `${f.w}d${f.diff}${f.id ? "" : "i"} (seed ${f.seed})`;

    it(`${label}: desc matches C byte-for-byte`, () => {
      const { desc } = newGameDesc(params(f), randomNew(f.seed));
      expect(desc).toBe(f.desc);
      expect(validateDesc(params(f), desc)).toBeNull();
    });

    it(`${label}: TS solver grades at the C difficulty`, () => {
      const givens = newState(params(f), f.desc).grid.slice();
      const ret = solveGroup(givens, f.w, f.solverDiff);
      expect(ret).toBe(f.solverDiff);
    });
  }
});

src/native/games/salad/salad-render.test.source:
/**
 * Tier-2.5 render scenarios for Salad, plus the two tier-2 frames the scenario
 * driver cannot reach (they depend on `Ui` state, which `renderScenario`
 * replays no pointer events to set).
 *
 * Each scenario pairs targeted op assertions — the real guarantee — with a
 * `toMatchSnapshot` so unintended drift shows up as a reviewable text diff.
 * Re-baseline an intended change with `vitest -u` and commit the regenerated
 * `__snapshots__/*.snap`.
 */
import { describe, expect, it } from "vitest";
import { RecordingDrawing } from "../../engine/testing/recording-drawing.ts";
import {
  DEFAULT_BACKGROUND,
  renderScenario,
} from "../../engine/testing/render-scenario.ts";
import { saladGame } from "./index.ts";
import {
  COL_BACKGROUND,
  COL_BORDERCLUE,
  COL_G_HOLE,
  COL_HIGHLIGHT,
  COL_HINT,
  COL_HINT_CELL,
  COL_I_BALLBG,
  COL_I_HOLE,
  COL_LOWLIGHT,
  COL_MISTAKE,
  COL_PENCIL,
  COL_PENCIL_BODY,
  FLASH_TIME,
  newDrawState,
  redraw,
  setTileSize,
} from "./render.ts";
import { saladSolution } from "./solver.ts";
import {
  DIFF_EASY,
  GAMEMODE_LETTERS,
  GAMEMODE_NUMBERS,
  newState,
  newUi,
  type SaladMove,
  type SaladParams,
} from "./state.ts";

const LETTERS_P: SaladParams = {
  order: 4,
  nums: 3,
  mode: GAMEMODE_LETTERS,
  diff: DIFF_EASY,
};
const LETTERS_DESC = "CaCbAfBaAa,p";
const LETTERS_ID = `4n3Lde:${LETTERS_DESC}`;

const NUMBERS_P: SaladParams = {
  order: 5,
  nums: 3,
  mode: GAMEMODE_NUMBERS,
  diff: DIFF_EASY,
};
const NUMBERS_DESC = "d1cO32b3aXa1d2b";
const NUMBERS_ID = `5n3Bde:${NUMBERS_DESC}`;

describe("salad render scenarios", () => {
  it("draws the ABC End View border clues in the margin", () => {
    const { recording } = renderScenario({ game: saladGame, id: LETTERS_ID });
    const clues = recording.ops.filter(
      (o) => o.op === "text" && o.colour === COL_BORDERCLUE,
    );
    // The reference board carries five border clues (C, C, A, B, A).
    expect(clues).toHaveLength(5);
    expect(clues.map((o) => (o.op === "text" ? o.text : "")).sort()).toEqual([
      "A",
      "A",
      "B",
      "C",
      "C",
    ]);
    expect(recording.ops).toMatchSnapshot();
  });

  it("does not let a border clue's erase wipe the grid's outline", () => {
    // Regression (owner-reported): the four clue tiles abut the play area, and
    // the grid's outermost boundary lines are drawn by the neighbouring *cells*
    // on the shared pixel. A clue that erases its whole tile therefore rubs out
    // the boundary — which happened on the right edge, so every row carrying a
    // right-hand clue lost its outer cell border. Assert the invariant (no
    // background fill may cover a boundary line) rather than the pixel offset,
    // so a different fix still passes.
    const ts = saladGame.preferredTileSize ?? 32;
    const o = LETTERS_P.order;
    const { recording } = renderScenario({ game: saladGame, id: LETTERS_ID });

    // The grid's outline, as a closed box: the cells paint their borders on
    // `x = ts`/`x = (o+1)·ts` and `y = ts−1`/`y = (o+1)·ts−1`. No clue-tile
    // erase may touch it.
    const box = {
      x0: ts,
      x1: (o + 1) * ts,
      y0: ts - 1,
      y1: (o + 1) * ts - 1,
    };
    // Only the clue-tile erases matter: they are the background fills smaller
    // than a whole tile (a cell's own repaint is `ts × ts` and legitimately
    // repaints its own borders straight afterwards).
    const erases = recording.ops.filter(
      (op) => op.op === "rect" && op.colour === COL_BACKGROUND && op.w < ts,
    );
    expect(erases.length).toBeGreaterThan(0);
    for (const e of erases) {
      if (e.op !== "rect") continue;
      const overlaps =
        e.x <= box.x1 &&
        e.x + e.w - 1 >= box.x0 &&
        e.y <= box.y1 &&
        e.y + e.h - 1 >= box.y0;
      expect({ x: e.x, y: e.y, overlaps }).toEqual({ x: e.x, y: e.y, overlaps: false });
    }
  });

  it("draws Number Ball's balls and crosses", () => {
    const { recording } = renderScenario({ game: saladGame, id: NUMBERS_ID });
    // A ball is two concentric circles; a *given* one takes the immutable
    // ball background.
    expect(
      recording.ops.some((o) => o.op === "circle" && o.fill === COL_I_BALLBG),
    ).toBe(true);
    // A given cross is two thick strokes in the immutable hole colour, and
    // none is drawn in the player's guess colour on an untouched board.
    expect(recording.ops.some((o) => o.op === "line" && o.colour === COL_I_HOLE)).toBe(
      true,
    );
    expect(recording.ops.some((o) => o.op === "line" && o.colour === COL_G_HOLE)).toBe(
      false,
    );
    expect(recording.ops).toMatchSnapshot();
  });

  it("draws pencil marks after Mark all", () => {
    const moves: SaladMove[] = [{ type: "markAll" }];
    const { recording } = renderScenario({
      game: saladGame,
      id: NUMBERS_ID,
      moves,
    });
    const notes = recording.ops.filter(
      (o) => o.op === "text" && o.colour === COL_PENCIL,
    );
    expect(notes.length).toBeGreaterThan(0);
    // The "might be empty" mark renders as an X alongside the digits.
    expect(notes.some((o) => o.op === "text" && o.text === "X")).toBe(true);
    expect(recording.ops).toMatchSnapshot();
  });

  it("outlines a Check & Save mistake in red", () => {
    const s = newState(NUMBERS_P, NUMBERS_DESC);
    const sol = saladSolution(s);
    if (!sol) throw new Error("expected a solution");
    const o = s.order;
    const i = sol.findIndex((v, k) => v > 0 && !s.gridclues[k]);
    const { recording, mistakeCount } = renderScenario({
      game: saladGame,
      id: NUMBERS_ID,
      moves: [
        { type: "set", x: i % o, y: (i / o) | 0, value: (sol[i] % NUMBERS_P.nums) + 1 },
      ],
      showMistakes: true,
    });
    expect(mistakeCount).toBeGreaterThan(0);
    expect(
      recording.ops.some((op) => op.op === "line" && op.colour === COL_MISTAKE),
    ).toBe(true);
    expect(recording.ops).toMatchSnapshot();
  });
});

describe("salad hint frames", () => {
  /** Reach the first plan step whose narration matches, leaving it displayed but
   * not applied. */
  const hintFrame = (id: string, re: RegExp) =>
    renderScenario({
      game: saladGame,
      id,
      showHint: true,
      hintUntil: (step) => re.test(step.explanation),
    });

  it("shades the run a clue's symbol is confined to, and lights the clue", () => {
    // The far arm: the clue's own symbol can sit only within the line's hole
    // budget of the clue, so the squares beyond it lose that candidate. The
    // shaded run is where it *can* be — the premise as an area, not one cell
    // (§5.2).
    const { recording, hint } = hintFrame(LETTERS_ID, /has room for only/);
    expect(hint?.explanation).toMatch(/has room for only \d+ empty square/);
    const shaded = recording.ops.filter(
      (o) => o.op === "rect" && o.colour === COL_HINT_CELL,
    );
    expect(shaded.length).toBeGreaterThan(1);
    // The premise is only visible if the clue glyph is part of the highlight
    // (design D8): it is redrawn in COL_HINT rather than the usual clue colour.
    expect(recording.ops.some((o) => o.op === "text" && o.colour === COL_HINT)).toBe(
      true,
    );
    // Each square acted on is ringed in COL_HINT, so its struck notes stay
    // legible against the light shade (§5.4).
    expect(
      recording.ops.some((o) => o.op === "polygon" && o.outline === COL_HINT),
    ).toBe(true);
    expect(recording.ops).toMatchSnapshot();
  });

  it("shades the nearest square a clue can see, when that is the whole premise", () => {
    // The near arm on a board with one empty square per line: the run really is
    // a single square, and saying so is honest rather than a missing area.
    const { recording, hint } = hintFrame(
      LETTERS_ID,
      /so nothing but [A-C] can go here/,
    );
    expect(hint?.explanation).toMatch(/and this is the nearest square to it/);
    expect(
      recording.ops.filter((o) => o.op === "rect" && o.colour === COL_HINT_CELL),
    ).toHaveLength(1);
    expect(recording.ops.some((o) => o.op === "text" && o.colour === COL_HINT)).toBe(
      true,
    );
  });

  it("previews an empty-square marker as a cross in the hint colour", () => {
    const { recording, hint } = hintFrame(
      NUMBERS_ID,
      /so every other square in it must be empty|must be empty\.$/,
    );
    expect(hint?.explanation).toMatch(/must be empty/);
    // §5.1a: Salad writes three shapes, so the hint echoes the one it is asking
    // for — here the two strokes of a cross, in COL_HINT.
    const strokes = recording.ops.filter(
      (o) => o.op === "line" && o.colour === COL_HINT,
    );
    expect(strokes.length).toBeGreaterThanOrEqual(2);
    expect(recording.ops).toMatchSnapshot();
  });

  it("previews a holds-a-symbol marker as a ball in the hint colour", () => {
    const { recording, hint } = hintFrame(
      NUMBERS_ID,
      /must hold a number|holds a number/,
    );
    expect(hint?.explanation).toMatch(/hold a number|holds a number/);
    expect(recording.ops.some((o) => o.op === "circle" && o.outline === COL_HINT)).toBe(
      true,
    );
    expect(recording.ops).toMatchSnapshot();
  });

  it("previews a placement as its own symbol, and strikes what it rules out", () => {
    const { recording, hint } = hintFrame(NUMBERS_ID, /it can only be \d/);
    const want = hint?.explanation.match(/it can only be (\d)/)?.[1];
    expect(want).toBeDefined();
    expect(
      recording.ops.some(
        (o) => o.op === "text" && o.colour === COL_HINT && o.text === want,
      ),
    ).toBe(true);
    expect(recording.ops).toMatchSnapshot();
  });

  it("crosses a struck candidate through, keeping the note itself legible", () => {
    // The Towers convention: the struck note keeps COL_PENCIL (so it still reads
    // as a real note) and gains a strikethrough in the same colour.
    const { recording } = hintFrame(NUMBERS_ID, /There's already a \d/);
    const notes = recording.ops.filter(
      (o) => o.op === "text" && o.colour === COL_PENCIL,
    );
    const rules = recording.ops.filter(
      (o) => o.op === "line" && o.colour === COL_PENCIL,
    );
    expect(notes.length).toBeGreaterThan(0);
    expect(rules.length).toBeGreaterThan(0);
  });
});

// --- tier 2: frames that depend on Ui state --------------------------------

/** Paint one frame straight against the game's `redraw`, so the `Ui` (cursor,
 * pencil mode) and the flash clock can be set explicitly. */
function paint(
  state: ReturnType<typeof newState>,
  ui: ReturnType<typeof newUi>,
  flashTime = 0,
): RecordingDrawing {
  const ds = newDrawState(state);
  setTileSize(ds, saladGame.preferredTileSize ?? 32);
  const rec = new RecordingDrawing(saladGame.colours(DEFAULT_BACKGROUND));
  redraw(rec, ds, null, state, 0, ui, 0, flashTime);
  return rec;
}

describe("salad Ui-driven frames", () => {
  it("fills the selected square, and shows a corner triangle in pencil mode", () => {
    const s = newState(LETTERS_P, LETTERS_DESC);
    const ui = { ...newUi(s), hshow: true, hx: 1, hy: 2 };

    const ink = paint(s, ui);
    expect(
      ink.ops.some(
        (o) => o.op === "rect" && o.colour === COL_LOWLIGHT && o.w === 40 && o.h === 40,
      ),
    ).toBe(true);
    // No pencil-mode glyph while entering ink.
    expect(ink.ops.some((o) => o.op === "polygon" && o.fill === COL_PENCIL_BODY)).toBe(
      false,
    );

    const pencil = paint(s, { ...ui, hpencil: true });
    // The pencil highlight is a half-tile corner triangle, not a full fill.
    expect(
      pencil.ops.some(
        (o) => o.op === "polygon" && o.fill === COL_LOWLIGHT && o.points.length === 3,
      ),
    ).toBe(true);
    // ...and the CapsLock-style indicator appears in the clue margin.
    expect(
      pencil.ops.some((o) => o.op === "polygon" && o.fill === COL_PENCIL_BODY),
    ).toBe(true);
  });

  it("plays the completion flash as a moving three-phase wave", () => {
    const s = newState(LETTERS_P, LETTERS_DESC);
    const ui = newUi(s);
    // Two phases of the same flash must paint *differently* — a snapshot alone
    // cannot tell you an animation is moving (playbook §3.2).
    const phaseA = paint(s, ui, FLASH_TIME);
    const phaseB = paint(s, ui, FLASH_TIME - 0.1);
    const wave = (r: RecordingDrawing) =>
      r.ops
        .filter((o) => o.op === "rect" && o.colour === COL_HIGHLIGHT)
        .map((o) => (o.op === "rect" ? `${o.x},${o.y}` : ""))
        .join(" ");
    expect(wave(phaseA)).not.toBe("");
    expect(wave(phaseA)).not.toBe(wave(phaseB));
  });
});

src/native/games/bridges/bridges-differe.source:
/**
 * Gated C-vs-TS differential for the Bridges port. Reads the committed fixture
 * recorded from upstream bridges.c (puzzles/auxiliary/bridges-trace.c) and
 * asserts:
 *
 *  1. TS `newDesc` over the same seed reproduces the C desc **byte-for-byte** —
 *     the generator is a faithful port, its accept/reject decisions are made by
 *     identical solver verdicts, and the RNG is bit-identical.
 *  2. The TS solver solves each C-generated board at the recorded difficulty
 *     and (for a Medium/Hard board with enough islands) does NOT solve it one
 *     level down — the same "too easy" gate the generator applied.
 *
 * Regenerate the fixture (while bridges.c still exists) with:
 *   cmake -B build/native -S puzzles -DUSE_TS_RANDOM=0
 *   (cd build/native && make bridges-trace)
 *   build/native/auxiliary/bridges-trace \
 *     > src/native/games/bridges/__fixtures__/bridges-c-reference.json
 */
import { describe, expect, it } from "vitest";
import { describeDescDifferential } from "../../engine/testing/differential.ts";
import cReference from "./__fixtures__/bridges-c-reference.json" with { type: "json" };
import { newBridgesDesc } from "./generator.ts";
import { solveFromScratch } from "./solver.ts";
import { type BridgesParams, newStateFromDesc, validateDesc } from "./state.ts";

interface Fixture {
  w: number;
  h: number;
  maxb: number;
  islands: number;
  expansion: number;
  allowloops: boolean;
  difficulty: number;
  seed: string;
  desc: string;
}

const data = cReference as { fixtures: Fixture[] };

const MIN_SENSIBLE_ISLANDS = 3;

const params = (f: Fixture): BridgesParams => ({
  w: f.w,
  h: f.h,
  maxb: f.maxb,
  islands: f.islands,
  expansion: f.expansion,
  allowloops: f.allowloops,
  difficulty: f.difficulty,
});

const label = (f: Fixture) =>
  `${f.w}x${f.h} m${f.maxb}${f.allowloops ? "" : "L"} d${f.difficulty} seed=${f.seed}`;

// 1. Byte-for-byte desc match (plus the desc validating, for free).
describeDescDifferential<Fixture, BridgesParams>({
  title: "Bridges C-vs-TS differential — desc byte-match (gated)",
  fixtures: data.fixtures,
  label,
  params,
  newDesc: newBridgesDesc,
  extra: (f, p) => {
    expect(validateDesc(p, f.desc)).toBeNull();
  },
});

// 2. Solver agreement — the TS solver grades every C board like C did.
describe("Bridges C-vs-TS differential — solver agreement (gated)", () => {
  for (const f of data.fixtures) {
    const p = params(f);
    it(`${label(f)}: TS solver solves at difficulty ${f.difficulty}`, () => {
      const state = newStateFromDesc(p, f.desc);
      expect(solveFromScratch(state.workingCopy(), f.difficulty)).toBe(1);

      // The "too easy" gate: a Medium/Hard board with more than the sensible
      // minimum of islands must not solve one difficulty down.
      if (f.difficulty > 0 && state.islands.length > MIN_SENSIBLE_ISLANDS) {
        expect(solveFromScratch(state.workingCopy(), f.difficulty - 1)).toBe(0);
      }
    });
  }
});

src/native/games/magnets/magnets-differe.source:
/**
 * Gated C-vs-TS differential for magnets (openspec add-magnets-ts-port).
 *
 * Byte-for-byte desc match: the generator is a faithful port over the
 * bit-identical `random.ts` — the `dominoLayout` shuffles, the `layDominoes`
 * scratch shuffle, and the strip-clues shuffle all reproduce C's draws — so
 * `newDesc(params, randomNew(seed)).desc` reproduces C exactly (playbook
 * §4.3). Two follow-on assertions (§4.4): the recorded aux (C's solution)
 * matches, and the TS solver grades each C board at exactly the recorded
 * difficulty (solves at diff; for a Tricky board, fails at Easy) — the
 * generator is solver-gated, so the TS solver must reach C's verdict.
 *
 * Regenerate the frozen fixture while puzzles/magnets.c still exists (it is
 * deleted at acceptance):
 *   cmake -B build/native -S puzzles -DUSE_TS_RANDOM=0
 *   (cd build/native && make magnets-trace)
 *   build/native/auxiliary/magnets-trace \
 *     > src/native/games/magnets/__fixtures__/magnets-c-reference.json
 */
import { expect } from "vitest";
import { describeDescDifferential } from "../../engine/testing/differential.ts";
import { randomNew } from "../../random/index.ts";
import cReference from "./__fixtures__/magnets-c-reference.json" with { type: "json" };
import { newMagnetsDesc } from "./generator.ts";
import { MagnetsSolver } from "./solver.ts";
import { DIFF_COUNT, DIFF_EASY, type MagnetsParams, newState } from "./state.ts";

interface Fixture {
  w: number;
  h: number;
  diff: number;
  stripclues: boolean;
  seed: string;
  desc: string;
  aux: string;
}
const data = cReference as { fixtures: Fixture[] };

describeDescDifferential<Fixture, MagnetsParams>({
  title: "magnets differential (frozen C reference)",
  fixtures: data.fixtures,
  label: (f) => `${f.w}x${f.h} d${f.diff}${f.stripclues ? "S" : ""} seed=${f.seed}`,
  params: (f) => ({ w: f.w, h: f.h, diff: f.diff, stripclues: f.stripclues }),
  newDesc: newMagnetsDesc,
  extra: (f, p) => {
    // The generated aux (solution) matches C's.
    const { aux } = newMagnetsDesc(p, randomNew(f.seed));
    expect(aux).toBe(f.aux);

    // The TS solver grades the C board at exactly the recorded difficulty.
    const s = newState(p, f.desc);
    const solver = new MagnetsSolver(
      s.w,
      s.h,
      s.common.dominoes,
      s.common.rowcount,
      s.common.colcount,
    );
    expect(solver.solve(DIFF_COUNT)).toBe(1); // uniquely solvable
    if (f.diff > DIFF_EASY) {
      const easier = new MagnetsSolver(
        s.w,
        s.h,
        s.common.dominoes,
        s.common.rowcount,
        s.common.colcount,
      );
      expect(easier.solve(f.diff - 1)).toBeLessThanOrEqual(0); // ambiguous one level down
    }
  },
});

