// Tier-1 midend integration: drive the real `Midend` with Range from a
// generated id through the Solve command, an honest move-by-move solve,
// and the mistake overlay.
import { describe, expect, it } from "vitest";
import type { ChangeNotification, GameStatus } from "../../../puzzle/types.ts";
import { Midend } from "../../engine/midend.ts";
import { LEFT_BUTTON, RIGHT_BUTTON } from "../../engine/pointer.ts";
import { randomNew } from "../../random/index.ts";
import { rangeGame } from "./index.ts";
import { fullSolve } from "./solver.ts";
import { BLACK, decodeParams, idx, newState, type RangeMove, WHITE } from "./state.ts";

function harness() {
  const notes: ChangeNotification[] = [];
  const m = new Midend(rangeGame);
  m.setCallbacks(
    (n) => notes.push(n),
    () => {},
    () => {},
  );
  const status = (): GameStatus | undefined =>
    (
      [...notes].reverse().find((n) => n.type === "game-state-change") as
        | Extract<ChangeNotification, { type: "game-state-change" }>
        | undefined
    )?.status;
  const hintBanner = (): string | undefined =>
    (
      [...notes].reverse().find((n) => n.type === "status-bar-change") as
        | Extract<ChangeNotification, { type: "status-bar-change" }>
        | undefined
    )?.activeHintExplanation;
  return { m, status, hintBanner };
}

describe("midend integration", () => {
  it("starts ongoing and the Solve command finishes with help", () => {
    const { m, status } = harness();
    expect(m.newGameFromId("9x6#range-mid-solve")).toBeUndefined();
    expect(status()).toBe("ongoing");
    expect(m.solve()).toBeUndefined();
    expect(status()).toBe("solved-with-help");
  });

  it("reaches a plain solved state by playing the solution's moves", () => {
    const params = decodeParams("9x6");
    const { desc } = rangeGame.newDesc(params, randomNew("range-mid-play"));
    const solution = fullSolve(newState(params, desc).grid, params.w, params.h);
    if (!solution) throw new Error("expected solvable");

    const { m, status } = harness();
    expect(m.newGameFromId(`9x6:${desc}`)).toBeUndefined();

    const moves: RangeMove[] = [];
    for (let r = 0; r < params.h; r++) {
      for (let c = 0; c < params.w; c++) {
        const v = solution[idx(r, c, params.w)];
        if (v === BLACK) moves.push({ sets: [{ r, c, value: "black" }] });
        else if (v === WHITE) moves.push({ sets: [{ r, c, value: "white" }] });
      }
    }
    m.playMoves(moves);
    expect(status()).toBe("solved");
  });

  it("surfaces the hint explanation without a status bar and clears it on a move", () => {
    // Range has wantsStatusbar=false but explained hints; the banner
    // (activeHintExplanation) must still be emitted, and cleared by a move.
    const params = decodeParams("9x6");
    const { desc } = rangeGame.newDesc(params, randomNew("range-hint-banner"));
    const { m, hintBanner } = harness();
    expect(m.newGameFromId(`9x6:${desc}`)).toBeUndefined();

    expect(m.hint()).toBeUndefined();
    const banner = hintBanner();
    expect(banner).toBeTruthy();
    expect((banner ?? "").length).toBeGreaterThan(0);

    // Make the hinted move as a real click (processInput runs the hint
    // keep-track, which advances+hides the plan) → the banner clears.
    const plan = rangeGame.hint?.(newState(params, desc));
    if (!plan?.ok) throw new Error("expected a plan");
    const t = (
      plan.steps[0].highlights as { target: { r: number; c: number; value: string } }
    ).target;
    const ts = 32;
    const b = ts / 2;
    const x = b + ts * t.c + ts / 2;
    const y = b + ts * t.r + ts / 2;
    m.processInput(x, y, t.value === "white" ? RIGHT_BUTTON : LEFT_BUTTON);
    expect(hintBanner() ?? "").toBe("");
  });

  it("reports mistakes against the solution and clears when corrected", () => {
    const params = decodeParams("9x6");
    const { desc } = rangeGame.newDesc(params, randomNew("range-mid-mistake"));
    const solution = fullSolve(newState(params, desc).grid, params.w, params.h);
    if (!solution) throw new Error("expected solvable");

    const { m } = harness();
    expect(m.newGameFromId(`9x6:${desc}`)).toBeUndefined();

    // Dot (white) a cell that is black in the solution → a mistake.
    const blackCell = solution.indexOf(BLACK);
    const r = Math.floor(blackCell / params.w);
    const c = blackCell % params.w;
    m.playMoves([{ sets: [{ r, c, value: "white" }] }]);
    expect(m.findMistakes()).toBeGreaterThan(0);

    // Correct it to black → no mistakes.
    m.playMoves([{ sets: [{ r, c, value: "black" }] }]);
    expect(m.findMistakes()).toBe(0);
  });
});

src/native/games/inertia/inertia-differe.source:
/**
 * Inertia differential — the frozen C-reference check (playbook §4.1, gated).
 *
 * The fixtures in `__fixtures__/inertia-c-reference.json` were recorded from the
 * C build by `puzzles/auxiliary/inertia-trace.c`. The two halves of the game get
 * two quite different bars, and the difference is the point:
 *
 * 1. **The desc is byte-matched.** The generator's only RNG draws are `shuffle`
 *    calls and `random.ts` is bit-identical to `random.c`, so a faithful
 *    generator reproduces the C board exactly for the same seed (playbook §4.3).
 *    That is a real, cheap check on the generator *and* on the gem-candidate
 *    search it gates on, so it stays.
 *
 * 2. **The route is not.** `solve_game` is deterministic, so an exactly faithful
 *    port would reproduce C's route too — and the original port did, which is
 *    how it caught a bug. But a route is a *travelling-salesman tour*: there is
 *    no right answer to match, only better and worse answers, and byte-matching
 *    one pins the port to C's in-place `memmove` splicing (see the tour history
 *    in `solver.ts`). The byte-parity scope doctrine (playbook §4) puts the
 *    generator/solver/codec under fidelity and everything else under "write it
 *    well", and an approximate optimiser is squarely the latter.
 *
 *    So the route is checked on what actually matters — it is **legal** (every
 *    move is a real slide, and it never touches a mine), it **collects every
 *    gem**, and it is **no longer than the route C found**. That is a stronger
 *    guarantee than byte-equality, which would have been satisfied by faithfully
 *    reproducing a *bad* route.
 */

import { describe, expect, it } from "vitest";
import { randomNew } from "../../random/index.ts";
import reference from "./__fixtures__/inertia-c-reference.json" with { type: "json" };
import { newInertiaDesc } from "./generator.ts";
import { inertiaGame } from "./index.ts";
import { solveRoute } from "./solver.ts";
import { GEM, type InertiaState, newState, validateDesc } from "./state.ts";

interface Fixture {
  w: number;
  h: number;
  seed: string;
  desc: string;
  /** The route C's `solve_game` found, as digits — kept as a quality yardstick,
   * not as an answer to reproduce. */
  route: string | null;
}

const FIXTURES = reference.fixtures as Fixture[];

describe("inertia differential vs the C reference", () => {
  for (const f of FIXTURES) {
    const params = { w: f.w, h: f.h };

    it(`${f.w}x${f.h} seed=${f.seed}: generator reproduces the C desc`, () => {
      const { desc } = newInertiaDesc(params, randomNew(f.seed));
      expect(desc).toBe(f.desc);
      expect(validateDesc(params, f.desc)).toBeNull();
    });

    it(`${f.w}x${f.h} seed=${f.seed}: the route collects every gem, alive`, () => {
      const start = newState(params, f.desc);
      const result = solveRoute(start);
      expect(result.ok).toBe(true);
      if (!result.ok) return;

      // Replaying the route through the real move logic is the check: an
      // illegal direction throws, and a mine kills.
      let state: InertiaState = start;
      for (const dir of result.route) {
        state = inertiaGame.executeMove(state, { type: "move", dir });
        expect(state.dead).toBe(false);
      }
      expect(state.gems).toBe(0);
      expect(state.board.cells.includes(GEM)).toBe(false);
    });

    it(`${f.w}x${f.h} seed=${f.seed}: the route is no longer than C's`, () => {
      const result = solveRoute(newState(params, f.desc));
      expect(result.ok).toBe(true);
      if (!result.ok) return;
      expect(f.route).not.toBeNull();

      // Upstream grows one tour, always reaching for the nearest uncollected
      // gem. We grow that tour *and* a farthest-first one and keep the shorter
      // (see `solveRoute`), so we can only match or beat it — and on these ten
      // boards we beat it on six and tie on four, for 521 moves against 553.
      expect(result.route.length).toBeLessThanOrEqual((f.route ?? "").length);
    });
  }
});

src/native/games/solo/solo-state.test.ts.source:
/**
 * Tier-1 tests for solo's state/codec layer (state.ts): param round-trips
 * across all four variants, the grid + block-structure codecs as mutual
 * inverses, and full desc assembly through validateDesc/newState. The solver,
 * generator, render, and move handling are tested separately as they land.
 */
import { describe, expect, it } from "vitest";
import type { Dsf } from "../../engine/dsf.ts";
import {
  blocksFromDsf,
  checkValid,
  DIFF_BLOCK,
  DIFF_KINTERSECT,
  DIFF_KMINMAX,
  DIFF_RECURSIVE,
  DIFF_SET,
  DIFF_SIMPLE,
  decodeParams,
  defaultParams,
  encodeBlockStructureDesc,
  encodeGrid,
  encodeParams,
  newState,
  rectangularBlocks,
  type SoloParams,
  SYMM_NONE,
  SYMM_REF4D,
  SYMM_ROT2,
  specToDsf,
  specToGrid,
  validateDesc,
  validateParams,
} from "./state.ts";

function paramsEqual(a: SoloParams, b: SoloParams): boolean {
  return (
    a.c === b.c &&
    a.r === b.r &&
    a.symm === b.symm &&
    a.diff === b.diff &&
    a.xtype === b.xtype &&
    a.killer === b.killer
  );
}

describe("solo params codec", () => {
  it("round-trips every variant through full encode/decode", () => {
    const cases: SoloParams[] = [
      {
        c: 3,
        r: 3,
        symm: SYMM_ROT2,
        diff: DIFF_BLOCK,
        kdiff: DIFF_KMINMAX,
        xtype: false,
        killer: false,
      },
      {
        c: 2,
        r: 3,
        symm: SYMM_ROT2,
        diff: DIFF_SIMPLE,
        kdiff: DIFF_KMINMAX,
        xtype: false,
        killer: false,
      },
      {
        c: 3,
        r: 3,
        symm: SYMM_ROT2,
        diff: DIFF_SIMPLE,
        kdiff: DIFF_KMINMAX,
        xtype: true,
        killer: false,
      },
      {
        c: 9,
        r: 1,
        symm: SYMM_ROT2,
        diff: DIFF_SET,
        kdiff: DIFF_KMINMAX,
        xtype: false,
        killer: false,
      },
      {
        c: 3,
        r: 3,
        symm: SYMM_NONE,
        diff: DIFF_BLOCK,
        kdiff: DIFF_KINTERSECT,
        xtype: false,
        killer: true,
      },
      {
        c: 3,
        r: 3,
        symm: SYMM_REF4D,
        diff: DIFF_RECURSIVE,
        kdiff: DIFF_KMINMAX,
        xtype: false,
        killer: false,
      },
    ];
    for (const p of cases) {
      const decoded = decodeParams(encodeParams(p, true));
      expect(paramsEqual(decoded, p), `round-trip ${encodeParams(p, true)}`).toBe(true);
    }
  });

  it("encodes the documented variant strings", () => {
    const base = defaultParams();
    expect(encodeParams({ ...base, c: 3, r: 3 }, false)).toBe("3x3");
    expect(encodeParams({ ...base, c: 9, r: 1 }, false)).toBe("9j");
    expect(encodeParams({ ...base, c: 3, r: 3, xtype: true }, false)).toBe("3x3x");
    expect(encodeParams({ ...base, c: 3, r: 3, killer: true }, false)).toBe("3x3k");
    // full mode adds symmetry + difficulty (ROT2 / BLOCK are the omitted defaults)
    expect(
      encodeParams({ ...base, c: 3, r: 3, symm: SYMM_NONE, diff: DIFF_SET }, true),
    ).toBe("3x3ada");
  });

  it("decodes the legacy jigsaw-of-a-rectangle form", () => {
    // "3x3j" collapses a former 3x3 rectangle into a jigsaw of edge 9.
    const p = decodeParams("3x3j");
    expect(p.c).toBe(9);
    expect(p.r).toBe(1);
  });

  it("rejects out-of-range params", () => {
    expect(validateParams({ ...defaultParams(), c: 1 }, true)).not.toBeNull();
    expect(validateParams({ ...defaultParams(), c: 6, r: 6 }, true)).not.toBeNull(); // 36 > 31
    expect(
      validateParams({ ...defaultParams(), c: 4, r: 3, killer: true }, true),
    ).not.toBeNull(); // killer 12 > 9
    expect(validateParams(defaultParams(), true)).toBeNull();
  });
});

describe("solo grid codec", () => {
  it("round-trips a grid through encode/specToGrid", () => {
    const area = 81;
    const grid = new Int8Array(area);
    // a scattering of givens, incl. the top-left and bottom-right corners
    grid[0] = 5;
    grid[1] = 9;
    grid[40] = 1;
    grid[80] = 7;
    grid[79] = 3;
    const enc = encodeGrid(grid, area);
    const out = new Int8Array(area);
    const next = specToGrid(enc, 0, out, area);
    expect(next).toBe(enc.length);
    expect(Array.from(out)).toEqual(Array.from(grid));
  });
});

describe("solo block-structure codec", () => {
  it("encode and specToDsf are mutual inverses (partition preserved)", () => {
    const cr = 9;
    const orig = rectangularBlocks(3, 3); // any cr-region partition
    const enc = encodeBlockStructureDesc(cr, orig);
    const { dsf, error, next } = specToDsf(enc, 0, cr);
    expect(error).toBeNull();
    expect(next).toBe(enc.length);
    const round = blocksFromDsf(dsf as Dsf, cr);
    // The block *numbering* may differ; the *partition* must be identical.
    const area = cr * cr;
    for (let i = 0; i < area; i++)
      for (let j = i + 1; j < area; j++)
        expect(orig.whichblock[i] === orig.whichblock[j]).toBe(
          round.whichblock[i] === round.whichblock[j],
        );
  });
});

describe("solo desc assembly (validateDesc + newState)", () => {
  it("validates and rebuilds a standard board (givens only)", () => {
    const p: SoloParams = {
      c: 3,
      r: 3,
      symm: SYMM_ROT2,
      diff: DIFF_SIMPLE,
      kdiff: DIFF_KMINMAX,
      xtype: false,
      killer: false,
    };
    const area = 81;
    const grid = new Int8Array(area);
    grid[0] = 5;
    grid[10] = 8;
    grid[80] = 2;
    const desc = encodeGrid(grid, area);
    expect(validateDesc(p, desc)).toBeNull();
    const st = newState(p, desc);
    expect(Array.from(st.grid)).toEqual(Array.from(grid));
    expect(st.immutable[0]).toBe(1);
    expect(st.immutable[1]).toBe(0);
    expect(st.blocks.nrBlocks).toBe(9);
  });

  it("validates and rebuilds a jigsaw board (grid + block structure)", () => {
    const p: SoloParams = {
      c: 9,
      r: 1,
      symm: SYMM_ROT2,
      diff: DIFF_SET,
      kdiff: DIFF_KMINMAX,
      xtype: false,
      killer: false,
    };
    const cr = 9;
    const area = cr * cr;
    const grid = new Int8Array(area);
    grid[0] = 4;
    const blocks = rectangularBlocks(3, 3); // a valid 9×9-of-9 partition
    const desc = `${encodeGrid(grid, area)},${encodeBlockStructureDesc(cr, blocks)}`;
    expect(validateDesc(p, desc)).toBeNull();
    const st = newState(p, desc);
    expect(st.blocks.nrBlocks).toBe(9);
    // partition preserved
    for (let i = 0; i < area; i++)
      for (let j = i + 1; j < area; j++)
        expect(blocks.whichblock[i] === blocks.whichblock[j]).toBe(
          st.blocks.whichblock[i] === st.blocks.whichblock[j],
        );
  });

  it("validates and rebuilds a killer board (grid + cages + sums)", () => {
    const p: SoloParams = {
      c: 3,
      r: 3,
      symm: SYMM_NONE,
      diff: DIFF_BLOCK,
      kdiff: DIFF_KINTERSECT,
      xtype: false,
      killer: true,
    };
    const cr = 9;
    const area = cr * cr;
    const grid = new Int8Array(area); // killer puzzles ship no givens
    // Cages: compact 3×3 blocks (size 9 = cr, the max). A realistic cage
    // partition keeps non-edge runs short; full-row cages would exercise the
    // `'z'` run-overflow path the real generator never produces (see state.ts).
    const kblocks = rectangularBlocks(3, 3);
    const kgrid = new Int32Array(area);
    for (let b = 0; b < kblocks.nrBlocks; b++) kgrid[kblocks.blocks[b][0]] = 45; // sum 1..9
    const desc = `${encodeGrid(grid, area)},${encodeBlockStructureDesc(cr, kblocks)},${encodeGrid(kgrid, area)}`;
    expect(validateDesc(p, desc)).toBeNull();
    const st = newState(p, desc);
    expect(st.killerData).not.toBeNull();
    expect(st.killerData?.kblocks.nrBlocks).toBe(9);
    // every cage carries its recorded sum at exactly one cell
    let clued = 0;
    for (let i = 0; i < area; i++) if (st.killerData?.kgrid[i] === 45) clued++;
    expect(clued).toBe(9);
  });
});

describe("solo completion check", () => {
  it("accepts a full valid standard grid and rejects a broken one", () => {
    const cr = 9;
    const area = cr * cr;
    const blocks = rectangularBlocks(3, 3);
    // a known-valid 9×9 sudoku solution (base pattern)
    const grid = new Int8Array(area);
    for (let y = 0; y < cr; y++)
      for (let x = 0; x < cr; x++)
        grid[y * cr + x] = (((y % 3) * 3 + ((y / 3) | 0) + x) % 9) + 1;
    expect(checkValid(cr, blocks, null, false, grid)).toBe(true);
    // swap two cells in a row to break it
    const broken = grid.slice();
    broken[0] = broken[1];
    expect(checkValid(cr, blocks, null, false, broken)).toBe(false);
  });
});

src/native/engine/testing/render-scenari.source:
// Mechanics of the Midend-backed scenario driver, exercised against a
// real full-featured game (Palisade: redraw + hint + findMistakes). The
// game-specific seed frames (the equivalentEdges hint) live in
// palisade-render-scenario.test.ts; this file pins the driver contract.
import { describe, expect, it } from "vitest";
import { palisadeGame } from "../../games/palisade/index.ts";
import { COL_GRID, COL_HINT } from "../../games/palisade/render.ts";
import { newDesc } from "../../games/palisade/solver.ts";
import { randomNew } from "../../random/index.ts";
import { BORDER } from "../border-grid.ts";
import { renderScenario } from "./render-scenario.ts";
import { toSvg } from "./svg-drawing.ts";

const P = { w: 5, h: 5, k: 5 };
const ID = `5x5n5:${newDesc(P, randomNew("render-scenario")).desc}`;

// A guaranteed-valid interior edge edit: toggle the wall between cells
// (1,1) and (2,1). executeMove just XORs the border bits, so this is a
// legal move on any board, independent of the generated clues.
const WALL_MOVE = {
  type: "edges" as const,
  edits: [
    { x: 1, y: 1, flag: BORDER(1) },
    { x: 2, y: 1, flag: BORDER(3) },
  ],
};

describe("renderScenario", () => {
  it("throws on an invalid id rather than capturing an empty frame", () => {
    expect(() => renderScenario({ game: palisadeGame, id: "not-an-id" })).toThrow(
      /invalid id/,
    );
  });

  it("captures a non-empty frame for a fresh board", () => {
    const { recording, size } = renderScenario({ game: palisadeGame, id: ID });
    expect(recording.ops.length).toBeGreaterThan(0);
    // The clue digits and the grid rim are drawn.
    expect(recording.ops.some((o) => o.op === "text")).toBe(true);
    expect(recording.ops.some((o) => o.op === "rect" && o.colour === COL_GRID)).toBe(
      true,
    );
    expect(size.w).toBeGreaterThan(0);
    expect(size.h).toBeGreaterThan(0);
  });

  it("replays Moves directly through the midend (not pointer events)", () => {
    const before = renderScenario({ game: palisadeGame, id: ID });
    const after = renderScenario({ game: palisadeGame, id: ID, moves: [WALL_MOVE] });

    // The move actually took: the board state changed (the save bytes
    // differ) and so did the captured render.
    const beforeSave = before.midend.saveGame();
    const afterSave = after.midend.saveGame();
    expect(afterSave).not.toEqual(beforeSave);
    expect(JSON.stringify(after.recording.ops)).not.toBe(
      JSON.stringify(before.recording.ops),
    );
  });

  it("reports the mistake count (0 on a fresh board)", () => {
    const { mistakeCount } = renderScenario({
      game: palisadeGame,
      id: ID,
      showMistakes: true,
    });
    expect(mistakeCount).toBe(0);
  });

  it("shows a hint step and paints its action edge in COL_HINT", () => {
    const { hint, recording } = renderScenario({
      game: palisadeGame,
      id: ID,
      showHint: true,
    });
    expect(hint).toBeDefined();
    expect(recording.ops.some((o) => o.op === "rect" && o.colour === COL_HINT)).toBe(
      true,
    );
  });

  it("walks the plan to a step matching hintUntil", () => {
    // Predicate matches the first step → no walking; the displayed step
    // is the plan opener.
    const opener = renderScenario({
      game: palisadeGame,
      id: ID,
      showHint: true,
      hintUntil: () => true,
    });
    // Predicate matches the second step → exactly one executeHint.
    let seen = 0;
    const second = renderScenario({
      game: palisadeGame,
      id: ID,
      showHint: true,
      hintUntil: () => seen++ >= 1,
    });
    expect(opener.hint).toBeDefined();
    expect(second.hint).toBeDefined();
    // The two steps differ (the walk advanced the displayed step).
    expect(JSON.stringify(second.hint)).not.toBe(JSON.stringify(opener.hint));
  });

  it("toSvg renders the same record as a well-formed SVG", () => {
    const { recording, size } = renderScenario({ game: palisadeGame, id: ID });
    const svg = toSvg(recording.ops, size);
    expect(svg.startsWith("<svg")).toBe(true);
    expect(svg).toContain("</svg>");
    expect(svg).toContain("<rect");
    expect(svg).toContain(`width="${size.w}"`);
  });
});

src/native/games/group/group-render-scen.source:
/**
 * Tier-2.5 render-scenario tests for Group: drive a real `Midend` to a target
 * frame and assert the recorded draw ops (plus a snapshot regression baseline).
 * Covers the distinctive Group rendering — the element legend, the shaded main
 * diagonal, and a player-placed subgroup divider — reached in-process with no
 * browser (playbook §5, `add-render-snapshot-harness`).
 *
 * A fixed fixture desc keeps every frame deterministic without depending on the
 * generator's RNG.
 */

import { describe, expect, it } from "vitest";
import { renderScenario } from "../../engine/testing/render-scenario.ts";
import { groupGame } from "./index.ts";
import { COL_DIAGONAL, COL_GRID, COL_HINT, COL_HINT_CELL } from "./render.ts";

// A 6x6 identity-shown board (group-trace-5 fixture): the identity row/column
// are given, so the frame exercises legend, diagonal, and immutable digits.
const ID = "6dn:1_2_3_4_5_6_2e3d5_4e5a1c6_3d";

function rects(ops: readonly { op: string }[]) {
  return ops.filter((o) => o.op === "rect") as {
    op: "rect";
    colour: number;
    w: number;
    h: number;
  }[];
}

describe("group render scenarios", () => {
  it("opener frame draws the legend, the shaded diagonal, and digits", () => {
    const { recording } = renderScenario({ game: groupGame, id: ID });
    const ops = recording.ops;

    // The element legend and the given digits are drawn as text.
    const textOps = ops.filter((o) => o.op === "text");
    expect(textOps.length).toBeGreaterThan(0);

    // The w cells on the main display diagonal are shaded COL_DIAGONAL.
    const diagonal = rects(ops).filter((r) => r.colour === COL_DIAGONAL);
    expect(diagonal.length).toBe(6);

    expect(recording.ops).toMatchSnapshot();
  });

  it("a subgroup divider adds thick grid edges the opener lacks", () => {
    const opener = renderScenario({ game: groupGame, id: ID });
    const withDivider = renderScenario({
      game: groupGame,
      id: ID,
      moves: [{ type: "divider", i: 0, j: 1 }],
    });

    // The divider paints extra 1px COL_GRID edges between the two elements.
    const thinGridEdges = (ops: readonly { op: string }[]) =>
      rects(ops).filter((r) => r.colour === COL_GRID && (r.w === 1 || r.h === 1))
        .length;

    expect(thinGridEdges(withDivider.recording.ops)).toBeGreaterThan(
      thinGridEdges(opener.recording.ops),
    );

    expect(withDivider.recording.ops).toMatchSnapshot();
  });

  it("an associativity hint frame rings the target and shades the known products", () => {
    // Scan Normal (identity-shown) seeds for a plan that reaches an associativity
    // step, walking the plan to it (the fixed-seed scan + hintUntil idiom).
    const isAssoc = (step: { explanation: string }) =>
      /in any group/.test(step.explanation);
    let frame: ReturnType<typeof renderScenario> | undefined;
    for (let n = 0; n < 40 && !frame; n++) {
      const r = renderScenario({
        game: groupGame,
        id: `6dn#assoc-${n}`,
        showHint: true,
        hintUntil: isAssoc,
      });
      if (r.hint && isAssoc(r.hint)) frame = r;
    }
    expect(frame, "no associativity frame found in 40 seeds").toBeDefined();
    if (!frame) return;

    // The forced cell is ringed with a solid COL_HINT fill; the three known
    // products are shaded COL_HINT_CELL as evidence (design D4 / §5.2).
    const hintTargets = rects(frame.recording.ops).filter((r) => r.colour === COL_HINT);
    const evidence = rects(frame.recording.ops).filter(
      (r) => r.colour === COL_HINT_CELL,
    );
    expect(hintTargets.length).toBeGreaterThanOrEqual(1);
    expect(evidence.length).toBeGreaterThanOrEqual(3);

    expect(frame.recording.ops).toMatchSnapshot();
  });
});

src/native/engine/tilings/penrose.test.t.source:
/**
 * Unit tests for the Penrose P2/P3 tilings.
 *
 * The heavy lifting is done by `grid-aperiodic-differential.test.ts`, which
 * byte-matches 13 C-generated fixtures across both variants. These cover what
 * a fixture cannot: the shape of the hand-transcribed transition tables, the
 * description parser's rejection paths (which are untrusted-input surface), and
 * the `"dummy"` replay RNG, which no ordinary fixture reaches.
 */

import { describe, expect, it } from "vitest";
import { randomNew } from "../../random/index.ts";
import { GridTrimmedAwayError } from "../grid-trim.ts";
import { PENROSE_LETTERS, transition, transitionIn } from "./penrose.ts";
import {
  gridNewPenrose,
  type PenroseWhich,
  penroseNewDesc,
  penroseValidateDesc,
} from "./penrose-grid.ts";

const WHICHES: PenroseWhich[] = ["p2", "p3"];

describe("penrose transition tables", () => {
  // Upstream's two nested switches are the one place in this change a human
  // types the data, so assert the *shape* of what was typed. The counts come
  // from the C: 60 leaves in `transition` (penrose.c:100-266) and 36 in
  // `transition_in` (penrose.c:275-361). A dropped or duplicated row moves a
  // count; the differential then says which row.
  it("has exactly the C's 60 outward leaves", () => {
    const defined: string[] = [];
    for (const parent of PENROSE_LETTERS) {
      for (const child of PENROSE_LETTERS) {
        for (const edge of [0, 1, 2]) {
          try {
            transition(parent, child, edge);
            defined.push(`${parent}/${child}/${edge}`);
          } catch {
            // Not a legal parent/child pairing: upstream's FAIL.
          }
        }
      }
    }
    expect(defined).toHaveLength(60);
  });

  it("defines exactly the subdivision rule's children, all three edges each", () => {
    // The children each metatile subdivides into, from upstream's switch arms.
    const children: Record<string, string[]> = {
      A: ["A", "B", "U"],
      B: ["A", "B", "V"],
      U: ["B", "U"],
      V: ["A", "V"],
      C: ["C", "Y"],
      D: ["D", "X"],
      X: ["C", "X", "Y"],
      Y: ["D", "X", "Y"],
    };
    for (const parent of PENROSE_LETTERS) {
      for (const child of PENROSE_LETTERS) {
        const legal = children[parent].includes(child);
        for (const edge of [0, 1, 2]) {
          if (legal) {
            expect(() => transition(parent, child, edge)).not.toThrow();
          } else {
            expect(() => transition(parent, child, edge)).toThrow(/not a child of/);
          }
        }
      }
    }
  });

  it("rejects an out-of-range edge rather than falling through", () => {
    // Upstream's inner `switch (edge)` has no `default`, so an out-of-range
    // edge silently drops into the *next child's* dispatch. Unreachable in
    // practice, but reproducing the fallthrough would hide a real bug.
    expect(() => transition("A", "A", 3)).toThrow(/out of range/);
    expect(() => transition("A", "A", -1)).toThrow(/out of range/);
  });

  it("has exactly the C's 36 inward leaves", () => {
    const defined: string[] = [];
    for (const parent of PENROSE_LETTERS) {
      for (const edge of [0, 1, 2]) {
        for (const end of [-1, 0, 1] as const) {
          try {
            transitionIn(parent, edge, end);
            defined.push(`${parent}/${edge}/${end}`);
          } catch {
            // An `end` inconsistent with whether that edge is divided.
          }
        }
      }
    }
    expect(defined).toHaveLength(36);
  });

  it("gives every parent edge either two divided ends or one undivided", () => {
    // A structural invariant of the tiling, and a cheap check that no row was
    // transcribed with a mismatched `end`: an edge of a metatile is either cut
    // in half by a child boundary (so both -1 and +1 are entries, and 0 is
    // not) or it is not (only 0).
    for (const parent of PENROSE_LETTERS) {
      for (const edge of [0, 1, 2]) {
        const present = ([-1, 0, 1] as const).filter((end) => {
          try {
            transitionIn(parent, edge, end);
            return true;
          } catch {
            return false;
          }
        });
        expect(present).toSatisfy(
          (ends: number[]) =>
            (ends.length === 2 && ends[0] === -1 && ends[1] === 1) ||
            (ends.length === 1 && ends[0] === 0),
        );
      }
    }
  });

  it("always lands inside a child when stepping inwards", () => {
    for (const parent of PENROSE_LETTERS) {
      for (const edge of [0, 1, 2]) {
        for (const end of [-1, 0, 1] as const) {
          let result: ReturnType<typeof transitionIn> | undefined;
          try {
            result = transitionIn(parent, edge, end);
          } catch {
            continue;
          }
          expect(result.kind).toBe("internal");
          // The triangle we enter must be one that can actually step back out
          // through the same parent — i.e. a legal child of it.
          expect(() =>
            transition(parent, result.newChild, result.newEdge),
          ).not.toThrow();
        }
      }
    }
  });
});

describe("penrose descriptions", () => {
  for (const which of WHICHES) {
    describe(which, () => {
      it("generates a description it then accepts and can build", () => {
        const desc = penroseNewDesc(which, 8, 8, randomNew("round-trip"));
        // `[orientation 0-9][start vertex 0-2][letters]`.
        expect(desc).toMatch(
          which === "p2" ? /^[0-9][0-2][ABUV]+$/ : /^[0-9][0-2][CDXY]+$/,
        );
        expect(penroseValidateDesc(which, 8, 8, desc)).toBeNull();

        const g = gridNewPenrose(which, 8, 8, desc);
        expect(g.numFaces).toBeGreaterThan(0);
        // Every Penrose tile is a quadrilateral, both halves included.
        for (const f of g.faces) expect(f.order).toBe(4);
      });

      it("is deterministic: the same seed gives the same description", () => {
        const a = penroseNewDesc(which, 6, 7, randomNew("same"));
        const b = penroseNewDesc(which, 6, 7, randomNew("same"));
        expect(a).toBe(b);
      });

      it("rejects a legacy 'G' description by name", () => {
        // `penrose-legacy.c` is deliberately not ported (design D9). Falling
        // through to the generic "expected digit" error would be survivable
        // but misleading.
        const legacy = "G3,4,5";
        expect(penroseValidateDesc(which, 6, 6, legacy)).toMatch(/legacy/i);
        expect(() => gridNewPenrose(which, 6, 6, legacy)).toThrow(/legacy/i);
      });
    });
  }

  it("requires a description at all", () => {
    expect(penroseValidateDesc("p2", 6, 6, null)).toBe(
      "Missing grid description string.",
    );
    expect(penroseValidateDesc("p2", 6, 6, "")).toBe("empty grid description");
  });

  it("rejects a description too short to carry its own header", () => {
    // Upstream computes `strlen(desc) - 2` before checking the length, which
    // underflows `size_t` on a one-character desc. Checking the header first
    // reaches the same message without the underflow.
    expect(penroseValidateDesc("p2", 6, 6, "5")).toMatch(/second char/);
    expect(penroseValidateDesc("p2", 6, 6, "A")).toMatch(/expected digit at start/);
    expect(penroseValidateDesc("p2", 6, 6, "53")).toMatch(/second char/);
    expect(penroseValidateDesc("p2", 6, 6, "50")).toBe(
      "expected at least one coordinate",
    );
  });

  it("rejects letters from the other tiling", () => {
    expect(penroseValidateDesc("p2", 6, 6, "50CXY")).toMatch(/expected tile letter/);
    expect(penroseValidateDesc("p3", 6, 6, "50ABU")).toMatch(/expected tile letter/);
  });

  it("rejects a pair of letters that cannot nest", () => {
    // A may sit inside A, B or V — never inside U.
    expect(penroseValidateDesc("p2", 6, 6, "50AU")).toBe(
      "invalid pair of consecutive coordinates",
    );
    expect(penroseValidateDesc("p2", 6, 6, "50AB")).toBeNull();
  });

  it("refuses to build from a description it would reject", () => {
    expect(() => gridNewPenrose("p2", 6, 6, "50AU")).toThrow(
      /invalid penrose description/,
    );
  });
});

describe('penrose "dummy" replay RNG', () => {
  // When a stored description is replayed at a larger size than it was
  // generated for, the search asks for metatile levels the description never
  // recorded. Upstream conjures a fixed-seed RNG at that moment; this is the
  // only path that exercises it, and no differential fixture reaches it.
  //
  // The 20×20 size is chosen because it is *verified* to reach the fallback:
  // instrumenting the branch shows a 4×4 description (9 coordinates for P2,
  // 8 for P3) exhausting itself before the patch is filled. Do not shrink it —
  // this test would keep passing while asserting nothing about the fallback.
  for (const which of WHICHES) {
    it(`${which}: replays a small description at a larger size, reproducibly`, () => {
      const desc = penroseNewDesc(which, 4, 4, randomNew("small"));
      expect(penroseValidateDesc(which, 20, 20, desc)).toBeNull();

      const first = gridNewPenrose(which, 20, 20, desc);
      const second = gridNewPenrose(which, 20, 20, desc);

      // The description is far too short for a 20×20 patch, so the extra
      // levels came from the fallback RNG. Both builds must agree exactly: a
      // fallback created eagerly, per-triangle, or re-seeded per call would
      // still produce a valid tiling here, but not the same one twice.
      expect(first.numFaces).toBeGreaterThan(0);
      expect(second.dots.map((d) => [d.x, d.y])).toEqual(
        first.dots.map((d) => [d.x, d.y]),
      );
      expect(second.numFaces).toBe(first.numFaces);
    });
  }
});

describe("penrose degenerate patches", () => {
  it("reports an empty patch rather than returning an empty grid", () => {
    // A patch small enough that the seed triangle lands out of bounds never
    // runs the search at all; the tell is a description with a single
    // coordinate letter. Upstream then aborts inside `dsf_new(0)`; trimming
    // catches it here instead, which is the better failure. Not a bug to work
    // around — the differential fixtures deliberately start above this size.
    const desc = "50A";
    expect(penroseValidateDesc("p2", 1, 1, desc)).toBeNull();
    expect(() => gridNewPenrose("p2", 1, 1, desc)).toThrow(GridTrimmedAwayError);
  });
});

