/**
 * Tracks behavioural tests (tier 1 + tier 2): params/desc codecs, the solver
 * grade, `findMistakes`, input mapping, and the mistake render overlay
 * (paint-twice, so the overlay is proven to live in the diff key).
 *
 * Heavy solver checks use frozen fixture descs (not fresh generation), so they
 * are fast and deterministic; the generator's byte-match + grade is covered by
 * `tracks-differential.test.ts`.
 */
import { describe, expect, it } from "vitest";
import {
  LEFT_BUTTON,
  LEFT_DRAG,
  LEFT_RELEASE,
  RIGHT_BUTTON,
  RIGHT_DRAG,
  RIGHT_RELEASE,
} from "../../engine/pointer.ts";
import { RecordingDrawing } from "../../engine/testing/recording-drawing.ts";
import { randomNew } from "../../random/index.ts";
import { newDesc } from "./generator.ts";
import { tracksGame } from "./index.ts";
import { executeMove, uiCanFlipSquare } from "./moves.ts";
import { COL_ERROR, newDrawState, redraw } from "./render.ts";
import { copyAndStrip, tracksSolve } from "./solver.ts";
import {
  DIFF_COUNT,
  DIFF_TRICKY,
  decodeParams,
  encodeParams,
  newState,
  S_CLUE,
  S_TRACK,
  stateToBoard,
  type TracksParams,
} from "./state.ts";

const DEFAULT_BACKGROUND: [number, number, number] = [0.9, 0.9, 0.9];

// Known boards from the C-reference fixtures.
const SMALL: { p: TracksParams; desc: string } = {
  p: { w: 6, h: 6, diff: 0, singleOnes: true },
  desc: "f6pCkC,2,3,3,2,3,S3,3,S3,3,3,2,2",
};
const HARD: { p: TracksParams; desc: string } = {
  p: { w: 10, h: 10, diff: 2, singleOnes: true },
  desc: "aCmCa5b6zze9hAhAc,9,5,2,2,5,4,S8,4,8,7,7,8,S5,5,5,4,4,7,6,3",
};

const sq = (x: number, y: number, track: boolean, set: boolean) => ({
  kind: "square" as const,
  x,
  y,
  track,
  set,
});

describe("tracks params codec", () => {
  it("round-trips presets and the single_ones suffix", () => {
    const cases: TracksParams[] = [
      { w: 8, h: 8, diff: 1, singleOnes: true },
      { w: 10, h: 8, diff: 1, singleOnes: false },
      { w: 15, h: 15, diff: 2, singleOnes: true },
    ];
    for (const p of cases) expect(decodeParams(encodeParams(p, true))).toEqual(p);
    expect(encodeParams({ w: 10, h: 8, diff: 1, singleOnes: false }, true)).toBe(
      "10x8dto",
    );
    expect(encodeParams({ w: 8, h: 8, diff: 0, singleOnes: true }, false)).toBe("8x8");
  });
});

describe("tracks desc codec", () => {
  it("parses a board and validates its desc", () => {
    const st = newState(SMALL.p, SMALL.desc);
    expect(st.numbers.rowS).toBeGreaterThanOrEqual(0);
    expect(st.numbers.colS).toBeGreaterThanOrEqual(0);
    expect(tracksGame.validateDesc(SMALL.p, SMALL.desc)).toBeNull();
  });

  it("rejects malformed descs", () => {
    // A clue flag with the wrong bit-count (a single direction is 1 bit).
    expect(
      tracksGame.validateDesc(SMALL.p, "1zc,1,1,1,1,1,S1,1,S1,1,1,1,1"),
    ).not.toBeNull();
    // Missing entrance/exit markers.
    expect(
      tracksGame.validateDesc(SMALL.p, "f6pCkC,2,3,3,2,3,3,3,3,3,3,2,2"),
    ).not.toBeNull();
  });
});

describe("tracks solver", () => {
  it("solves the fixture board uniquely at DIFF_COUNT", () => {
    const strip = copyAndStrip(stateToBoard(newState(SMALL.p, SMALL.desc)), -1);
    expect(tracksSolve(strip, DIFF_COUNT).ret).toBe(1);
  });

  it("grades the Hard fixture Hard, and the Tricky solver cannot finish it", () => {
    const strip = () => copyAndStrip(stateToBoard(newState(HARD.p, HARD.desc)), -1);
    expect(tracksSolve(strip(), DIFF_COUNT).maxDiff).toBe(2 /* DIFF_HARD */);
    expect(tracksSolve(strip(), DIFF_TRICKY).ret).toBeLessThan(1);
  });

  it("generates a solvable Easy board (fixed seed)", () => {
    const p: TracksParams = { w: 8, h: 8, diff: 0, singleOnes: true };
    const { desc } = newDesc(p, randomNew("tracks-gen-easy"));
    const solved = copyAndStrip(stateToBoard(newState(p, desc)), -1);
    expect(tracksSolve(solved, DIFF_COUNT).ret).toBe(1);
  });
});

describe("tracks findMistakes + solve", () => {
  it("flags a track laid where the solution has none; leaves correct marks", () => {
    const st = newState(SMALL.p, SMALL.desc);
    const solution = copyAndStrip(stateToBoard(st), -1);
    tracksSolve(solution, DIFF_COUNT);
    const { w, h } = SMALL.p;

    let notrackCell = -1;
    let trackCell = -1;
    for (let i = 0; i < w * h; i++) {
      if (st.sflags[i] & S_CLUE) continue;
      if (!(solution.sflags[i] & S_TRACK) && notrackCell < 0) notrackCell = i;
      if (solution.sflags[i] & S_TRACK && trackCell < 0) trackCell = i;
    }
    expect(notrackCell).toBeGreaterThanOrEqual(0);

    const bad = executeMove(st, {
      ops: [sq(notrackCell % w, Math.floor(notrackCell / w), true, true)],
    });
    expect(tracksGame.findMistakes?.(bad) ?? []).toContainEqual({
      x: notrackCell % w,
      y: Math.floor(notrackCell / w),
    });

    const good = executeMove(st, {
      ops: [sq(trackCell % w, Math.floor(trackCell / w), true, true)],
    });
    expect(
      (tracksGame.findMistakes?.(good) ?? []).some(
        (m) => m.x === trackCell % w && m.y === Math.floor(trackCell / w),
      ),
    ).toBe(false);
  });

  it("solve() drives a blank board to completion", () => {
    const st = newState(SMALL.p, SMALL.desc);
    const result = tracksGame.solve?.(st, st);
    expect(result?.ok).toBe(true);
    if (result?.ok) expect(executeMove(st, result.move).completed).toBe(true);
  });

  it("findMistakes returns [] on an untouched board", () => {
    expect(tracksGame.findMistakes?.(newState(SMALL.p, SMALL.desc)) ?? []).toEqual([]);
  });
});

// Geometry for PREFERRED_TILE_SIZE=33 → sz6=5, tile=30, border=0.
const CENTRE = (n: number) => (n + 1) * 30 + 15;

describe("tracks input", () => {
  it("a left-drag lays a straight run of track", () => {
    const st = newState(SMALL.p, SMALL.desc);
    const ui = tracksGame.newUi(st);
    tracksGame.interpretMove(st, ui, null, { x: CENTRE(1), y: CENTRE(3) }, LEFT_BUTTON);
    tracksGame.interpretMove(st, ui, null, { x: CENTRE(3), y: CENTRE(3) }, LEFT_DRAG);
    const move = tracksGame.interpretMove(
      st,
      ui,
      null,
      { x: CENTRE(3), y: CENTRE(3) },
      LEFT_RELEASE,
    );
    expect(move && typeof move === "object" && "ops" in move).toBe(true);
    const applied = executeMove(st, move as Parameters<typeof executeMove>[1]);
    for (const x of [1, 2, 3]) {
      expect(applied.sflags[3 * SMALL.p.w + x] & S_TRACK).toBeTruthy();
    }
  });

  it("a drag that drifts out of bounds keeps its last valid extent", () => {
    const st = newState(SMALL.p, SMALL.desc);
    const ui = tracksGame.newUi(st);
    tracksGame.interpretMove(st, ui, null, { x: CENTRE(1), y: CENTRE(3) }, LEFT_BUTTON);
    // A valid horizontal drag out to column 3.
    tracksGame.interpretMove(st, ui, null, { x: CENTRE(3), y: CENTRE(3) }, LEFT_DRAG);
    // Now drift above the grid (y=5 → row −1): upstream would cancel; we freeze.
    tracksGame.interpretMove(st, ui, null, { x: CENTRE(3), y: 5 }, LEFT_DRAG);
    expect(ui.dragging).toBe(true);
    expect(ui.dragEx).toBe(3); // extent preserved, not reset to the origin
    const move = tracksGame.interpretMove(
      st,
      ui,
      null,
      { x: CENTRE(3), y: 5 },
      LEFT_RELEASE,
    );
    const applied = executeMove(st, move as Parameters<typeof executeMove>[1]);
    for (const x of [1, 2, 3]) {
      expect(applied.sflags[3 * SMALL.p.w + x] & S_TRACK).toBeTruthy();
    }
  });

  it("a right-drag over cells that already hold track is a no-op", () => {
    let st = newState(SMALL.p, SMALL.desc);
    st = executeMove(st, { ops: [1, 2, 3].map((x) => sq(x, 3, true, true)) });
    const ui = tracksGame.newUi(st);
    tracksGame.interpretMove(
      st,
      ui,
      null,
      { x: CENTRE(1), y: CENTRE(3) },
      RIGHT_BUTTON,
    );
    tracksGame.interpretMove(st, ui, null, { x: CENTRE(3), y: CENTRE(3) }, RIGHT_DRAG);
    const move = tracksGame.interpretMove(
      st,
      ui,
      null,
      { x: CENTRE(3), y: CENTRE(3) },
      RIGHT_RELEASE,
    );
    expect(move).toBeNull();
    expect(uiCanFlipSquare(stateToBoard(st), 1, 3, true)).toBe(false);
  });
});

describe("tracks render", () => {
  it("draws rails and clue numbers on the initial frame", () => {
    const st = newState(SMALL.p, SMALL.desc);
    const solved = executeMove(
      st,
      (tracksGame.solve?.(st, st) as { ok: true; move: never }).move,
    );
    const ds = newDrawState(solved);
    ds.tileSize = tracksGame.preferredTileSize ?? 33;
    const dr = new RecordingDrawing(tracksGame.colours(DEFAULT_BACKGROUND));
    redraw(dr, ds, null, solved, 1, tracksGame.newUi(solved), 0, 0);
    expect(dr.ops.some((o) => o.op === "text")).toBe(true);
    expect(dr.ops.some((o) => o.op === "line")).toBe(true);
  });

  it("paints the mistake overlay even on an already-drawn tile", () => {
    const st = newState(SMALL.p, SMALL.desc);
    const solution = copyAndStrip(stateToBoard(st), -1);
    tracksSolve(solution, DIFF_COUNT);
    const { w, h } = SMALL.p;
    let notrackCell = -1;
    for (let i = 0; i < w * h; i++) {
      if (!(st.sflags[i] & S_CLUE) && !(solution.sflags[i] & S_TRACK)) {
        notrackCell = i;
        break;
      }
    }
    const bad = executeMove(st, {
      ops: [sq(notrackCell % w, Math.floor(notrackCell / w), true, true)],
    });
    const ds = newDrawState(bad);
    ds.tileSize = tracksGame.preferredTileSize ?? 33;
    const ui = tracksGame.newUi(bad);
    const palette = tracksGame.colours(DEFAULT_BACKGROUND);

    // Warm the drawstate without the overlay, then repaint with it.
    redraw(new RecordingDrawing(palette), ds, null, bad, 1, ui, 0, 0);
    const mistakes = tracksGame.findMistakes?.(bad) ?? [];
    const dr = new RecordingDrawing(palette);
    redraw(dr, ds, null, bad, 1, ui, 0, 0, undefined, mistakes);
    expect(dr.ops.some((o) => o.op === "rect" && o.colour === COL_ERROR)).toBe(true);
  });
});

src/native/games/undead/undead.test.ts.source:
/**
 * Behavioural tests for the Undead port (tier 1 + a tier-2.5 render smoke).
 *
 * Generation is seeded for determinism, so the heavy generate/solve blocks do
 * fixed work and need no clock gate (playbook §5.2). End-to-end consistency is checked by
 * decoding a generated desc and confirming its unique solution equals the
 * generator's recorded `aux` solution — exercising codec + solver + generator
 * together.
 */
import { describe, expect, it } from "vitest";
import { Midend } from "../../engine/index.ts";
import { renderScenario } from "../../engine/testing/render-scenario.ts";
import { randomNew } from "../../random/index.ts";
import { newUndeadDesc } from "./generator.ts";
import { undeadGame } from "./index.ts";
import {
  findUndeadSolution,
  isUniquelySolvable,
  RUNG_ARC,
  RUNG_COUNTING,
  RUNG_FORCING,
  solveDeductive,
} from "./solver.ts";
import {
  type Difficulty,
  decodeParams,
  encodeParams,
  MON_GHOST,
  MON_NONE,
  MON_VAMPIRE,
  MON_ZOMBIE,
  newState,
  newUi,
  type UndeadParams,
  type UndeadState,
  validateDesc,
  validateParams,
} from "./state.ts";

function gen(w: number, h: number, diff: Difficulty, seed: string) {
  const params: UndeadParams = { w, h, diff };
  const { desc, aux } = newUndeadDesc(params, randomNew(`undead-${seed}`));
  const state = newState(params, desc);
  return { params, desc, aux, state };
}

function auxToGuess(aux: string): number[] {
  return [...aux.slice(1)].map((c) =>
    c === "G" ? MON_GHOST : c === "V" ? MON_VAMPIRE : MON_ZOMBIE,
  );
}

// --- params ----------------------------------------------------------------

describe("undead params", () => {
  it("round-trips encode/decode", () => {
    const p: UndeadParams = { w: 5, h: 5, diff: "tricky" };
    expect(encodeParams(p, true)).toBe("5x5dt");
    expect(encodeParams(p, false)).toBe("5x5");
    expect(decodeParams("5x5dt")).toEqual(p);
    expect(decodeParams("4x4")).toEqual({ w: 4, h: 4, diff: "normal" });
    expect(decodeParams("7x7dn")).toEqual({ w: 7, h: 7, diff: "normal" });
  });

  it("rejects invalid params", () => {
    expect(validateParams({ w: 2, h: 4, diff: "easy" }, true)).not.toBeNull();
    expect(validateParams({ w: 4, h: 2, diff: "easy" }, true)).not.toBeNull();
    expect(validateParams({ w: 8, h: 8, diff: "easy" }, true)).not.toBeNull(); // 8*8 > 54
    expect(validateParams({ w: 5, h: 5, diff: "normal" }, true)).toBeNull();
  });
});

// --- generation + codec + solver (end-to-end) ------------------------------

describe("undead generation", () => {
  const cases: [number, number, Difficulty][] = [
    [4, 4, "easy"],
    [4, 4, "normal"],
    [4, 4, "tricky"],
    [5, 5, "normal"],
  ];
  for (const [w, h, diff] of cases) {
    it(`generates a unique, on-difficulty ${w}x${h} ${diff} board`, () => {
      const { params, desc, aux, state } = gen(w, h, diff, `${w}x${h}-${diff}`);
      expect(validateDesc(params, desc)).toBeNull();
      expect(isUniquelySolvable(state.common)).toBe(true);

      // The unique solution equals the generator's recorded solution.
      const sol = findUndeadSolution(state);
      expect(sol.ok).toBe(true);
      if (sol.ok) expect(Array.from(sol.guess)).toEqual(auxToGuess(aux));

      // The deductive ladder solves it with zero recursion, at the rung the
      // requested tier demands (the guess-free generation gate).
      const start = new Uint8Array(state.common.numTotal).fill(MON_NONE);
      const grade = solveDeductive(state.common, start);
      expect(grade.inconsistent).toBe(false);
      expect(grade.solved).toBe(true);
      if (diff === "easy") {
        expect(grade.rung).toBe(RUNG_ARC);
        expect(grade.arcPasses).toBeLessThanOrEqual(3);
      } else if (diff === "normal") {
        expect(
          (grade.rung === RUNG_ARC && grade.arcPasses > 3) ||
            grade.rung === RUNG_COUNTING,
        ).toBe(true);
      } else {
        expect(grade.rung).toBe(RUNG_FORCING);
      }
    }, 30_000);
  }
});

// --- desc decoding ---------------------------------------------------------

describe("undead validateDesc", () => {
  it("accepts a generated desc and rejects corruptions", () => {
    const { params, desc } = gen(4, 4, "normal", "valid");
    expect(validateDesc(params, desc)).toBeNull();
    expect(validateDesc(params, "")).not.toBeNull();
    expect(validateDesc(params, "0,2,6")).not.toBeNull(); // no grid/sightings
    // A grid character that overfills.
    expect(validateDesc(params, desc.replace(/^(\d+,\d+,\d+,)/, "$1z"))).not.toBeNull();
  });
});

// --- moves -----------------------------------------------------------------

describe("undead executeMove", () => {
  function emptyState(): UndeadState {
    return gen(4, 4, "normal", "moves").state;
  }

  it("places and clears a monster", () => {
    const s0 = emptyState();
    const s1 = undeadGame.executeMove(s0, {
      type: "set",
      cell: 0,
      monster: MON_ZOMBIE,
    });
    expect(s1.guess[0]).toBe(MON_ZOMBIE);
    const s2 = undeadGame.executeMove(s1, { type: "clear", cell: 0 });
    expect(s2.guess[0]).toBe(MON_NONE);
    expect(s0.guess[0]).toBe(MON_NONE); // original unmutated
  });

  it("toggles a pencil mark", () => {
    const s0 = emptyState();
    const s1 = undeadGame.executeMove(s0, {
      type: "pencil",
      cell: 0,
      monster: MON_GHOST,
    });
    expect(s1.pencils[0]).toBe(MON_GHOST);
    const s2 = undeadGame.executeMove(s1, {
      type: "pencil",
      cell: 0,
      monster: MON_GHOST,
    });
    expect(s2.pencils[0]).toBe(0);
  });

  it("fills all pencil marks on undecided cells", () => {
    const s0 = emptyState();
    const s1 = undeadGame.executeMove(s0, { type: "set", cell: 0, monster: MON_GHOST });
    const s2 = undeadGame.executeMove(s1, { type: "markAll" });
    expect(s2.pencils[0]).toBe(0); // cell 0 is placed, not pencilled
    for (let i = 1; i < s2.common.numTotal; i++) expect(s2.pencils[i]).toBe(7);
  });

  it("toggles an edge clue's done flag", () => {
    const s0 = emptyState();
    const s1 = undeadGame.executeMove(s0, { type: "hintDone", clue: 0 });
    expect(s1.hintsDone[0]).toBe(1);
    const s2 = undeadGame.executeMove(s1, { type: "hintDone", clue: 0 });
    expect(s2.hintsDone[0]).toBe(0);
  });

  it("marks the board solved when the full correct solution is placed", () => {
    const { state, aux } = gen(4, 4, "normal", "complete");
    const placements = auxToGuess(aux);
    let s = state;
    for (let i = 0; i < placements.length; i++) {
      s = undeadGame.executeMove(s, { type: "set", cell: i, monster: placements[i] });
    }
    expect(s.solved).toBe(true);
    expect(undeadGame.status(s)).toBe("solved");
  });

  it("reddens the count when a monster type is over-placed", () => {
    const { state } = gen(4, 4, "normal", "overcount");
    let s = state;
    // Place every cell as a zombie; once full, the counts must mismatch.
    for (let i = 0; i < s.common.numTotal; i++) {
      s = undeadGame.executeMove(s, { type: "set", cell: i, monster: MON_ZOMBIE });
    }
    expect([...s.countErrors].some((e) => e === 1)).toBe(true);
  });
});

// --- live flash ------------------------------------------------------------

describe("undead flash", () => {
  it("flashes on a genuine solve but not a cheated one", () => {
    const { state, aux } = gen(4, 4, "normal", "flash");
    const placements = auxToGuess(aux);
    let s = state;
    for (let i = 0; i < placements.length - 1; i++) {
      s = undeadGame.executeMove(s, { type: "set", cell: i, monster: placements[i] });
    }
    const before = s;
    const after = undeadGame.executeMove(s, {
      type: "set",
      cell: placements.length - 1,
      monster: placements[placements.length - 1],
    });
    expect(undeadGame.flashLength?.(before, after, 1, newUi(state))).toBeGreaterThan(0);

    const cheated = undeadGame.executeMove(state, { type: "solve", placements });
    expect(undeadGame.flashLength?.(state, cheated, 1, newUi(state))).toBe(0);
  });
});

// --- findMistakes ----------------------------------------------------------

describe("undead findMistakes", () => {
  it("flags a wrong placement and a note that crosses out the solution", () => {
    const { state, aux } = gen(4, 4, "normal", "mistakes");
    const sol = auxToGuess(aux);
    // A wrong monster at cell 0 (any value != solution).
    const wrong = sol[0] === MON_GHOST ? MON_VAMPIRE : MON_GHOST;
    let s = undeadGame.executeMove(state, { type: "set", cell: 0, monster: wrong });
    // A note at cell 1 that excludes its solution monster.
    const other = sol[1] === MON_GHOST ? MON_VAMPIRE : MON_GHOST;
    s = undeadGame.executeMove(s, { type: "pencil", cell: 1, monster: other });

    const mistakes = undeadGame.findMistakes?.(s) ?? [];
    expect(mistakes.some((m) => m.kind === "cell")).toBe(true);
    expect(mistakes.some((m) => m.kind === "note")).toBe(true);
  });

  it("ignores a note that still includes the solution monster", () => {
    const { state, aux } = gen(4, 4, "normal", "mistakes2");
    const sol = auxToGuess(aux);
    // A note at cell 0 that includes the solution plus an extra.
    const extra = sol[0] === MON_ZOMBIE ? MON_GHOST : MON_ZOMBIE;
    let s = undeadGame.executeMove(state, { type: "pencil", cell: 0, monster: sol[0] });
    s = undeadGame.executeMove(s, { type: "pencil", cell: 0, monster: extra });
    const mistakes = undeadGame.findMistakes?.(s) ?? [];
    expect(mistakes.length).toBe(0);
  });
});

// --- Solve via a real Midend -----------------------------------------------

describe("undead Solve via Midend", () => {
  it("solves a freshly generated board (aux path)", () => {
    const me = new Midend(undeadGame);
    expect(me.newGameFromId("4x4dn#undead-solve")).toBeUndefined();
    expect(me.solve()).toBeUndefined();
    const solved = (me as unknown as { state: UndeadState }).state;
    expect(undeadGame.status(solved)).toBe("solved");
    // Every cell is a single placed monster.
    for (let i = 0; i < solved.common.numTotal; i++) {
      const g = solved.guess[i];
      expect(g === MON_GHOST || g === MON_VAMPIRE || g === MON_ZOMBIE).toBe(true);
    }
  });
});

// --- render smoke (tier 2.5) -----------------------------------------------

describe("undead render", () => {
  it("redraws the initial frame and a partially-filled board", () => {
    const r0 = renderScenario({ game: undeadGame, id: "4x4dn#undead-render" });
    expect(r0.recording.ops.length).toBeGreaterThan(0);
    // The grid frame rect is painted.
    expect(r0.recording.ops.some((o) => o.op === "rect")).toBe(true);

    const r1 = renderScenario({
      game: undeadGame,
      id: "4x4dn#undead-render",
      moves: [{ type: "set", cell: 0, monster: MON_ZOMBIE }],
    });
    expect(r1.recording.ops.length).toBeGreaterThan(0);
    expect(r1.recording.ops).toMatchSnapshot();
  });
});

describe("on-screen keys (requestKeys)", () => {
  it("offers exactly Ghost/Vampire/Zombie plus clear", () => {
    expect(undeadGame.requestKeys?.(undeadGame.defaultParams())).toEqual([
      { button: "G".charCodeAt(0), label: "Ghost" },
      { button: "V".charCodeAt(0), label: "Vampire" },
      { button: "Z".charCodeAt(0), label: "Zombie" },
      { button: 8, label: "Clear" },
    ]);
  });
});

src/native/games/flip/flip-differential..source:
/*
 * Frozen differential check (behavioural, gating): asserts the Flip TS
 * port's generator against a committed snapshot of the C reference
 * (`__fixtures__/flip-c-reference.json`, produced by the deleted
 * `puzzles/flip-trace.c` before flip.c was removed). This is the
 * reproducible, C-free form of the differential spot-check; the live
 * C-vs-TS comparison lives in `scripts/diff-flip.test.ts` (advisory,
 * on-demand, not gated).
 *
 * Per the `flip` spec: CROSSES is deterministic and `random.ts` is
 * bit-identical, so the TS desc MUST equal the C reference exactly;
 * RANDOM uses an idiomatic generator and is EXPECTED to differ — there
 * the real bar is "every generated board is solvable".
 */

import { describe, expect, it } from "vitest";
import { randomNew } from "../../random/index.ts";
import cReference from "./__fixtures__/flip-c-reference.json" with { type: "json" };
import { type FlipParams, flipGame } from "./index.ts";

interface RefEntry {
  seed: string;
  w: number;
  h: number;
  matrixType: "crosses" | "random";
  desc: string;
}

const solveFlip = flipGame.solve as NonNullable<typeof flipGame.solve>;

describe("Flip differential vs frozen C reference", () => {
  for (const e of cReference as RefEntry[]) {
    const p: FlipParams = { w: e.w, h: e.h, matrixType: e.matrixType };
    const tag = `${e.w}x${e.h} ${e.matrixType} seed=${e.seed}`;

    if (e.matrixType === "crosses") {
      it(`${tag}: TS desc matches C exactly`, () => {
        const ts = flipGame.newDesc(p, randomNew(e.seed)).desc;
        expect(ts).toBe(e.desc);
      });
    } else {
      it(`${tag}: TS board solvable (RANDOM may differ from C)`, () => {
        const ts = flipGame.newDesc(p, randomNew(e.seed)).desc;
        expect(flipGame.validateDesc(p, ts)).toBeNull();
        const st = flipGame.newState(p, ts);
        const r = solveFlip(st, st);
        expect(r.ok).toBe(true);
      });
    }
  }
});

src/native/games/rect/rect-render-scenar.source:
/**
 * Tier-2.5 render scenarios for Rectangles: drive a real Midend to a target
 * frame and capture `redraw`. Targeted op assertions (number text, the grey
 * correct-rectangle fill after solving, the red mistake overlay) plus a
 * snapshot so a render regression is a reviewable text diff (`vitest -u`
 * re-baselines; the targeted assertions survive a careless `-u`).
 */
import { describe, expect, it } from "vitest";
import { renderScenario } from "../../engine/testing/render-scenario.ts";
import { randomNew } from "../../random/index.ts";
import { newDesc } from "./generator.ts";
import { rectGame } from "./index.ts";
import { newState } from "./moves.ts";
import { COL_CORRECT, COL_MISTAKE } from "./render.ts";
import type { RectMove, RectParams } from "./state.ts";

const P: RectParams = { w: 7, h: 7, expandfactor: 0, unique: true };
const ID = `${rectGame.encodeParams(P, true)}#rect-scenario`;

describe("rect render scenarios", () => {
  it("opener frame: number text drawn, no correct-fill yet", () => {
    const { recording } = renderScenario({ game: rectGame, id: ID });
    expect(recording.ops.some((o) => o.op === "text")).toBe(true);
    // Nothing is complete on a blank board, so no grey correct fill.
    expect(recording.ops.some((o) => o.op === "rect" && o.colour === COL_CORRECT)).toBe(
      false,
    );
    expect(recording.ops).toMatchSnapshot();
  });

  it("solved frame: grey correct fill covers the board", () => {
    // Build the solve move from the same id's board.
    const { desc } = newDesc(P, randomNew("rect-scenario"));
    const st = newState(P, desc);
    const solveMove = rectGame.solve?.(st, st, undefined);
    if (!solveMove?.ok) throw new Error("unsolvable");
    const { recording } = renderScenario({
      game: rectGame,
      id: ID,
      moves: [solveMove.move as RectMove],
    });
    // Every cell is correct → grey COL_CORRECT fill appears; flash is 0 here.
    expect(recording.ops.some((o) => o.op === "rect" && o.colour === COL_CORRECT)).toBe(
      true,
    );
  });

  it("mistake frame: a wrong wall shows the red overlay", () => {
    const { desc } = newDesc(P, randomNew("rect-scenario"));
    const st = newState(P, desc);
    const solveMove = rectGame.solve?.(st, st, undefined);
    if (!solveMove?.ok) throw new Error("unsolvable");
    const solved = rectGame.executeMove(st, solveMove.move);
    // Find an interior vedge not in the solution.
    let wrong: RectMove | null = null;
    for (let y = 0; y < P.h && !wrong; y++)
      for (let x = 1; x < P.w; x++)
        if (!solved.vedge[y * P.w + x]) {
          wrong = { type: "edge", edge: "v", x, y };
          break;
        }
    if (!wrong) throw new Error("no free edge");
    const { recording, mistakeCount } = renderScenario({
      game: rectGame,
      id: ID,
      moves: [wrong],
      showMistakes: true,
    });
    expect(mistakeCount).toBeGreaterThan(0);
    expect(recording.ops.some((o) => o.op === "rect" && o.colour === COL_MISTAKE)).toBe(
      true,
    );
  });
});

src/native/engine/mark-all.test.ts.source:
/**
 * Cross-game guarantee: **the Mark-all press only ever adds or removes pencil
 * marks — it never resets them.**
 *
 * This exists because the collection shipped the opposite for months and nothing
 * caught it. Every `pencilAll` implementation filled *every* empty cell with the
 * full candidate set, so pressing Mark-all (or asking for a hint, whose opener
 * reuses the same move) on a board with **some** narrowed cells and **some** blank
 * ones threw away the player's own deductions. It went unnoticed because the
 * usual latch — "does any empty cell lack notes?" — hides it whenever every empty
 * cell already has at least one note, which is the common case; you only see it on
 * the mixed board. Owner-reported on Salad, twice (the hint's opener, then the
 * button), and then fixed across all ten games that offer the press.
 *
 * The properties pinned here are deliberately representation-agnostic — each game
 * only says *where* its notes live — so a new game with a Mark-all press joins by
 * adding one row.
 */
import { describe, expect, it } from "vitest";
import { abcdGame } from "../games/abcd/index.ts";
import { groupGame } from "../games/group/index.ts";
import { keenGame } from "../games/keen/index.ts";
import { mathraxGame } from "../games/mathrax/index.ts";
import { saladGame } from "../games/salad/index.ts";
import { seismicGame } from "../games/seismic/index.ts";
import { soloGame } from "../games/solo/index.ts";
import { towersGame } from "../games/towers/index.ts";
import { undeadGame } from "../games/undead/index.ts";
import { unequalGame } from "../games/unequal/index.ts";
import { randomNew } from "../random/index.ts";
import { UI_UPDATE } from "./game.ts";
import { type AnyGame, firstLeaf } from "./testing/hint-games.ts";

/** Where a game keeps its pencil marks, and how many array slots one cell owns
 * (ABCD's notes are a candidate *cube*: `n` contiguous slots per cell — see its
 * `cuboid(x, y, i, n, w) = i + x*n + y*n*w`). */
interface Row {
  name: string;
  game: AnyGame;
  // biome-ignore lint/suspicious/noExplicitAny: a deliberately game-agnostic probe.
  notes: (state: any) => Int32Array | Uint8Array | Uint16Array;
  // biome-ignore lint/suspicious/noExplicitAny: params shape differs per game.
  slots?: (params: any) => number;
}

/** Every game answering `canMarkAll`. */
const MARK_ALL_GAMES: Row[] = [
  { name: "towers", game: towersGame, notes: (s) => s.pencil },
  { name: "keen", game: keenGame, notes: (s) => s.pencil },
  { name: "unequal", game: unequalGame, notes: (s) => s.pencil },
  { name: "solo", game: soloGame, notes: (s) => s.pencil },
  { name: "group", game: groupGame, notes: (s) => s.pencil },
  { name: "mathrax", game: mathraxGame, notes: (s) => s.marks },
  { name: "seismic", game: seismicGame, notes: (s) => s.marks },
  { name: "salad", game: saladGame, notes: (s) => s.marks },
  { name: "undead", game: undeadGame, notes: (s) => s.pencils },
  { name: "abcd", game: abcdGame, notes: (s) => s.pencil, slots: (p) => p.n },
];

it("every game offering the press is enrolled here", () => {
  // A game that ships `canMarkAll` without a row above would be unguarded.
  for (const { name, game } of MARK_ALL_GAMES) {
    expect(game.canMarkAll, `${name} does not offer a Mark-all press`).toBe(true);
  }
});

/** Press `M` — ASCII **77**, exactly what the toolbar button injects
 * (`puzzle-history.ts` `handleMarkAll`) — and apply whatever it asks for. Returns
 * the new state, or `null` when the press is a true no-op.
 *
 * Uppercase matters: Group intercepts only `'M'`, because lowercase `'m'` is its
 * element 13 for `w >= 13`. Probing with 109 there enters a value instead. */
function press(
  row: Row,
  // biome-ignore lint/suspicious/noExplicitAny: game-agnostic probe.
  state: any,
  // biome-ignore lint/suspicious/noExplicitAny: game-agnostic probe.
  ui: any,
  // biome-ignore lint/suspicious/noExplicitAny: game-agnostic probe.
): any | null {
  const move = row.game.interpretMove(state, ui, null, { x: 0, y: 0 }, 77);
  if (move === null || move === UI_UPDATE) return null;
  return row.game.executeMove(state, move);
}

// biome-ignore lint/suspicious/noExplicitAny: game-agnostic probe.
function board(row: Row, seed: string): { state: any; ui: any; params: any } {
  const params = firstLeaf(row.game.presets());
  const { desc } = row.game.newDesc(params, randomNew(seed));
  const state = row.game.newState(params, desc);
  return { state, ui: row.game.newUi(state), params };
}

describe("the Mark-all press converges", () => {
  for (const row of MARK_ALL_GAMES) {
    it(`${row.name}: repeated presses reach a true no-op`, () => {
      // Fill, then clean, then nothing — a further press must add no undo entry
      // at all rather than re-applying a move that changes nothing.
      const { state, ui } = board(row, `markall-${row.name}`);
      let cur = state;
      let presses = 0;
      for (; presses < 6; presses++) {
        const next = press(row, cur, ui);
        if (next === null) break;
        cur = next;
      }
      expect(presses, `${row.name}: did not converge`).toBeLessThan(6);
      expect(press(row, cur, ui)).toBeNull();
    });
  }
});

/** Remove exactly one candidate from cell `cell`, leaving at least one behind —
 * i.e. *narrow* it, the way a player crossing out a note does. Reports whether
 * the cell had two candidates to narrow between. Handles both note shapes: a
 * bitmask in one slot, or ABCD's one-flag-per-slot cube. */
function narrowOne(
  notes: Int32Array | Uint8Array | Uint16Array,
  cell: number,
  slots: number,
): boolean {
  if (slots === 1) {
    const v = notes[cell];
    if (v === 0 || (v & (v - 1)) === 0) return false; // needs two candidates
    notes[cell] = v & (v - 1); // clear the lowest set bit
    return true;
  }
  const set: number[] = [];
  for (let k = 0; k < slots; k++) if (notes[cell + k]) set.push(k);
  if (set.length < 2) return false;
  notes[cell + set[0]] = 0;
  return true;
}

describe("the Mark-all press never resets a note the player narrowed", () => {
  for (const row of MARK_ALL_GAMES) {
    it(`${row.name}: a fill leaves every already-noted cell bit-for-bit alone`, () => {
      const { state, ui, params } = board(row, `narrow-${row.name}`);

      // Run the press to convergence, so every fillable cell carries notes.
      let cur = state;
      for (let i = 0; i < 6; i++) {
        const next = press(row, cur, ui);
        if (next === null) break;
        cur = next;
      }

      // Reproduce the reported board: one cell **narrowed** by hand, a *different*
      // one blank, so the press has something to fill and something to spare.
      //
      // Poking the arrays directly is deliberate. The point is to build the state
      // shape, not the route to it — the per-cell pencil toggle differs in every
      // game, and `cur` is a fresh clone from `executeMove`, so nothing shared is
      // mutated. Note the *narrowing* is what makes this test bite: with no
      // narrowed cell, a resetting fill writes back exactly what was there and the
      // bug hides (which it did in the first cut of this test — Towers has no
      // givens, so its clean press strikes nothing and every cell keeps its full
      // candidate set).
      const slots = row.slots?.(params) ?? 1;
      const notes = row.notes(cur);
      let narrowed = -1;
      for (let i = 0; i + slots <= notes.length; i += slots) {
        if (narrowOne(notes, i, slots)) {
          narrowed = i;
          break;
        }
      }
      expect(
        narrowed,
        `${row.name}: no cell had two candidates to narrow between`,
      ).toBeGreaterThanOrEqual(0);

      let blank = -1;
      for (let i = 0; i + slots <= notes.length; i += slots) {
        if (i === narrowed) continue;
        let any = false;
        for (let k = 0; k < slots; k++) if (notes[i + k] !== 0) any = true;
        if (any) {
          blank = i;
          break;
        }
      }
      expect(
        blank,
        `${row.name}: no second noted cell to blank`,
      ).toBeGreaterThanOrEqual(0);
      for (let k = 0; k < slots; k++) notes[blank + k] = 0;
      const before = Array.from(notes);

      const after = press(row, cur, ui);
      expect(
        after,
        `${row.name}: the press did not refill the blank cell`,
      ).not.toBeNull();
      const filled = Array.from(row.notes(after));

      // The blank cell is filled again…
      expect(
        filled.slice(blank, blank + slots).some((v) => v !== 0),
        `${row.name}: the note-less cell was not refilled`,
      ).toBe(true);
      // …and every other cell is untouched — in particular the narrowed one keeps
      // the candidate it lost. This is the whole regression: a resetting fill
      // widens every narrowed cell back to its full set.
      for (let i = 0; i < before.length; i++) {
        if (i >= blank && i < blank + slots) continue;
        expect(
          filled[i],
          `${row.name}: the fill changed an already-noted cell at index ${i}`,
        ).toBe(before[i]);
      }
    });
  }
});

