    const ui = newUi();
    ui.pencilSticky = false;
    const open = state.puzzle.walls.indexOf(0);
    const c = cellCentre(open % 5, Math.floor(open / 5));
    press(state, ui, RIGHT_BUTTON, c.x, c.y);
    expect(ui).toMatchObject({ cpencil: true, cshow: true });
