/**
 * Tier-1 tests for the Guess Game glue: move execution + purity,
 * win/lose/reveal transitions, the `changedState` hold-carry, the
 * hint-fills-the-working-row behaviour (played end-to-end), and key
 * input mapping.
 */
import { describe, expect, it } from "vitest";
import { CURSOR_SELECT } from "../../engine/pointer.ts";
import { randomNew } from "../../random/index.ts";
import { guessGame } from "./index.ts";
import {
  defaultParams,
  type GuessMove,
  type GuessState,
  type GuessUi,
  newDesc,
  newState,
  status,
} from "./state.ts";

const ZERO = { x: 0, y: 0 };

function freshGame(
  seed = "seed-X",
  params = defaultParams(),
): { state: GuessState; ui: GuessUi } {
  const { desc } = newDesc(params, randomNew(seed));
  const state = newState(params, desc);
  const ui = guessGame.newUi(state);
  guessGame.changedState?.(ui, null, state);
  return { state, ui };
}

function submit(pegs: number[], holds?: boolean[]): GuessMove {
  return { type: "guess", pegs, holds: holds ?? pegs.map(() => false) };
}

describe("executeMove", () => {
  it("a correct guess wins", () => {
    const { state } = freshGame();
    const next = guessGame.executeMove(state, submit(state.solution.slice()));
    expect(next.solved).toBe(1);
    expect(status(next)).toBe("solved");
    // The winning row is stored at nextGo (unchanged) with all-place feedback.
    expect(next.guesses[next.nextGo].feedback.every((f) => f === 1)).toBe(true);
  });

  it("is pure (source state unchanged)", () => {
    const { state } = freshGame();
    const before = JSON.stringify(state);
    guessGame.executeMove(state, submit(state.solution.slice()));
    expect(JSON.stringify(state)).toBe(before);
  });

  it("a wrong guess advances next_go and stores feedback", () => {
    const { state } = freshGame();
    const wrong = state.solution.slice();
    wrong[0] = (wrong[0] % state.params.ncolours) + 1; // perturb one peg
    const next = guessGame.executeMove(state, submit(wrong));
    expect(next.solved).toBe(0);
    expect(next.nextGo).toBe(1);
    expect(next.guesses[0].pegs).toEqual(wrong);
  });

  it("exhausting the rows loses and reveals", () => {
    const params = { ...defaultParams(), nguesses: 1 };
    const { state } = freshGame("oneshot", params);
    const wrong = state.solution.slice();
    wrong[0] = (wrong[0] % params.ncolours) + 1;
    const next = guessGame.executeMove(state, submit(wrong));
    expect(next.solved).toBe(-1);
    expect(status(next)).toBe("lost");
  });

  it("solve reveals (give-up = loss reveal)", () => {
    const { state } = freshGame();
    const res = guessGame.solve?.(state, state);
    expect(res?.ok).toBe(true);
    if (res?.ok) {
      const next = guessGame.executeMove(state, res.move);
      expect(next.solved).toBe(-1);
      expect(status(next)).toBe("lost");
    }
  });

  it("rejects an out-of-range peg", () => {
    const { state } = freshGame();
    expect(() => guessGame.executeMove(state, submit([1, 2, 3, 99]))).toThrow();
  });
});

describe("changedState (hold-carry)", () => {
  it("carries held pegs into the next working row, clears the rest", () => {
    const { state, ui } = freshGame();
    const guess = state.solution.slice();
    guess[1] = (guess[1] % state.params.ncolours) + 1; // ensure not a win
    const holds = [true, false, false, false];
    const next = guessGame.executeMove(state, submit(guess, holds));
    guessGame.changedState?.(ui, state, next);
    expect(ui.currPegs[0]).toBe(guess[0]); // held
    expect(ui.currPegs.slice(1)).toEqual([0, 0, 0]); // cleared
    expect(ui.holds[0]).toBe(true);
  });

  it("clears the working row and holds on a win", () => {
    const { state, ui } = freshGame();
    ui.holds[0] = true;
    const next = guessGame.executeMove(
      state,
      submit(state.solution.slice(), [true, false, false, false]),
    );
    guessGame.changedState?.(ui, state, next);
    expect(ui.currPegs).toEqual([0, 0, 0, 0]);
    expect(ui.holds.every((h) => !h)).toBe(true);
  });

  it("drops the cached hint on an undo (next_go decreases)", () => {
    const { state, ui } = freshGame();
    ui.hint = [1, 1, 1, 1];
    const wrong = state.solution.slice();
    wrong[0] = (wrong[0] % state.params.ncolours) + 1;
    const next = guessGame.executeMove(state, submit(wrong)); // nextGo 0 -> 1
    guessGame.changedState?.(ui, next, state); // simulate undo: new < old
    expect(ui.hint).toBeNull();
  });
});

describe("hint (compute_hint)", () => {
  it("solving by always taking the hint wins within the guess limit", () => {
    const params = defaultParams();
    let { state, ui } = freshGame("hint-solve", params);
    let guesses = 0;
    while (state.solved === 0 && guesses < params.nguesses) {
      // Press the hint key: fills ui.currPegs with a consistent row.
      const r = guessGame.interpretMove(state, ui, null, ZERO, 0x68 /* 'h' */);
      expect(r).toBeTruthy();
      const move = submit(ui.currPegs.slice());
      state = guessGame.executeMove(state, move);
      guessGame.changedState?.(ui, state, state);
      guesses++;
    }
    expect(state.solved).toBe(1);
  });

  it("the hint row is consistent with every prior guess's feedback", () => {
    const params = defaultParams();
    const { state: s0, ui } = freshGame("hint-consistency", params);
    // Submit one deliberate wrong guess to create feedback.
    const wrong = [1, 2, 3, 4];
    const s1 = guessGame.executeMove(s0, submit(wrong));
    guessGame.changedState?.(ui, s0, s1);
    guessGame.interpretMove(s1, ui, null, ZERO, 0x68);
    // Re-score the hint row against the prior guess; it must reproduce
    // that guess's feedback (the definition of "consistent").
    // Use the same maxcolour bound compute_hint uses (here ncolours).
    const hintRow = ui.currPegs.slice();
    // markPegs(hintRow, priorGuessPegs) equals priorGuess feedback.
    // (compute_hint guarantees this for the recorded feedback.)
    expect(hintRow.every((c) => c >= 1 && c <= params.ncolours)).toBe(true);
  });
});

describe("interpretMove keyboard", () => {
  it("number keys place a peg and advance the cursor", () => {
    const { state, ui } = freshGame();
    ui.displayCur = true;
    const r = guessGame.interpretMove(state, ui, null, ZERO, 0x33 /* '3' */);
    expect(r).toBeTruthy();
    expect(ui.currPegs[0]).toBe(3);
    expect(ui.pegCur).toBe(1);
  });

  it("submit is offered only for a markable row", () => {
    const { state, ui } = freshGame();
    // Fill all pegs → markable; move cursor to submit position.
    for (let i = 0; i < state.params.npegs; i++) ui.currPegs[i] = 1;
    ui.markable = true;
    ui.pegCur = state.params.npegs;
    ui.displayCur = true;
    const r = guessGame.interpretMove(state, ui, null, ZERO, CURSOR_SELECT);
    expect(r).toMatchObject({ type: "guess" });
  });

  it("the label toggle works even after the game ends", () => {
    const { state, ui } = freshGame();
    const solved = guessGame.executeMove(state, submit(state.solution.slice()));
    const before = ui.showLabels;
    const r = guessGame.interpretMove(solved, ui, null, ZERO, 0x6c /* 'l' */);
    expect(r).toBeTruthy();
    expect(ui.showLabels).toBe(!before);
  });
});

src/native/games/blackbox/blackbox.test..source:
/**
 * Tier-1 logic tests for Black Box: the laser ray-tracer (straight pass,
 * head-on hit, entry reflection, exit reciprocity), guess verification
 * counting, desc obfuscation round-trip + rejection, params round-trip +
 * validation, and the status mapping.
 *
 * The tracer is exercised through the public `Game` surface (build a
 * state with known balls, fire via `executeMove`, read `exits`) rather
 * than the internal functions, so the tests pin observable behaviour.
 */

import { describe, expect, it } from "vitest";
import { randomNew } from "../../random/index.ts";
import { blackboxGame } from "./index.ts";
import {
  BALL_CORRECT,
  type BlackboxState,
  type BlackboxUi,
  decodeParams,
  defaultParams,
  encodeParams,
  grid2range,
  LASER_EMPTY,
  LASER_HIT,
  LASER_REFLECT,
  newDesc,
  newState,
  validateDesc,
  validateParams,
} from "./state.ts";

/** Build a state with balls at 0-indexed arena coords `[x, y]`. */
function makeState(
  w: number,
  h: number,
  balls: Array<[number, number]>,
): BlackboxState {
  const nlasers = 2 * (w + h);
  const grid = new Int32Array((w + 2) * (h + 2));
  for (const [bx, by] of balls) grid[(by + 1) * (w + 2) + (bx + 1)] = BALL_CORRECT;
  return {
    w,
    h,
    minballs: balls.length,
    maxballs: balls.length,
    nballs: balls.length,
    nlasers,
    grid,
    exits: new Int32Array(nlasers).fill(LASER_EMPTY),
    laserno: 1,
    nguesses: 0,
    nright: 0,
    nwrong: 0,
    nmissed: 0,
    reveal: false,
    justwrong: false,
  };
}

/** rangeno of the top-row firing cell above arena column `ax` (0-indexed). */
function topRange(w: number, h: number, ax: number): number {
  return grid2range(w, h, ax + 1, 0) as number;
}
/** rangeno of the bottom-row firing cell below arena column `ax`. */
function bottomRange(w: number, h: number, ax: number): number {
  return grid2range(w, h, ax + 1, h + 1) as number;
}

function fire(s: BlackboxState, rangeno: number): BlackboxState {
  return blackboxGame.executeMove(s, { type: "fire", rangeno });
}

describe("Black Box — laser tracer", () => {
  it("passes straight through an empty arena and pairs entry/exit", () => {
    const s = makeState(5, 5, []);
    const top = topRange(5, 5, 0); // column 1
    const bottom = bottomRange(5, 5, 0);
    const after = fire(s, top);
    expect(after.exits[top]).toBe(bottom);
    expect(after.exits[bottom]).toBe(top);
  });

  it("reports a hit on a head-on ball", () => {
    // Ball in column 1 (arena x=0), fired from the top of column 1.
    const s = makeState(5, 5, [[0, 2]]);
    const top = topRange(5, 5, 0);
    const after = fire(s, top);
    expect(after.exits[top]).toBe(LASER_HIT);
  });

  it("reflects instantly when a ball sits diagonally at the entry", () => {
    // Entry is top of column 1 heading down; a ball at arena (1,0) sits
    // diagonally ahead, forcing an immediate reflection.
    const s = makeState(5, 5, [[1, 0]]);
    const top = topRange(5, 5, 0);
    const after = fire(s, top);
    expect(after.exits[top]).toBe(LASER_REFLECT);
  });

  it("deflects around a ball and exits elsewhere", () => {
    // A single off-column ball deflects the beam to a different exit
    // (neither hit, reflect, nor the straight-through pairing).
    const s = makeState(5, 5, [[1, 1]]);
    const top = topRange(5, 5, 0);
    const straight = bottomRange(5, 5, 0);
    const after = fire(s, top);
    const e = after.exits[top];
    expect(e).not.toBe(LASER_HIT);
    expect(e).not.toBe(LASER_REFLECT);
    expect(e).not.toBe(LASER_EMPTY);
    expect(e).not.toBe(straight);
    // Whatever the exit, it is reciprocal.
    expect(after.exits[e]).toBe(top);
  });

  it("keeps every fired laser reciprocal across a full sweep", () => {
    let s = makeState(6, 6, [
      [0, 0],
      [2, 3],
      [4, 1],
      [5, 5],
      [3, 4],
    ]);
    for (let i = 0; i < s.nlasers; i++) {
      if (s.exits[i] !== LASER_EMPTY) continue;
      s = fire(s, i);
    }
    for (let i = 0; i < s.nlasers; i++) {
      const e = s.exits[i];
      if (e === LASER_EMPTY || e === LASER_HIT || e === LASER_REFLECT) continue;
      expect(s.exits[e]).toBe(i);
    }
  });

  it("rejects firing an already-fired laser", () => {
    const s = makeState(5, 5, []);
    const top = topRange(5, 5, 0);
    const after = fire(s, top);
    expect(() => fire(after, top)).toThrow();
  });
});

describe("Black Box — guess verification", () => {
  const balls: Array<[number, number]> = [
    [0, 0],
    [1, 1],
    [2, 2],
  ];

  function mark(s: BlackboxState, x: number, y: number): BlackboxState {
    return blackboxGame.executeMove(s, { type: "toggleBall", x: x + 1, y: y + 1 });
  }

  it("counts right / wrong / missed on a give-up reveal", () => {
    let s = makeState(5, 5, balls);
    s = mark(s, 0, 0); // correct
    s = mark(s, 1, 1); // correct
    s = mark(s, 3, 3); // wrong (real ball at 2,2 is missed)
    const revealed = blackboxGame.executeMove(s, { type: "solve" });
    expect(revealed.reveal).toBe(true);
    expect(revealed.nright).toBe(2);
    expect(revealed.nwrong).toBe(1);
    expect(revealed.nmissed).toBe(1);
    expect(blackboxGame.status(revealed)).toBe("lost");
  });

  it("solves when every ball is guessed correctly", () => {
    let s = makeState(5, 5, balls);
    for (const [x, y] of balls) s = mark(s, x, y);
    const revealed = blackboxGame.executeMove(s, { type: "reveal" });
    expect(revealed.reveal).toBe(true);
    expect(revealed.nright).toBe(3);
    expect(revealed.nwrong).toBe(0);
    expect(revealed.nmissed).toBe(0);
    expect(blackboxGame.status(revealed)).toBe("solved");
  });

  it("shows one error without revealing on an inconsistent verify", () => {
    let s = makeState(5, 5, balls);
    s = mark(s, 0, 0);
    s = mark(s, 1, 1);
    s = mark(s, 3, 3); // wrong
    const verified = blackboxGame.executeMove(s, { type: "reveal" });
    expect(verified.justwrong).toBe(true);
    expect(verified.reveal).toBe(false);
    expect(blackboxGame.status(verified)).toBe("ongoing");
  });

  it("rejects a reveal when too few balls are marked", () => {
    let s = makeState(5, 5, balls);
    s = mark(s, 0, 0); // only one of three
    expect(() => blackboxGame.executeMove(s, { type: "reveal" })).toThrow();
  });

  it("bumps the session error counter on a wrong move via changedState", () => {
    let s = makeState(5, 5, balls);
    s = mark(s, 0, 0);
    s = mark(s, 1, 1);
    s = mark(s, 3, 3);
    const verified = blackboxGame.executeMove(s, { type: "reveal" });
    const ui = blackboxGame.newUi(s);
    ui.newmove = true; // a real move was just made
    blackboxGame.changedState?.(ui, s, verified);
    expect(ui.errors).toBe(1);
    expect(ui.newmove).toBe(false);
  });
});

describe("Black Box — desc codec", () => {
  it("recovers the scattered balls through obfuscation", () => {
    const p = defaultParams();
    const { desc } = newDesc(p, randomNew("blackbox-desc"));
    expect(validateDesc(p, desc)).toBeNull();
    const s = newState(p, desc);
    let placed = 0;
    for (let i = 0; i < s.grid.length; i++) if (s.grid[i] & BALL_CORRECT) placed++;
    expect(placed).toBe(s.nballs);
    expect(s.nballs).toBeGreaterThanOrEqual(p.minballs);
    expect(s.nballs).toBeLessThanOrEqual(p.maxballs);
    expect(s.w).toBe(p.w);
    expect(s.h).toBe(p.h);
  });

  it("rejects a description of the wrong length", () => {
    const p = defaultParams();
    expect(validateDesc(p, "abc")).not.toBeNull();
  });

  it("rejects a description whose balls fall outside the arena", () => {
    // A 2x2 board needs a ball coord < 2; craft an obfuscated desc that
    // de-obfuscates to an out-of-range ball by perturbing a valid one.
    const p = { w: 2, h: 2, minballs: 1, maxballs: 1 };
    const { desc } = newDesc(p, randomNew("oob"));
    // Flip a hex nibble in the ball-coord region to corrupt it; at least
    // one perturbation must produce an out-of-range / mismatched header.
    let rejected = false;
    for (let i = 0; i < desc.length; i++) {
      const c = desc[i] === "f" ? "0" : "f";
      const bad = desc.slice(0, i) + c + desc.slice(i + 1);
      if (validateDesc(p, bad) !== null) {
        rejected = true;
        break;
      }
    }
    expect(rejected).toBe(true);
  });
});

describe("Black Box — params", () => {
  it("round-trips encode/decode", () => {
    const p = { w: 8, h: 8, minballs: 3, maxballs: 6 };
    expect(encodeParams(p, true)).toBe("w8h8m3M6");
    expect(decodeParams("w8h8m3M6")).toEqual(p);
  });

  it("ignores unknown letters on decode", () => {
    expect(decodeParams("w5zzh5m3M3")).toEqual({
      w: 5,
      h: 5,
      minballs: 3,
      maxballs: 3,
    });
  });

  it("rejects invalid params", () => {
    expect(
      validateParams({ w: 1, h: 5, minballs: 1, maxballs: 1 }, true),
    ).not.toBeNull();
    expect(
      validateParams({ w: 5, h: 5, minballs: 0, maxballs: 1 }, true),
    ).not.toBeNull();
    expect(
      validateParams({ w: 5, h: 5, minballs: 4, maxballs: 2 }, true),
    ).not.toBeNull();
    expect(
      validateParams({ w: 3, h: 3, minballs: 9, maxballs: 9 }, true),
    ).not.toBeNull();
    expect(validateParams({ w: 8, h: 8, minballs: 5, maxballs: 5 }, true)).toBeNull();
  });
});

describe("Black Box — Game surface", () => {
  it("reports its capability flags", () => {
    expect(blackboxGame.id).toBe("blackbox");
    expect(blackboxGame.wantsStatusbar).toBe(true);
    expect(blackboxGame.canSolve).toBe(true);
    expect(blackboxGame.hint).toBeUndefined();
    expect(blackboxGame.findMistakes).toBeUndefined();
  });

  it("produces the correct status-bar text across phases", () => {
    const s = makeState(8, 8, [
      [0, 0],
      [1, 1],
      [2, 2],
      [3, 3],
      [4, 4],
    ]);
    const ui: BlackboxUi = blackboxGame.newUi(s);
    expect(blackboxGame.statusbarText?.(s, ui)).toContain("Balls marked: 0 / 5");
  });
});

