// Tier-2 render test (see the `repo-layout` spec): drive Cube's `redraw`
// against a recording `GameDrawing` double and assert the structure of
// the draw calls — a background fill, one polygon per grid square (blue
// squares in COL_BLUE), the projected solid's faces, and a final update.
import { describe, expect, it } from "vitest";
import type { GameDrawing } from "../../engine/game.ts";
import { gridArea } from "./grid.ts";
import { cubeGame, executeMove } from "./index.ts";
import { COL_BACKGROUND, COL_BLUE } from "./render.ts";
import { SOLIDS, SolidType } from "./solids.ts";
import { type CubeParams, newState } from "./state.ts";

interface Op {
  op: string;
  colour?: number;
  x?: number;
  y?: number;
  w?: number;
  h?: number;
}

function recordingDrawing(): { dr: GameDrawing; ops: Op[] } {
  const ops: Op[] = [];
  const dr = {
    startDraw: () => ops.push({ op: "startDraw" }),
    endDraw: () => ops.push({ op: "endDraw" }),
    drawUpdate: (r: { x: number; y: number; w: number; h: number }) =>
      ops.push({ op: "drawUpdate", x: r.x, y: r.y, w: r.w, h: r.h }),
    clip: () => ops.push({ op: "clip" }),
    unclip: () => ops.push({ op: "unclip" }),
    drawRect: (r: { x: number; y: number; w: number; h: number }, c: number) =>
      ops.push({ op: "drawRect", colour: c, x: r.x, y: r.y, w: r.w, h: r.h }),
    drawLine: (_a: unknown, _b: unknown, c: number) =>
      ops.push({ op: "drawLine", colour: c }),
    drawPolygon: (_p: unknown, f: number) => ops.push({ op: "drawPolygon", colour: f }),
    drawCircle: (_p: unknown, _r: number, f: number) =>
      ops.push({ op: "drawCircle", colour: f }),
    drawText: (_p: unknown, _o: unknown, c: number) =>
      ops.push({ op: "drawText", colour: c }),
    blitterNew: () => ({}),
    blitterFree: () => {},
    blitterSave: () => {},
    blitterLoad: () => {},
  } as unknown as GameDrawing;
  return { dr, ops };
}

const newDrawState = cubeGame.newDrawState as NonNullable<typeof cubeGame.newDrawState>;
const setTileSize = cubeGame.setTileSize as NonNullable<typeof cubeGame.setTileSize>;
const redraw = cubeGame.redraw as NonNullable<typeof cubeGame.redraw>;

/** A cube board with square 0 painted blue and the solid starting on a
 * non-blue square, sized at the preferred tile size. */
function freshCube() {
  const p: CubeParams = { solid: SolidType.Cube, d1: 4, d2: 4 };
  const area = gridArea(p.d1, p.d2, SOLIDS[p.solid].order);
  // Square 0 blue (top nibble bit 0x8), start on square 5.
  const desc = `8${"0".repeat(Math.floor((area + 3) / 4) - 1)},5`;
  const state = newState(p, desc);
  const ds = newDrawState(state);
  setTileSize(ds, cubeGame.preferredTileSize ?? 48);
  return { p, state, ds };
}

describe("Cube rendering", () => {
  it("paints a background fill, every grid square, the solid, and an update", () => {
    const { state, ds } = freshCube();
    const { dr, ops } = recordingDrawing();

    redraw(dr, ds, null, state, 0, {}, 0, 0);

    // A background rect at the origin.
    expect(
      ops.some(
        (o) =>
          o.op === "drawRect" && o.x === 0 && o.y === 0 && o.colour === COL_BACKGROUND,
      ),
    ).toBe(true);

    // One polygon per grid square is drawn before the solid's faces; the
    // total polygon count exceeds the square count by the visible faces.
    const polys = ops.filter((o) => o.op === "drawPolygon");
    expect(polys.length).toBeGreaterThan(state.grid.length);

    // The first `grid.length` polygons are the grid squares; square 0 is
    // blue, so at least one square polygon uses COL_BLUE.
    const squarePolys = polys.slice(0, state.grid.length);
    expect(squarePolys.some((o) => o.colour === COL_BLUE)).toBe(true);

    // A final drawUpdate covering the canvas.
    expect(ops.some((o) => o.op === "drawUpdate")).toBe(true);
  });

  it("draws fewer faces than the solid has (back-face culling)", () => {
    const { state, ds } = freshCube();
    const { dr, ops } = recordingDrawing();
    redraw(dr, ds, null, state, 0, {}, 0, 0);

    const polys = ops.filter((o) => o.op === "drawPolygon");
    const facePolys = polys.length - state.grid.length;
    // A cube shows at most 3 faces at once; culling must drop the rest.
    expect(facePolys).toBeGreaterThan(0);
    expect(facePolys).toBeLessThan(SOLIDS[SolidType.Cube].nfaces);
  });

  it("animates a roll without throwing and still draws the solid", () => {
    const { state, ds } = freshCube();
    const rolled = executeMove(state, { dir: "R" });
    const { dr, ops } = recordingDrawing();

    // Mid-roll: prev = old state, animTime between 0 and ROLLTIME.
    redraw(dr, ds, state, rolled, 0, {}, 0.06, 0);

    const polys = ops.filter((o) => o.op === "drawPolygon");
    expect(polys.length).toBeGreaterThan(state.grid.length);
  });
});

src/native/games/guess/guess-render.test.source:
/**
 * Tier-2 render-ops test: drive Guess's `redraw` against a recording
 * `GameDrawing` double and assert the draw-call structure — the
 * first-draw background fill, a correct-place feedback marker in
 * COL_CORRECTPLACE, the hold bar in COL_HOLD on a held slot, and the
 * solution reveal appearing only once the game is over.
 */
import { describe, expect, it } from "vitest";
import type { GameDrawing } from "../../engine/game.ts";
import { randomNew } from "../../random/index.ts";
import { guessGame } from "./index.ts";
import {
  COL_BACKGROUND,
  COL_CORRECTPLACE,
  COL_HOLD,
  type GuessDrawState,
  redraw,
} from "./render.ts";
import { defaultParams, type GuessUi, newDesc, newState } from "./state.ts";

interface Op {
  op: string;
  colour?: number;
  x?: number;
  y?: number;
  w?: number;
  h?: number;
  r?: number;
}

function recordingDrawing(): { dr: GameDrawing; ops: Op[] } {
  const ops: Op[] = [];
  const dr = {
    startDraw: () => ops.push({ op: "startDraw" }),
    endDraw: () => ops.push({ op: "endDraw" }),
    drawUpdate: () => ops.push({ op: "drawUpdate" }),
    clip: () => ops.push({ op: "clip" }),
    unclip: () => ops.push({ op: "unclip" }),
    drawRect: (r: { x: number; y: number; w: number; h: number }, c: number) =>
      ops.push({ op: "drawRect", colour: c, x: r.x, y: r.y, w: r.w, h: r.h }),
    drawLine: (_a: unknown, _b: unknown, c: number) =>
      ops.push({ op: "drawLine", colour: c }),
    drawPolygon: (p: { x: number; y: number }[], f: number) =>
      ops.push({ op: "drawPolygon", colour: f, x: p[0].x, y: p[0].y }),
    drawCircle: (p: { x: number; y: number }, r: number, f: number) =>
      ops.push({ op: "drawCircle", colour: f, r, x: p.x, y: p.y }),
    drawText: () => ops.push({ op: "drawText" }),
    blitterNew: () => ({}),
    blitterFree: () => {},
    blitterSave: () => {},
    blitterLoad: () => {},
  } as unknown as GameDrawing;
  return { dr, ops };
}

const TS = 32;
const params = defaultParams();

function freshDs(): GuessDrawState {
  const ds = guessGame.newDrawState?.(newState(params, "01020304")) as GuessDrawState;
  guessGame.setTileSize?.(ds, TS);
  return ds;
}

function freshUi(state = newState(params, "01020304")): GuessUi {
  const ui = guessGame.newUi(state);
  guessGame.changedState?.(ui, null, state);
  return ui;
}

describe("Guess redraw", () => {
  it("fills the background on first draw", () => {
    const s = newState(params, "01020304");
    const ds = freshDs();
    const { dr, ops } = recordingDrawing();
    redraw(dr, ds, null, s, 1, freshUi(s), 0, 0);
    expect(
      ops.some(
        (o) =>
          o.op === "drawRect" &&
          o.colour === COL_BACKGROUND &&
          o.w === ds.w &&
          o.h === ds.h,
      ),
    ).toBe(true);
  });

  it("draws a correct-place feedback marker after a scored guess", () => {
    const { desc } = newDesc(params, randomNew("render-fb"));
    const s0 = newState(params, desc);
    const wrong = s0.solution.slice();
    wrong[0] = (wrong[0] % params.ncolours) + 1; // 3 exact matches remain
    const s1 = guessGame.executeMove(s0, {
      type: "guess",
      pegs: wrong,
      holds: [false, false, false, false],
    });
    expect(s1.guesses[0].feedback).toContain(1); // FEEDBACK_CORRECTPLACE

    const ds = freshDs();
    const ui = freshUi(s1);
    const { dr, ops } = recordingDrawing();
    redraw(dr, ds, s0, s1, 1, ui, 0, 0);
    expect(
      ops.some((o) => o.op === "drawCircle" && o.colour === COL_CORRECTPLACE),
    ).toBe(true);
  });

  it("draws the hold bar on a held active slot", () => {
    const s = newState(params, "01020304");
    const ds = freshDs();
    const ui = freshUi(s);
    ui.holds[0] = true;
    const { dr, ops } = recordingDrawing();
    redraw(dr, ds, null, s, 1, ui, 0, 0);
    expect(
      ops.some((o) => o.op === "drawRect" && o.colour === COL_HOLD && o.h === 2),
    ).toBe(true);
  });

  it("reveals the solution row only once the game is over", () => {
    const { desc } = newDesc(params, randomNew("render-reveal"));
    const s0 = newState(params, desc);

    // Unsolved: no peg circles in the solution row (y >= solny).
    const dsA = freshDs();
    const { dr: drA, ops: opsA } = recordingDrawing();
    redraw(drA, dsA, null, s0, 1, freshUi(s0), 0, 0);
    const pegCircle = (o: Op) =>
      o.op === "drawCircle" &&
      o.colour !== undefined &&
      o.colour >= 6 &&
      o.colour <= 15;
    expect(opsA.some((o) => pegCircle(o) && (o.y ?? 0) >= dsA.solny)).toBe(false);

    // Solved: the solution pegs are revealed in the solution row.
    const won = guessGame.executeMove(s0, {
      type: "guess",
      pegs: s0.solution.slice(),
      holds: [false, false, false, false],
    });
    const dsB = freshDs();
    const { dr: drB, ops: opsB } = recordingDrawing();
    redraw(drB, dsB, s0, won, 1, freshUi(won), 0, 0);
    expect(opsB.some((o) => pegCircle(o) && (o.y ?? 0) >= dsB.solny)).toBe(true);
  });
});

src/native/engine/palette.test.ts.source:
/**
 * The **meanings** half of the colour guard.
 *
 * The palette itself is measured in [`colours.test.ts`](./colours.test.ts) — how
 * far apart the colours are, in both schemes. What is left for this file is the
 * relationship between the two layers, and it is the one thing that keeps the
 * collapse from unwinding: **a meaning holds no value of its own**. The moment
 * `ERROR` is a red rather than *the* red, restyling red stops restyling errors,
 * and the ~190-token sprawl starts growing back one role at a time.
 *
 * The source half of the guard — "a game contains no colour value" — is
 * [`palette-source.test.ts`](./palette-source.test.ts), which reads the game
 * sources, because that requirement is about where a colour is written rather
 * than what it is.
 */
import { describe, expect, it } from "vitest";
import type { Colour } from "../../puzzle/types.ts";
import { colourToOKLCH, isGrayChroma, type OKLCH } from "../../utils/color.ts";
import { getTsGame } from "./registry.ts";
import "../games/index.ts";
import { mkhighlight } from "./colour-mkhighlight.ts";
import { darkValue } from "./colour-token.ts";
import * as colours from "./colours.ts";
import * as roles from "./palette.ts";

/** A light host background, standing in for the frontend's theme colour. */
const BG: Colour = [0.827, 0.827, 0.827];

const key = (c: Colour): string => c.map((v) => Math.round(v * 1000) / 1000).join(",");

/**
 * Call a derived role, whatever it takes.
 *
 * Most roles are a function of the background alone; `wallColour` also needs the
 * highlight, because "a quarter of the way from the floor toward its bevel" is
 * what the colour *means*. Dispatching on arity keeps that one exception from
 * needing a hand-maintained list here — a new role is picked up automatically.
 */
// biome-ignore lint/complexity/noBannedTypes: the role table is heterogeneous by design.
function resolve(fn: Function, background: Colour, highlight: Colour): Colour {
  return fn.length === 2
    ? (fn as (b: Colour, h: Colour) => Colour)(background, highlight)
    : (fn as (b: Colour) => Colour)(background);
}

describe("the shared colour vocabulary", () => {
  it("defines every meaning in terms of a named colour", () => {
    // The whole point of the two layers. A meaning that held its own value would
    // be a colour decision wearing a role's name — which is what ~170 of the ~190
    // tokens this change deleted actually were.
    //
    // Checked by **identity**, not by value: a copy of `RED` is the right colour
    // with its scheme decision silently removed, and by value the two are
    // indistinguishable.
    const palette = new Set<Colour>(
      Object.values(colours).flatMap((v: unknown): Colour[] => {
        if (!Array.isArray(v)) return [];
        // Either a colour, or one of the sets built out of them.
        return typeof v[0] === "number" ? [v as Colour] : (v as Colour[]);
      }),
    );
    // INK and PAPER are the two exceptions, and they earn it: they are *maximum
    // contrast against the surface*, so they must be adapted by the scheme rather
    // than authored — which is exactly what a named colour may not be.
    const exempt = new Set<Colour>([roles.INK, roles.PAPER]);
    for (const [name, value] of Object.entries(roles)) {
      if (typeof value === "function") continue;
      const colour = value as Colour;
      if (exempt.has(colour)) continue;
      expect(
        palette.has(colour),
        `${name} holds a colour value instead of referencing one from colours.ts`,
      ).toBe(true);
    }
  });

  it("keeps ink and paper adapting", () => {
    // The distinction from BLACK and WHITE only exists in dark mode, so this is
    // where it is pinned: ink is maximum contrast against the surface and must
    // invert, while a piece's black is the piece's identity — inverting it would
    // tell the player the piece is the other colour.
    expect(darkValue(roles.INK)).toBeUndefined();
    expect(darkValue(roles.PAPER)).toBeUndefined();
    expect(darkValue(colours.BLACK)).toEqual([0, 0, 0]);
    expect(darkValue(colours.WHITE)).toEqual([1, 1, 1]);
  });

  it("reports a game's scheme decisions by palette index", () => {
    // The engine hands these to the frontend as plain per-index data, because
    // the tag rides on the colour and would not survive structured clone.
    const pearl = getTsGame("pearl");
    if (!pearl) throw new Error("pearl not registered");
    const decisions = pearl
      .colours(BG)
      .map((c, i) => (c && darkValue(c) ? i : -1))
      .filter((i) => i >= 0);
    // COL_BLACK = 3 and COL_WHITE = 4: the two pearls, which must not invert.
    expect(decisions).toContain(3);
    expect(decisions).toContain(4);
  });

  it("keeps the three hint emphases distinct", () => {
    // These are one meaning at three jobs — the move, the fill behind the digit
    // the move is about, and the evidence the deduction rests on — and seven games
    // put two or three of them on screen at once. Two of the three used to be
    // shades of one blue eight hundredths of a lightness apart; they are a shade
    // and a hue apart now, and this is what says so.
    const d = (a: Colour, b: Colour): number => {
      const plane = (c: OKLCH): [number, number] =>
        isGrayChroma(c[1])
          ? [0, 0]
          : [
              c[1] * Math.cos((c[2] * Math.PI) / 180),
              c[1] * Math.sin((c[2] * Math.PI) / 180),
            ];
      const [al, ...arest] = colourToOKLCH(a);
      const [bl, ...brest] = colourToOKLCH(b);
      const [ax, ay] = plane([al, ...arest] as OKLCH);
      const [bx, by] = plane([bl, ...brest] as OKLCH);
      return Math.hypot(al - bl, ax - bx, ay - by);
    };
    for (const [x, y] of [
      [roles.HINT_ACTION, roles.HINT_FILL],
      [roles.HINT_FILL, roles.HINT_EVIDENCE],
      [roles.HINT_ACTION, roles.HINT_EVIDENCE],
      [roles.HINT_BLACKREF, roles.HINT_WHITEREF],
      [roles.HINT_ACTION, roles.HINT_BLACKREF],
      [roles.HINT_ACTION, roles.HINT_WHITEREF],
    ] as [Colour, Colour][]) {
      expect(d(x, y), `${key(x)} vs ${key(y)}`).toBeGreaterThan(0.12);
    }
    // ...and the two that are fills stay fills: a digit and its pencil marks are
    // drawn on top of them.
    expect(colourToOKLCH(roles.HINT_FILL)[0]).toBeGreaterThan(0.75);
    expect(colourToOKLCH(roles.HINT_EVIDENCE)[0]).toBeGreaterThan(0.75);
  });

  it("keeps every derived role visible against both host backgrounds", () => {
    // The app hands games pure white in dark mode, so a derived role that only
    // separates from a light background is the Spokes COL_DONE bug waiting to
    // happen.
    const distance = (a: Colour, b: Colour) =>
      Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);
    for (const bg of [BG, [1, 1, 1] as Colour]) {
      const { background, highlight } = mkhighlight(bg);
      for (const [name, value] of Object.entries(roles)) {
        if (typeof value !== "function") continue;
        const derived = resolve(value, background, highlight);
        if (!Array.isArray(derived) || derived.length !== 3) continue;
        expect(
          distance(derived, background),
          `${name} against ${bg.join(",")}`,
        ).toBeGreaterThan(0.05);
      }
    }
  });
});

