/**
 * Cross-game guarantees on hint narration *form* (never content).
 *
 * `hint-authoring.md` §2 is a list of narration rules that were, until
 * this file, enforced per-game or by review alone — and narration
 * quality is the broadest hint-defect class in the history (8 games; see
 * `unify-hint-framework` §0.2). Three of its rules are pure form, so
 * they are guarded here for every hinting game at once:
 *
 *  - **Every step shows something** (§5.2): board marks, words, or both.
 *    A step with neither is invisible — a "hint" the player cannot see.
 *  - **Deductive conclusions use the necessity voice** (§2.1): a
 *    deduction is narrated as what *must* / *can't* be, never a bare
 *    state of being. Movement games narrate imperatively instead and are
 *    exempt, as are the candidate games' mechanical populate/cleanup
 *    openers (procedure, not deduction) and each game's declared idioms
 *    (owner-endorsed phrasings whose necessity is carried by the words
 *    themselves — e.g. Filling's "fits exactly into").
 *  - **Narration stays terse** (§2.5): a hard length ceiling. The
 *    longest shipped narration is Undead's 281-char sightline teach; the
 *    cap catches the "rulebook bled into the step" class (Netslide,
 *    `d1f37b8`) without constraining anything that shipped.
 *
 * Form only: no assertion here ever touches *what* a hint says about the
 * board — flattening a good hint to satisfy a guard is the failure mode
 * this change's spec explicitly forbids.
 */
import { describe, expect, it } from "vitest";
import { randomNew } from "../random/index.ts";
import { declaresNoMarks, firstLeaf, HINT_GAMES } from "./testing/hint-games.ts";

const SEEDS = ["hq-a", "hq-b", "hq-c"];

/** Hard ceiling on one step's narration. Longest shipped today: 281. */
const MAX_NARRATION_CHARS = 300;

/** The shared necessity vocabulary a deductive conclusion draws from. */
const NECESSITY =
  /\bmust\b|\bcan(?:no|')t\b|\bcannot\b|\bcan only\b|\bcan never\b|\bhas to\b|\bhave to\b|\bneeds?\b|\brul(?:e|es|ed|ing)\b.{0,40}\bout\b|\bno other\b|\bonly\b|\bnever\b|\bforce[sd]?\b|\bimpossible\b|\bneither\b/i;

/** The candidate-elimination games' mechanical openers — procedure the
 * player is walked through, not a deduction, so no necessity modal. */
const MECHANICAL = /^Start by pencilling|^Now clear the easy ones/;

/** Games whose hints narrate deductions (the necessity-voice rule).
 * Movement/objective games (fifteen, sixteen, netslide, flood, inertia,
 * untangle) narrate moves imperatively and are exempt from that check. */
const DEDUCTIVE = new Set([
  "clusters",
  "crossing",
  "dominosa",
  "filling",
  "keen",
  "lightup",
  "palisade",
  "pattern",
  "range",
  "singles",
  "slant",
  "solo",
  "spokes",
  "towers",
  "undead",
  "unequal",
  "unruly",
]);

/** Owner-endorsed per-game idioms that carry necessity in their own
 * words rather than a modal. Adding here is a deliberate, reviewable
 * act — the list is the legend of endorsed exceptions, not a loophole. */
const IDIOMS: Record<string, RegExp> = {
  // Filling's grouped region step: "The shaded region of N fits exactly
  // into these squares." — the exactness *is* the forcing claim
  // (hint-authoring §5.5; owner-endorsed with the Filling hint).
  filling: /fits exactly into/,
};

describe("hint narration form, cross-game", () => {
  for (const [name, game] of HINT_GAMES) {
    it(`${name}: every step is visible, terse${DEDUCTIVE.has(name) ? ", and necessity-voiced" : ""}`, () => {
      for (const seed of SEEDS) {
        const params = firstLeaf(game.presets());
        const { desc, aux } = game.newDesc(params, randomNew(`${name}-${seed}`));
        const state = game.newState(params, desc);
        const res = game.hint?.(state, aux);
        if (!res?.ok) continue;
        res.steps.forEach((step, i) => {
          const at = `${name}/${seed} step ${i}: "${step.explanation}"`;

          // §5.2 — a step the player cannot see is not a hint.
          expect(
            step.explanation.length > 0 || !declaresNoMarks(step.highlights),
            `${at} — shows nothing: no words, no board marks`,
          ).toBe(true);

          // §2.5 — terse; the rulebook belongs in the help.
          expect(
            step.explanation.length,
            `${at} — narration over ${MAX_NARRATION_CHARS} chars`,
          ).toBeLessThanOrEqual(MAX_NARRATION_CHARS);

          // §2.1 — a deduction concludes in the necessity voice.
          if (DEDUCTIVE.has(name) && !MECHANICAL.test(step.explanation)) {
            expect(
              NECESSITY.test(step.explanation) ||
                (IDIOMS[name]?.test(step.explanation) ?? false),
              `${at} — no necessity modal (and no declared idiom)`,
            ).toBe(true);
          }
        });
      }
    });
  }
});

src/native/engine/hint-resume.test.ts.source:
/**
 * Cross-game guarantee: a hint can always make progress from *any* mid-game
 * position, and following hints solves the board.
 *
 * This is the uniform "solve from the middle" check, applied to every
 * hint-bearing game through the shared `Game` interface. It exists because two
 * games shipped a real bug of the same shape — a hint that gives up (or loops)
 * when asked from a position the player reached by their own play, even though
 * the board is still solvable:
 *
 *  - **Singles** — its deductive `solveSpecific` only ran from an empty board
 *    (upstream's sole use); resumed from the player's marks, the cascade never
 *    propagated from those marks and the solver stalled ("No further move").
 *  - **Untangle** — its aux-walk re-suggested a no-op move forever once a
 *    vertex sat on its (jittering) target pixel.
 *
 * The probe drives the importable scenario both bugs travelled: ask for a fresh
 * hint, apply only its first step, repeat. (In the app, a self-played move
 * drops any stored plan, so the next hint recomputes from the current state —
 * exactly this.) Recomputing every step exercises resumption from many
 * arbitrary partial positions; a correct hint must never give up before solved.
 */
import { describe, expect, it } from "vitest";
import { randomNew } from "../random/index.ts";
import { type AnyGame, firstLeaf, HINT_GAMES } from "./testing/hint-games.ts";

/** Walk a fresh board to solved, recomputing the hint after every move.
 * Returns the move count, or throws with a diagnostic if a hint gives up or
 * the walk fails to converge. */
function solveByHints(game: AnyGame, seed: string): number {
  const params = firstLeaf(game.presets());
  const { desc, aux } = game.newDesc(params, randomNew(seed));
  let state = game.newState(params, desc);
  // Generous cap: far above any honest plan length, so only a genuine
  // loop/non-convergence trips it.
  const cap = 800;
  for (let moves = 0; moves < cap; moves++) {
    if (game.status(state) === "solved") return moves;
    const res = game.hint?.(state, aux);
    if (!res) throw new Error(`${seed}: game has no hint() method`);
    if (!res.ok) {
      throw new Error(`${seed}: hint gave up after ${moves} moves: "${res.error}"`);
    }
    state = game.executeMove(state, res.steps[0].move);
  }
  throw new Error(`${seed}: did not converge within ${cap} moves (loop?)`);
}

const SEEDS = ["hr-a", "hr-b", "hr-c", "hr-d", "hr-e"];

/** A structural key for a game state — typed arrays rendered as plain arrays so
 * two states compare equal iff every field matches. Used to detect a hint step
 * that does nothing (a no-op when reached = an intrinsically stale step). */
function stateKey(s: unknown): string {
  return JSON.stringify(s, (_k, v) =>
    ArrayBuffer.isView(v) && !(v instanceof DataView)
      ? Array.from(v as unknown as ArrayLike<number>)
      : v instanceof Set
        ? [...v]
        : v,
  );
}

describe("a kept hint plan never contains a step that does nothing", () => {
  // The engine guarantees a displayed step is never stale (openspec
  // `fix-stale-hint-step`). The Towers-specific trigger (auto-pencil resolving a
  // later step) has its own end-to-end test; this is the cross-game invariant
  // that catches the *intrinsic* form for every hint game — a plan whose own
  // steps, replayed in order (the exact-follow path), include one that is
  // already a no-op when reached. A clean plan means the game has no latent
  // staleness of this shape.
  for (const [name, game] of HINT_GAMES) {
    it(`${name}: every plan step changes the board when reached`, () => {
      for (const seed of SEEDS) {
        const params = firstLeaf(game.presets());
        const { desc, aux } = game.newDesc(params, randomNew(`noop-${name}-${seed}`));
        let state = game.newState(params, desc);
        const res = game.hint?.(state, aux);
        if (!res?.ok) continue; // refusal (e.g. already solved) — nothing to check
        res.steps.forEach((step, i) => {
          const after = game.executeMove(state, step.move);
          expect(
            stateKey(after) !== stateKey(state),
            `${name}/${seed}: plan step ${i} is a no-op when reached (stale step)`,
          ).toBe(true);
          state = after;
        });
      }
    });
  }
});

describe("requesting a hint never mutates the board", () => {
  // A hint computes and *displays* a plan; it must leave the state untouched —
  // the player applies a step by following it (or pressing Hint a second time).
  // (Owner-reported: a Towers hint appeared to delete a pencil note. The note
  // was intact — a render bug drew the struck candidate invisibly — but the
  // guarantee is worth asserting directly: `hint()` is pure on the state.)
  for (const [name, game] of HINT_GAMES) {
    it(`${name}: hint() leaves the state unchanged`, () => {
      for (const seed of SEEDS) {
        const params = firstLeaf(game.presets());
        const { desc, aux } = game.newDesc(params, randomNew(`pure-${name}-${seed}`));
        const state = game.newState(params, desc);
        const before = stateKey(state);
        game.hint?.(state, aux);
        expect(stateKey(state), `${name}/${seed}: hint() mutated the state`).toBe(
          before,
        );
      }
    });
  }
});

describe("a Latin-family placement never falsely claims a naked single", () => {
  // The shared `latin.ts` solver records naked and hidden singles under one
  // `single` reason; a hint must re-derive which (engine/latin-hint.ts) so it never
  // says "every other number/height has been ruled out in this cell" about a cell
  // that still visibly shows several candidates (owner-reported on Keen). Walk each
  // Latin game and assert the naked-single phrasing only ever appears on a cell
  // whose notes really are down to one candidate.
  const LATIN: [string, AnyGame][] = HINT_GAMES.filter(([name]) =>
    ["towers", "unequal", "keen", "group"].includes(name),
  );
  for (const [name, game] of LATIN) {
    it(`${name}: "ruled out in this cell" only on a genuine naked single`, () => {
      for (const seed of SEEDS) {
        const params = firstLeaf(game.presets());
        const { desc, aux } = game.newDesc(params, randomNew(`naked-${name}-${seed}`));
        let state = game.newState(params, desc);
        // biome-ignore lint/suspicious/noExplicitAny: structural state access.
        const w = (params as any).w ?? (params as any).order;
        for (let moves = 0; moves < 2000 && game.status(state) === "ongoing"; moves++) {
          const res = game.hint?.(state, aux);
          if (!res?.ok) break;
          const step = res.steps[0];
          // biome-ignore lint/suspicious/noExplicitAny: structural move/state access.
          const m = step.move as any;
          if (
            m.type === "set" &&
            !m.pencil &&
            /ruled out in this cell/.test(step.explanation)
          ) {
            // biome-ignore lint/suspicious/noExplicitAny: structural state access.
            const pen = (state as any).pencil[m.y * w + m.x] as number;
            const ncand = Array.from({ length: w }, (_, k) => k + 1).filter(
              (n) => pen & (1 << n),
            ).length;
            expect(
              ncand,
              `${name}/${seed}: naked-single narration on a cell with ${ncand} candidates`,
            ).toBe(1);
          }
          state = game.executeMove(state, step.move);
        }
      }
    });
  }
});

describe("a hint can solve from any mid-game position", () => {
  for (const [name, game] of HINT_GAMES) {
    // Heavy, fixed-seed work (re-solve by following hints move-by-move across
    // every seed). The work per seed is bounded and deterministic; only the
    // wall-clock varies, stretching several-fold under full-suite CPU
    // saturation. That is why nothing here is clock-gated — the assertion is on
    // the *result*. See playbook §5.2.
    it(`${name}: following hints one move at a time always reaches solved`, () => {
      for (const seed of SEEDS) {
        // Throws with a per-seed diagnostic on failure.
        expect(() => solveByHints(game, `${name}-${seed}`)).not.toThrow();
      }
    });
  }
});

src/native/engine/midend-prefs.test.ts.source:
/**
 * Behavioural tests for the engine's per-game preferences hook (the
 * idiomatic-TS realisation of upstream `get_prefs`/`set_prefs`): the
 * declarative `Game.prefs`, the midend's
 * `getPreferencesConfig`/`getPreferences`/`setPreferences`, value
 * coercion, retention across a new game, and the empty result for a
 * game that declares no prefs.
 */

import { describe, expect, it } from "vitest";
import { fakeGame } from "./fake-game.ts";
import type { Game } from "./game.ts";
import { Midend } from "./midend.ts";

/** A ui carrying the two preference shapes: a boolean and a choice. */
interface PrefUi {
  highlight: boolean;
  style: number; // 0 = Circles, 1 = Numbers
  scratch: number; // a non-pref field, reset by newUi each game
}

interface PrefState {
  n: number;
}

/** Smallest game exercising the prefs hook: a boolean pref defaulting
 * ON and a two-way choice pref defaulting to index 0. */
const prefGame: Game<{ n: number }, PrefState, "noop", PrefUi> = {
  id: "__pref__",
  wantsStatusbar: false,
  isTimed: false,
  canSolve: false,
  canFormatAsText: false,
  defaultParams: () => ({ n: 1 }),
  presets: () => ({ title: "root", params: { n: 1 } }),
  encodeParams: (p) => `n${p.n}`,
  decodeParams: (s) => ({ n: Number(s.slice(1)) }),
  validateParams: () => null,
  newDesc: () => ({ desc: "d" }),
  validateDesc: () => null,
  newState: (p) => ({ n: p.n }),
  // Defaults live in newUi (the divergence point, exactly like Untangle):
  // highlight ON, style Circles.
  newUi: () => ({ highlight: true, style: 0, scratch: 0 }),
  interpretMove: () => null,
  executeMove: (s) => s,
  status: () => "ongoing",
  colours: () => [
    [1, 1, 1],
    [0, 0, 0],
  ],
  computeSize: () => ({ w: 10, h: 10 }),
  prefs: [
    {
      kw: "highlight",
      name: "Highlight things",
      type: "boolean",
      get: (ui) => ui.highlight,
      set: (ui, v) => {
        ui.highlight = v;
      },
    },
    {
      kw: "style",
      name: "Display style",
      type: "choices",
      choices: ["Circles", "Numbers"],
      get: (ui) => ui.style,
      set: (ui, v) => {
        ui.style = v;
      },
    },
  ],
};

function start(
  game = prefGame,
): Midend<{ n: number }, PrefState, "noop", PrefUi, unknown> {
  const m = new Midend(game);
  m.setCallbacks(
    () => {},
    () => {},
    () => {},
  );
  m.newGame();
  return m;
}

describe("engine preferences hook", () => {
  it("builds a config description from the declarative prefs", () => {
    const cfg = start().getPreferencesConfig();
    expect(cfg.title).toBe("__pref__");
    expect(cfg.items["highlight"]).toEqual({
      type: "boolean",
      name: "Highlight things",
    });
    expect(cfg.items["style"]).toEqual({
      type: "choices",
      name: "Display style",
      choicenames: ["Circles", "Numbers"],
    });
  });

  it("reports current values read off the live ui (defaults from newUi)", () => {
    expect(start().getPreferences()).toEqual({ highlight: true, style: 0 });
  });

  it("round-trips set → get for both item types", () => {
    const m = start();
    expect(m.setPreferences({ highlight: false, style: 1 })).toBeUndefined();
    expect(m.getPreferences()).toEqual({ highlight: false, style: 1 });
  });

  it("applies only the keys present, leaving others unchanged", () => {
    const m = start();
    m.setPreferences({ style: 1 });
    expect(m.getPreferences()).toEqual({ highlight: true, style: 1 });
  });

  it("coerces loosely-typed values (DB JSON / legacy)", () => {
    const m = start();
    // A string index for a choice, a string boolean — as a permissive
    // store might hand back.
    m.setPreferences({ highlight: "true", style: "1" });
    expect(m.getPreferences()).toEqual({ highlight: true, style: 1 });
    m.setPreferences({ highlight: false });
    expect(m.getPreferences()).toEqual({ highlight: false, style: 1 });
  });

  it("repaints when a preference changes", () => {
    let redraws = 0;
    const m = new Midend(prefGame);
    m.setCallbacks(
      () => {},
      () => {},
      () => {
        redraws++;
      },
    );
    m.newGame();
    const before = redraws;
    m.setPreferences({ highlight: false });
    expect(redraws).toBeGreaterThan(before);
  });

  it("retains a preference across a new game (ui is recreated by newUi)", () => {
    const m = start();
    m.setPreferences({ highlight: false, style: 1 });
    m.newGame(); // recreates ui via newUi (defaults highlight=true, style=0)
    expect(m.getPreferences()).toEqual({ highlight: false, style: 1 });
  });

  it("reports an empty set for a game that declares no prefs", () => {
    const m = new Midend(fakeGame);
    m.setCallbacks(
      () => {},
      () => {},
      () => {},
    );
    m.newGame();
    expect(m.getPreferencesConfig().items).toEqual({});
    expect(m.getPreferences()).toEqual({});
    expect(m.setPreferences({ anything: true })).toBeUndefined();
  });

  it("stores prefs set before a game starts and applies them on start", () => {
    const m = new Midend(prefGame);
    m.setCallbacks(
      () => {},
      () => {},
      () => {},
    );
    // No game yet: setPreferences stores but cannot apply (no ui).
    expect(m.getPreferences()).toEqual({});
    m.setPreferences({ highlight: false, style: 1 });
    m.newGame();
    expect(m.getPreferences()).toEqual({ highlight: false, style: 1 });
  });
});

