/**
 * Group behavioural tests (tier 1, pure logic): params codec, generation +
 * unique-solvability at target difficulty, desc round-trip, move transitions
 * (multifill, reorder, divider), completion, and findMistakes. The byte-match
 * differential against the C reference lives in `group-differential.test.ts`.
 */

import { describe, expect, it } from "vitest";
import { DIFF_AMBIGUOUS, DIFF_IMPOSSIBLE } from "../../engine/latin.ts";
import { randomNew } from "../../random/index.ts";
import { newGameDesc } from "./generator.ts";
import { groupGame } from "./index.ts";
import { colours, newDrawState, redraw, setTileSize } from "./render.ts";
import { solveGroup } from "./solver.ts";
import {
  cloneState,
  DIFF_HARD,
  DIFF_NORMAL,
  DIFF_UNREASONABLE,
  decodeParams,
  encodeGrid,
  encodeParams,
  type GroupParams,
  type GroupState,
  newState,
  newUi,
  PRESETS,
  validateDesc,
  validateParams,
} from "./state.ts";

const P = (w: number, diff: number, id: boolean): GroupParams => ({ w, diff, id });

/**
 * The optional `Game` hooks Group implements, narrowed once. Asserting them
 * here beats a `!` at each call site (a compile-time claim nothing checks) and
 * beats `?.` (which would silently make the assertion vacuous if a hook were
 * ever dropped): if one goes missing, this fails immediately and says which.
 * None of the three reads `this`, so calling them unbound is safe.
 */
const { solve, flashLength, findMistakes } = groupGame;
if (!solve || !flashLength || !findMistakes) {
  throw new Error("group: expected the solve / flashLength / findMistakes hooks");
}

/** A completed grid is a valid group table iff Latin + associative. */
function isValidGroupTable(grid: Uint8Array, w: number): boolean {
  // Latin: each element once per row and column.
  for (let y = 0; y < w; y++) {
    const seen = new Set<number>();
    for (let x = 0; x < w; x++) {
      const v = grid[y * w + x];
      if (v < 1 || v > w || seen.has(v)) return false;
      seen.add(v);
    }
  }
  for (let x = 0; x < w; x++) {
    const seen = new Set<number>();
    for (let y = 0; y < w; y++) seen.add(grid[y * w + x]);
    if (seen.size !== w) return false;
  }
  // Associative: (ab)c == a(bc).
  const g = (aa: number, bb: number) => grid[aa * w + bb] - 1; // 0-based product
  for (let i = 0; i < w; i++)
    for (let j = 0; j < w; j++)
      for (let k = 0; k < w; k++) if (g(g(i, j), k) !== g(i, g(j, k))) return false;
  return true;
}

describe("params codec", () => {
  it("round-trips every preset through encode/decode", () => {
    for (const p of PRESETS) {
      const enc = encodeParams(p, true);
      const dec = decodeParams(enc);
      expect(dec.w).toBe(p.w);
      expect(dec.diff).toBe(p.diff);
      expect(dec.id).toBe(p.id);
    }
  });

  it("encodes identity-hidden and difficulty faithfully", () => {
    expect(encodeParams(P(8, DIFF_HARD, false), true)).toBe("8dhi");
    expect(encodeParams(P(6, DIFF_NORMAL, true), true)).toBe("6dn");
    expect(encodeParams(P(6, DIFF_NORMAL, true), false)).toBe("6");
  });

  it("rejects the two impossible identity-hidden combinations", () => {
    expect(validateParams(P(3, DIFF_NORMAL, false), true)).toMatch(/3x3/);
    expect(validateParams(P(6, 0, false), true)).toMatch(/Trivial/);
    expect(validateParams(P(6, DIFF_NORMAL, false), true)).toBeNull();
    expect(validateParams(P(2, DIFF_NORMAL, true), true)).toMatch(/between 3 and 26/);
  });
});

describe("generation", () => {
  // A small, fast matrix across sizes / difficulties / both identity modes.
  const cases: GroupParams[] = [
    P(4, DIFF_NORMAL, true),
    P(6, DIFF_NORMAL, true),
    P(6, DIFF_NORMAL, false),
    P(6, DIFF_HARD, false),
    P(8, DIFF_HARD, true),
    P(8, DIFF_HARD, false),
  ];

  for (const p of cases) {
    it(`produces a uniquely-solvable board at ${p.w}d${p.diff}${p.id ? "" : "i"}`, () => {
      const rng = randomNew(`group-${p.w}-${p.diff}-${p.id}`);
      const { desc, aux } = newGameDesc(p, rng);

      // Desc validates and round-trips through the codec.
      expect(validateDesc(p, desc)).toBeNull();
      const state = newState(p, desc);
      expect(encodeGrid(state.grid, p.w * p.w)).toBe(desc);

      // The generated board is uniquely solvable at the (possibly downgraded)
      // difficulty, and the solution is a genuine group table.
      const soln = state.grid.slice();
      const ret = solveGroup(soln, p.w, DIFF_UNREASONABLE);
      expect(ret).not.toBe(DIFF_IMPOSSIBLE);
      expect(ret).not.toBe(DIFF_AMBIGUOUS);
      expect(isValidGroupTable(soln, p.w)).toBe(true);

      // aux encodes that same solution.
      expect(aux[0]).toBe("S");
      expect(aux.length).toBe(p.w * p.w + 1);
    });
  }
});

describe("moves and completion", () => {
  function freshGame(p: GroupParams): { state: GroupState; aux: string } {
    const rng = randomNew(`play-${p.w}-${p.diff}-${p.id}`);
    const { desc, aux } = newGameDesc(p, rng);
    return { state: newState(p, desc), aux };
  }

  it("solve() completes the board to a valid group table", () => {
    const p = P(6, DIFF_NORMAL, true);
    const { state, aux } = freshGame(p);
    const res = solve(state, state, aux);
    expect(res.ok).toBe(true);
    if (!res.ok) return;
    const done = groupGame.executeMove(state, res.move);
    expect(done.completed).toBe(true);
    expect(done.cheated).toBe(true); // solved via the button
    expect(isValidGroupTable(done.grid, p.w)).toBe(true);
    expect(groupGame.status(done)).toBe("solved");
  });

  it("the completion flash fires on a genuine (non-cheated) completion", () => {
    const p = P(6, DIFF_NORMAL, true);
    const { state, aux } = freshGame(p);
    const res = solve(state, state, aux);
    if (!res.ok) throw new Error("unsolvable");
    const solved = groupGame.executeMove(state, res.move);
    const before = cloneState(solved);
    before.completed = false;
    before.cheated = false;
    const after = cloneState(solved);
    after.cheated = false; // as if the player placed the last cell themselves
    expect(flashLength(before, after, +1, newUi(state))).toBeGreaterThan(0);
  });

  it("a multifill set writes every listed cell", () => {
    const p = P(6, DIFF_NORMAL, true);
    const { state } = freshGame(p);
    // Find three empty non-immutable cells to fill.
    const cells: { x: number; y: number }[] = [];
    for (let y = 0; y < p.w && cells.length < 3; y++)
      for (let x = 0; x < p.w && cells.length < 3; x++)
        if (!state.immutable[y * p.w + x] && !state.grid[y * p.w + x])
          cells.push({ x, y });
    const next = groupGame.executeMove(state, { type: "set", cells, n: 1 });
    for (const c of cells) expect(next.grid[c.y * p.w + c.x]).toBe(1);
  });

  it("reorder moves an element and clears an obsoleted divider", () => {
    const p = P(6, DIFF_NORMAL, true);
    const { state } = freshGame(p);
    // Put a divider to the right of element 0 (currently followed by element 1).
    const withDiv = groupGame.executeMove(state, { type: "divider", i: 0, j: 1 });
    expect(withDiv.dividers[0]).toBe(1);
    // Move element 3 to position 1, splitting 0 and 1 apart.
    const reordered = groupGame.executeMove(withDiv, {
      type: "reorder",
      num: 3,
      pos: 1,
    });
    expect(reordered.sequence[1]).toBe(3);
    // 0 is no longer immediately followed by 1, so its divider is cleared.
    expect(reordered.dividers[0]).toBe(-1);
    // Every element still present exactly once.
    expect([...reordered.sequence].sort((a, b) => a - b)).toEqual(
      Array.from({ length: p.w }, (_, i) => i),
    );
  });

  it("divider toggles off when reapplied", () => {
    const p = P(6, DIFF_NORMAL, true);
    const { state } = freshGame(p);
    const on = groupGame.executeMove(state, { type: "divider", i: 2, j: 3 });
    expect(on.dividers[2]).toBe(3);
    const off = groupGame.executeMove(on, { type: "divider", i: 2, j: 3 });
    expect(off.dividers[2]).toBe(-1);
  });

  it("rejects setting an immutable cell to a different value", () => {
    const p = P(6, DIFF_NORMAL, true);
    const { state } = freshGame(p);
    const imm = state.grid.findIndex((v, i) => state.immutable[i] !== 0 && v !== 0);
    const x = imm % p.w;
    const y = (imm / p.w) | 0;
    const wrong = (state.grid[imm] % p.w) + 1;
    expect(() =>
      groupGame.executeMove(state, { type: "set", cells: [{ x, y }], n: wrong }),
    ).toThrow();
  });
});

describe("findMistakes", () => {
  it("flags a wrong entry and clears once corrected", () => {
    const p = P(6, DIFF_NORMAL, true);
    const rng = randomNew("mistake");
    const { desc, aux } = newGameDesc(p, rng);
    const state = newState(p, desc);

    // Solve to the unique solution, then corrupt one non-immutable cell.
    const res = solve(state, state, aux);
    if (!res.ok) throw new Error("unsolvable");
    const solved = groupGame.executeMove(state, res.move);
    expect(findMistakes(solved)).toHaveLength(0);

    const idx = solved.grid.findIndex((_, i) => !state.immutable[i]);
    const bad = cloneState(solved);
    bad.grid[idx] = (bad.grid[idx] % p.w) + 1;
    const mistakes = findMistakes(bad);
    expect(mistakes.length).toBeGreaterThan(0);
    expect(mistakes.some((m) => m.y * p.w + m.x === idx)).toBe(true);
  });
});

describe("rendering smoke", () => {
  it("draws without throwing and the palette has all colours", () => {
    const p = P(6, DIFF_NORMAL, true);
    const rng = randomNew("render");
    const { desc } = newGameDesc(p, rng);
    const state = newState(p, desc);
    const pal = colours([0.9, 0.9, 0.9]);
    expect(pal).toHaveLength(10); // 8 upstream + COL_HINT / COL_HINT_CELL

    const ds = newDrawState(state);
    setTileSize(ds, 48);
    const ops: string[] = [];
    // Minimal GameDrawing double: record op names, ignore geometry.
    const dr = {
      drawRect: () => ops.push("rect"),
      drawLine: () => ops.push("line"),
      drawPolygon: () => ops.push("poly"),
      drawCircle: () => ops.push("circle"),
      drawText: () => ops.push("text"),
      clip: () => {},
      unclip: () => {},
      drawUpdate: () => {},
    } as unknown as Parameters<typeof redraw>[0];
    redraw(dr, ds, null, state, 0, newUi(state), 0, 0);
    expect(ops.length).toBeGreaterThan(0);
  });
});

src/native/games/keen/keen.test.ts.source:
/**
 * Behavioural tests for the Keen (KenKen) port.
 *
 * Tier 1 — pure logic: params/desc codecs, generator quality (seeded; solvable,
 * unique, correctly graded, valid cage areas), the cage solver, move
 * transitions, completion + flash, findMistakes, and Solve through a real
 * Midend (the aux path). Tier 2.5 — render scenarios: the initial frame (cage
 * clue text + grid backing), the pencil-mode indicator, and the Check & Save
 * mistake overlay, each with targeted op assertions plus a snapshot.
 */
import { describe, expect, it } from "vitest";
import { Midend } from "../../engine/index.ts";
import { RecordingDrawing } from "../../engine/testing/recording-drawing.ts";
import {
  DEFAULT_BACKGROUND,
  renderScenario,
} from "../../engine/testing/render-scenario.ts";
import { randomNew } from "../../random/index.ts";
import { newKeenDesc } from "./generator.ts";
import { keenGame } from "./index.ts";
import {
  COL_ERROR,
  COL_PENCIL_BODY,
  newDrawState,
  redraw,
  setTileSize,
} from "./render.ts";
import { solveKeen } from "./solver.ts";
import {
  C_DIV,
  C_SUB,
  CMASK,
  cloneState,
  clueOp,
  decodeParams,
  diffToLevel,
  encodeParams,
  type KeenParams,
  type KeenState,
  newState,
  newUi,
  validateDesc,
  validateParams,
} from "./state.ts";

function gen(p: KeenParams, seed: string) {
  const { desc, aux } = newKeenDesc(p, randomNew(seed));
  return { p, desc, aux, st: newState(p, desc) };
}

function solutionGrid(st: KeenState): number[] {
  const r = keenGame.solve?.(st, st);
  if (!r?.ok || r.move.type !== "solve") throw new Error("solve failed");
  return r.move.grid;
}

// A deterministic descriptive id from the frozen C fixture (4×4 Easy).
const D4 = "aa_a_aa_ba_5a,d2s1a9m4d2m6s2";
const P4: KeenParams = { w: 4, diff: "easy", multiplicationOnly: false };

// --- tier 1: params --------------------------------------------------------

describe("keen params codec", () => {
  it("round-trips full and short forms", () => {
    expect(encodeParams({ w: 6, diff: "hard", multiplicationOnly: false }, true)).toBe(
      "6dh",
    );
    expect(encodeParams({ w: 6, diff: "hard", multiplicationOnly: false }, false)).toBe(
      "6",
    );
    expect(encodeParams({ w: 5, diff: "easy", multiplicationOnly: true }, true)).toBe(
      "5dem",
    );
    expect(decodeParams("6dh")).toEqual({
      w: 6,
      diff: "hard",
      multiplicationOnly: false,
    });
    expect(decodeParams("5dem")).toEqual({
      w: 5,
      diff: "easy",
      multiplicationOnly: true,
    });
    expect(decodeParams("9dn")).toEqual({
      w: 9,
      diff: "normal",
      multiplicationOnly: false,
    });
  });

  it("rejects invalid params", () => {
    expect(
      validateParams({ w: 2, diff: "easy", multiplicationOnly: false }, true),
    ).not.toBeNull();
    expect(
      validateParams({ w: 10, diff: "easy", multiplicationOnly: false }, true),
    ).not.toBeNull();
    expect(
      validateParams({ w: 6, diff: "normal", multiplicationOnly: false }, true),
    ).toBeNull();
  });
});

// --- tier 1: desc codec ----------------------------------------------------

describe("keen desc codec", () => {
  it("accepts a valid desc and decodes a blank starting grid", () => {
    expect(validateDesc(P4, D4)).toBeNull();
    const st = newState(P4, D4);
    expect(st.grid.every((v) => v === 0)).toBe(true);
    expect(st.pencil.every((v) => v === 0)).toBe(true);
    // The fixture has a div, a sub, adds and muls — every cage carries a clue.
    let cages = 0;
    for (let i = 0; i < 16; i++) if (st.clues.minimal[i] === i) cages++;
    let clued = 0;
    for (let i = 0; i < 16; i++) if (st.clues.clues[i] !== 0) clued++;
    expect(clued).toBe(cages);
  });

  it("rejects malformed descs", () => {
    expect(validateDesc(P4, "!!!,a1")).not.toBeNull(); // bad block structure
    expect(validateDesc(P4, D4.replace(",d2s1a9m4d2m6s2", ",a9"))).not.toBeNull(); // too few clues
    // A subtraction clue on a non-domino cage: take a desc whose first cage is
    // large and tag it 's'.
    expect(
      validateDesc({ w: 3, diff: "easy", multiplicationOnly: false }, "z3,s9"),
    ).not.toBeNull();
  });
});

// --- tier 1: generator -----------------------------------------------------

describe("keen generator", () => {
  for (const p of [
    { w: 4, diff: "easy", multiplicationOnly: false },
    { w: 5, diff: "easy", multiplicationOnly: true },
    { w: 6, diff: "normal", multiplicationOnly: false },
    { w: 6, diff: "hard", multiplicationOnly: false },
  ] as KeenParams[]) {
    it(`emits a unique, exactly-graded board for ${p.w}d${p.diff}${p.multiplicationOnly ? "m" : ""}`, () => {
      const { st } = gen(p, `keen-gen-${p.w}-${p.diff}-${p.multiplicationOnly}`);
      const lvl = diffToLevel(p.diff);
      // Unique + exactly this difficulty.
      const soln = new Uint8Array(p.w * p.w);
      expect(solveKeen(p.w, st.clues, soln, lvl)).toBe(lvl);
      if (lvl > 0) {
        const easier = new Uint8Array(p.w * p.w);
        expect(solveKeen(p.w, st.clues, easier, lvl - 1)).toBeGreaterThan(lvl - 1);
      }
      // Valid cage areas: 1..6, and every sub/div cage is a domino.
      for (let i = 0; i < p.w * p.w; i++) {
        if (st.clues.minimal[i] !== i) continue;
        const size = st.clues.dsf.size(i);
        expect(size).toBeGreaterThanOrEqual(1);
        expect(size).toBeLessThanOrEqual(6);
        const op = clueOp(st.clues.clues[i]);
        if (op === C_SUB || op === C_DIV) expect(size).toBe(2);
        if (p.multiplicationOnly) expect(st.clues.clues[i] & CMASK).toBe(0x20000000);
      }
    });
  }
});

// --- tier 1: solver --------------------------------------------------------

describe("keen solver", () => {
  it("solves a known board to its unique solution", () => {
    const st = newState(P4, D4);
    const soln = new Uint8Array(16);
    expect(solveKeen(4, st.clues, soln, 0)).toBe(0);
    // Result is a valid Latin square.
    for (let y = 0; y < 4; y++) {
      const row = new Set<number>();
      const col = new Set<number>();
      for (let x = 0; x < 4; x++) {
        row.add(soln[y * 4 + x]);
        col.add(soln[x * 4 + y]);
      }
      expect(row.size).toBe(4);
      expect(col.size).toBe(4);
    }
  });
});

// --- tier 1: moves ---------------------------------------------------------

describe("keen moves", () => {
  it("places, pencils, fills-all and strikes without mutating the input", () => {
    const st = newState(P4, D4);
    const placed = keenGame.executeMove(st, {
      type: "set",
      x: 1,
      y: 2,
      n: 3,
      pencil: false,
    });
    expect(placed.grid[2 * 4 + 1]).toBe(3);
    expect(st.grid[2 * 4 + 1]).toBe(0); // original untouched

    const pen = keenGame.executeMove(st, {
      type: "set",
      x: 0,
      y: 0,
      n: 2,
      pencil: true,
    });
    expect(pen.pencil[0]).toBe(1 << 2);

    const all = keenGame.executeMove(st, { type: "pencilAll" });
    expect(all.pencil[0]).toBe((1 << 5) - (1 << 1)); // bits 1..4

    const struck = keenGame.executeMove(all, {
      type: "pencilStrike",
      marks: [{ x: 0, y: 0, n: 2 }],
    });
    expect(struck.pencil[0] & (1 << 2)).toBe(0);
  });

  it("auto-pencil strikes the placed digit from its row and column", () => {
    const all = keenGame.executeMove(newState(P4, D4), { type: "pencilAll" });
    const next = keenGame.executeMove(all, {
      type: "set",
      x: 1,
      y: 1,
      n: 3,
      pencil: false,
      autoElim: true,
    });
    // 3 struck from the rest of row 1 and column 1.
    for (let k = 0; k < 4; k++) {
      if (k !== 1) {
        expect(next.pencil[1 * 4 + k] & (1 << 3)).toBe(0);
        expect(next.pencil[k * 4 + 1] & (1 << 3)).toBe(0);
      }
    }
  });

  it("completes and flashes when the last correct digit lands (not on Solve)", () => {
    const st = newState(P4, D4);
    const sol = solutionGrid(st);
    let cur = st;
    for (let i = 0; i < 15; i++)
      cur = keenGame.executeMove(cur, {
        type: "set",
        x: i % 4,
        y: (i / 4) | 0,
        n: sol[i],
        pencil: false,
      });
    expect(cur.completed).toBe(false);
    const before = cur;
    cur = keenGame.executeMove(cur, {
      type: "set",
      x: 3,
      y: 3,
      n: sol[15],
      pencil: false,
    });
    expect(cur.completed).toBe(true);
    expect(cur.cheated).toBe(false);
    expect(keenGame.flashLength?.(before, cur, 1, newUi(st))).toBeGreaterThan(0);
  });

  it("Solve completes the board but marks it cheated (no flash)", () => {
    const st = newState(P4, D4);
    const r = keenGame.solve?.(st, st);
    if (!r?.ok) throw new Error("solve failed");
    const done = keenGame.executeMove(st, r.move);
    expect(done.completed).toBe(true);
    expect(done.cheated).toBe(true);
    expect(keenGame.flashLength?.(st, done, 1, newUi(st))).toBe(0);
  });
});

// --- tier 1: findMistakes --------------------------------------------------

describe("keen findMistakes", () => {
  it("flags a wrong digit and a note that excludes the solution", () => {
    const st = newState(P4, D4);
    const sol = solutionGrid(st);
    const wrong = (sol[0] % 4) + 1;
    const bad = keenGame.executeMove(st, {
      type: "set",
      x: 0,
      y: 0,
      n: wrong,
      pencil: false,
    });
    const ms = keenGame.findMistakes?.(bad) ?? [];
    expect(ms).toContainEqual({ kind: "cell", x: 0, y: 0 });

    // A note that has crossed out the correct value (kind "note").
    const all = keenGame.executeMove(st, { type: "pencilAll" });
    const struck = keenGame.executeMove(all, {
      type: "pencilStrike",
      marks: [{ x: 1, y: 1, n: sol[1 * 4 + 1] }],
    });
    expect(keenGame.findMistakes?.(struck) ?? []).toContainEqual({
      kind: "note",
      x: 1,
      y: 1,
    });
  });

  it("ignores a cell whose notes merely carry extra candidates", () => {
    const all = keenGame.executeMove(newState(P4, D4), { type: "pencilAll" });
    // Every candidate pencilled in (includes the solution) — not a mistake.
    expect((keenGame.findMistakes?.(all) ?? []).length).toBe(0);
  });
});

// --- tier 1: Solve via a real Midend (aux path) ----------------------------

describe("keen Solve via Midend", () => {
  it("solves a freshly generated board and reports solved", () => {
    const me = new Midend(keenGame);
    expect(me.newGameFromId("6dn#keen-solve")).toBeUndefined();
    expect(me.solve()).toBeUndefined();
    const solved = (me as unknown as { state: KeenState }).state;
    expect(solved.completed).toBe(true);
    expect(keenGame.status(solved)).toBe("solved");
  });

  it("save round-trips a played board", () => {
    const me = new Midend(keenGame);
    expect(me.newGameFromId(`4de:${D4}`)).toBeUndefined();
    me.playMoves([{ type: "set", x: 0, y: 0, n: 1, pencil: false }]);
    const saved = me.saveGame();
    const me2 = new Midend(keenGame);
    expect(me2.loadGame(saved)).toBeUndefined();
    expect((me2 as unknown as { state: KeenState }).state.grid[0]).toBe(1);
  });
});

// cloneState sanity (immutable clues shared, mutable arrays copied).
describe("keen cloneState", () => {
  it("shares clues by reference and copies the working arrays", () => {
    const st = newState(P4, D4);
    const c = cloneState(st);
    expect(c.clues).toBe(st.clues);
    c.grid[0] = 9;
    expect(st.grid[0]).toBe(0);
  });
});

// --- tier 2.5: render scenarios --------------------------------------------

const RENDER_ID = `4de:${D4}`;

describe("keen render", () => {
  it("draws the initial frame with cage clues and the grid backing", () => {
    const { recording } = renderScenario({ game: keenGame, id: RENDER_ID });
    // Cage clue text is drawn (numbers + operation symbols).
    expect(recording.ops.some((o) => o.op === "text")).toBe(true);
    // Filled rects (the grid backing + cell backgrounds).
    expect(recording.ops.some((o) => o.op === "rect")).toBe(true);
    expect(recording.ops).toMatchSnapshot();
  });

  it("shows the pencil-mode indicator glyph when sticky pencil is on", () => {
    const palette = keenGame.colours(DEFAULT_BACKGROUND);
    const ts = keenGame.preferredTileSize ?? 48;
    const render = (hpencil: boolean): RecordingDrawing => {
      const st = newState(P4, D4);
      const ui = newUi(st);
      ui.hpencil = hpencil;
      const ds = newDrawState(st);
      setTileSize(ds, ts);
      const dr = new RecordingDrawing(palette);
      redraw(dr, ds, null, st, 1, ui, 0, 0);
      return dr;
    };
    const glyph = (r: RecordingDrawing) =>
      r.ops.some((o) => o.op === "polygon" && o.fill === COL_PENCIL_BODY);
    expect(glyph(render(true))).toBe(true);
    expect(glyph(render(false))).toBe(false);
  });

  it("Check & Save highlights a mistake even when the cell was already drawn", () => {
    // Regression (playbook §3.2): the mistake overlay isn't part of a cell's
    // tile value, so it must be in the diff cache key — otherwise findMistakes()
    // on an already-painted cell repaints nothing and the red never shows.
    const me = new Midend(keenGame);
    expect(me.newGameFromId(RENDER_ID)).toBeUndefined();
    const st = (me as unknown as { state: KeenState }).state;
    const sol = solutionGrid(st);
    const wrong = (sol[0] % 4) + 1;
    me.playMoves([{ type: "set", x: 0, y: 0, n: wrong, pencil: false }]);

    const palette = keenGame.colours(DEFAULT_BACKGROUND);
    me.redraw(new RecordingDrawing(palette)); // first paint: wrong digit, no overlay
    expect(me.findMistakes()).toBeGreaterThan(0);
    const after = new RecordingDrawing(palette);
    me.redraw(after);
    expect(after.ops.some((o) => o.op === "line" && o.colour === COL_ERROR)).toBe(true);
  });
});

describe("adaptive mark-all ('M')", () => {
  const W = 4;
  const press = (st: KeenState) =>
    keenGame.interpretMove(st, newUi(st), null, { x: 0, y: 0 }, 77);

  it("fills note-less cells on the first press, then cleans obvious dups, then no-ops", () => {
    // First press on a fresh board: empty cells are note-less → fill all.
    const fresh = newState(P4, D4);
    expect(press(fresh)).toEqual({ type: "pencilAll" });

    // Fully-noted board with a placed 1 at (0,0): the press cleans the obvious
    // row/column duplicates of the 1, and is a single atomic pencilStrike.
    const noted = cloneState(fresh);
    const all = (1 << (W + 1)) - (1 << 1);
    for (let i = 0; i < W * W; i++) noted.pencil[i] = all;
    noted.grid[0] = 1;
    noted.pencil[0] = 0;
    const move = press(noted);
    if (typeof move !== "object" || move === null || move.type !== "pencilStrike")
      throw new Error("expected pencilStrike");
    const struck = new Set(move.marks.map((m) => `${m.x},${m.y},${m.n}`));
    // Row 0 (cells x=1,2,3) and column 0 (cells y=1,2,3) lose their 1.
    expect(struck).toEqual(
      new Set(["1,0,1", "2,0,1", "3,0,1", "0,1,1", "0,2,1", "0,3,1"]),
    );

    // Apply it and press again: nothing left to fill or strike → a true no-op.
    const cleaned = keenGame.executeMove(noted, move);
    expect(press(cleaned)).toBeNull();
  });

  it("never strikes a candidate that is only a cage-mate (cages are not uniqueness regions)", () => {
    // Place a 1 at (0,0); note 1 at (2,2), which shares neither row nor column
    // with (0,0). Even if (0,0) and (2,2) were cage-mates, a Keen cage permits a
    // legal repeat, so the 1 at (2,2) must survive the cleanup (design D3).
    const st = cloneState(newState(P4, D4));
    const all = (1 << (W + 1)) - (1 << 1);
    for (let i = 0; i < W * W; i++) st.pencil[i] = all;
    st.grid[0] = 1;
    st.pencil[0] = 0;
    const move = press(st);
    if (typeof move !== "object" || move === null || move.type !== "pencilStrike")
      throw new Error("expected pencilStrike");
    const struck = new Set(move.marks.map((m) => `${m.x},${m.y},${m.n}`));
    expect(struck.has("2,2,1")).toBe(false); // not in row 0 or column 0 → kept
  });
});

describe("on-screen keys (requestKeys)", () => {
  const keysFor = (w: number) =>
    keenGame.requestKeys?.({ ...keenGame.defaultParams(), w });

  it("offers digits 1..w plus clear at two widths", () => {
    expect(keysFor(4)).toEqual([
      ..."1234".split("").map((d) => ({ button: d.charCodeAt(0), label: d })),
      { button: 8, label: "Clear" },
    ]);
    expect(keysFor(6)).toEqual([
      ..."123456".split("").map((d) => ({ button: d.charCodeAt(0), label: d })),
      { button: 8, label: "Clear" },
    ]);
  });
});

src/native/games/loopy/loopy-render-scen.source:
/**
 * Tier-2.5 render scenarios for Loopy: drive a real Midend to a target frame
 * and capture `redraw`.
 *
 * Loopy's renderer has no per-tiling code — every geometric difference comes
 * out of `grid.ts` — so the risk it carries is not "did the hexagon branch get
 * written", it is "does the one branch survive contact with eighteen very
 * different geometries". Hence the sweep: nine tilings, including both
 * aperiodic families, each asserted against the invariants that must hold for
 * *any* tiling (one circle per dot, one line per edge, one digit per clued
 * face, every digit on the canvas). These tilings have never been rendered
 * anywhere before, so this is their first check rather than a regression net.
 *
 * The rest are the state-dependent colourings the sweep's opener frames cannot
 * reach: line state, the faint-line preference, vertex errors, the
 * `exactlyOneLoop` clue rule, and the clue-position cache `setTileSize`
 * invalidates.
 */
import { describe, expect, it } from "vitest";
import { gridFindIncentre } from "../../engine/grid.ts";
import { Midend } from "../../engine/midend.ts";
import { RecordingDrawing } from "../../engine/testing/recording-drawing.ts";
import {
  DEFAULT_BACKGROUND,
  renderScenario,
} from "../../engine/testing/render-scenario.ts";
import { randomNew } from "../../random/index.ts";
import { newDesc } from "./generator.ts";
import { type LoopyMove, loopyGame } from "./index.ts";
import { DIFF_EASY, encodeParams, type LoopyParams } from "./params.ts";
import {
  border,
  COL_BACKGROUND,
  COL_FAINT,
  COL_FOREGROUND,
  COL_LINEUNKNOWN,
  COL_MISTAKE,
  computeSize,
  PREFERRED_TILE_SIZE,
} from "./render.ts";
import { LINE_NO, LINE_YES, type LoopyState, newState } from "./state.ts";

/**
 * A fixed board for a tiling. The desc is generated from a fixed seed rather
 * than hardcoded, so it stays a *real* board for its tiling; a generator change
 * re-resolves it and churns the snapshot, which is the healthy signal.
 */
function board(
  name: string,
  type: number,
  w: number,
  h: number,
): { p: LoopyParams; id: string; state: LoopyState } {
  const p: LoopyParams = { w, h, diff: DIFF_EASY, type };
  const { desc } = newDesc(p, randomNew(`loopy-render-${name}`));
  return {
    p,
    id: `${encodeParams(p, true)}:${desc}`,
    state: newState(p, desc),
  };
}

/** Mirror of `render.ts`'s `toScreen` (not exported), so a test can say where
 * a given dot or incentre *should* land rather than only how many landed. */
function screenPos(
  state: LoopyState,
  ts: number,
  gx: number,
  gy: number,
): [number, number] {
  const g = state.grid;
  const b = border(ts);
  return [
    Math.round(((gx - g.lowestX) * ts) / g.tileSize) + b,
    Math.round(((gy - g.lowestY) * ts) / g.tileSize) + b,
  ];
}

const setEdges = (edges: readonly number[], state: 0 | 2): LoopyMove => ({
  kind: "set",
  ops: edges.map((edge) => ({ edge, state })),
});

// The tilings under test. Squares is the baseline; triangular / honeycomb /
// great-hexagonal are the hex family (three quite different vertex degrees);
// dodecagonal brings 12-sided faces and so double-digit clues; and the last
// four are both aperiodic families, whose grids are *described* rather than
// computed and whose faces are the least regular anything here will ever draw.
const TILINGS: readonly [string, number, number, number][] = [
  ["squares", 0, 5, 5],
  ["triangular", 1, 5, 5],
  ["honeycomb", 2, 5, 5],
  ["great-hexagonal", 5, 4, 3],
  ["dodecagonal", 9, 3, 3],
  ["penrose-kite-dart", 11, 6, 6],
  ["penrose-rhombs", 12, 6, 6],
  ["hats", 16, 6, 6],
  ["spectres", 17, 6, 6],
];

describe("Loopy render scenarios: every tiling draws its whole grid", () => {
  for (const [name, type, w, h] of TILINGS) {
    it(name, () => {
      const { id, state } = board(name, type, w, h);
      const g = state.grid;
      const { recording, size } = renderScenario({ game: loopyGame, id });
      const ops = recording.ops;

      // The game paints its own background first; the engine emits no pixels
      // of its own, so a missing opener rect means the board is drawn over
      // whatever was there before (`fix-flip-canvas-reshape`).
      expect(ops[0]).toMatchObject({ op: "rect", x: 0, y: 0, colour: COL_BACKGROUND });

      // Nothing may be dropped or duplicated in the translation from grid to
      // screen: one dot is one circle, one edge is one line. A tiling whose
      // geometry confused the renderer would show up as a count mismatch long
      // before anyone eyeballed the frame.
      const circles = ops.filter((o) => o.op === "circle");
      expect(circles.length).toBe(g.numDots);
      expect(circles.every((o) => o.op === "circle" && o.fill === COL_FOREGROUND)).toBe(
        true,
      );

      const lines = ops.filter((o) => o.op === "line");
      expect(lines.length).toBe(g.numEdges);
      // An untouched board is entirely UNKNOWN, so every line takes that one
      // colour — which also pins that no edge is silently drawn as an error.
      expect(lines.every((o) => o.op === "line" && o.colour === COL_LINEUNKNOWN)).toBe(
        true,
      );

      // Clues are drawn for exactly the clued faces, in face order and with
      // the right digits — the pairing, not just the count, since a tiling
      // whose face list the renderer walked differently would still emit the
      // right *number* of digits.
      const texts = ops.filter((o) => o.op === "text");
      const expected = [...state.clues].filter((c) => c >= 0).map(String);
      expect(texts.map((o) => (o.op === "text" ? o.text : ""))).toEqual(expected);
      expect(expected.length).toBeGreaterThan(0);

      // Every digit lands on the canvas. This is the check that would catch a
      // face incentre computed in the wrong space for an irregular tiling —
      // the failure mode most likely to be unique to hats/spectres/Penrose.
      for (const t of texts) {
        if (t.op !== "text") continue;
        expect(t.x).toBeGreaterThanOrEqual(0);
        expect(t.y).toBeGreaterThanOrEqual(0);
        expect(t.x).toBeLessThanOrEqual(size.w);
        expect(t.y).toBeLessThanOrEqual(size.h);
      }

      // And every dot lands where the projection says it should, which pins
      // the geometry itself rather than only its bulk properties.
      const dotKeys = new Set(
        circles.map((o) => (o.op === "circle" ? `${o.cx},${o.cy}` : "")),
      );
      for (const d of g.dots) {
        const [x, y] = screenPos(state, PREFERRED_TILE_SIZE, d.x, d.y);
        expect(dotKeys.has(`${x},${y}`)).toBe(true);
      }

      // The background rect must back everything the game then draws on top
      // of it: the game owns its own pixels, so anything outside it is left
      // showing whatever the canvas held before.
      const bg = ops[0];
      if (bg.op !== "rect") throw new Error("unreachable");
      for (const c of circles) {
        if (c.op !== "circle") continue;
        expect(c.cx + c.r).toBeLessThanOrEqual(bg.w);
        expect(c.cy + c.r).toBeLessThanOrEqual(bg.h);
      }

      expect(ops).toMatchSnapshot();
    });
  }
});

describe("Loopy render scenarios: line state and preferences", () => {
  const SQUARES = () => board("squares", 0, 5, 5);

  it("draws a YES edge black, a NO edge faint and the rest unknown", () => {
    const { id, state } = SQUARES();
    // Two edges far enough apart that neither creates a vertex error, so the
    // frame shows the three plain line colours and nothing else.
    const yesEdge = 0;
    const noEdge = 40;
    const { recording } = renderScenario({
      game: loopyGame,
      id,
      moves: [setEdges([yesEdge], LINE_YES), setEdges([noEdge], LINE_NO)],
    });
    const lines = recording.ops.filter((o) => o.op === "line");
    const byColour = (c: number) =>
      lines.filter((o) => o.op === "line" && o.colour === c);

    expect(byColour(COL_FOREGROUND).length).toBe(1);
    expect(byColour(COL_FAINT).length).toBe(1);
    expect(byColour(COL_LINEUNKNOWN).length).toBe(state.grid.numEdges - 2);
    expect(byColour(COL_MISTAKE).length).toBe(0);

    // The black line is the edge that was actually set, not merely *an* edge:
    // colour counts alone would survive the renderer colouring the wrong one.
    const e = state.grid.edges[yesEdge];
    const [x1, y1] = screenPos(state, PREFERRED_TILE_SIZE, e.dot1.x, e.dot1.y);
    const [x2, y2] = screenPos(state, PREFERRED_TILE_SIZE, e.dot2.x, e.dot2.y);
    expect(byColour(COL_FOREGROUND)[0]).toMatchObject({ x1, y1, x2, y2 });

    // A NO line is drawn thinner than a laid one — that difference is the
    // whole reason a faint line reads as a mark rather than as a segment.
    const faint = byColour(COL_FAINT)[0];
    const black = byColour(COL_FOREGROUND)[0];
    if (faint.op !== "line" || black.op !== "line") throw new Error("unreachable");
    expect(faint.thickness).toBeLessThan(black.thickness);

    expect(recording.ops).toMatchSnapshot();
  });

  it("omits NO lines entirely when draw-faint-lines is off", () => {
    const { id } = SQUARES();
    const moves = [setEdges([40], LINE_NO)];

    const shown = renderScenario({ game: loopyGame, id, moves });
    expect(
      shown.recording.ops.filter((o) => o.op === "line" && o.colour === COL_FAINT)
        .length,
    ).toBe(1);

    // The preference lives on the ui, which `renderScenario` does not expose,
    // so this one drives the Midend directly — same production path.
    const midend = new Midend(loopyGame);
    expect(midend.newGameFromId(id)).toBeUndefined();
    midend.playMoves(moves);
    expect(midend.setPreferences({ "draw-faint-lines": false })).toBeUndefined();
    const recording = new RecordingDrawing(loopyGame.colours(DEFAULT_BACKGROUND));
    midend.redraw(recording);

    // Not merely recoloured: the phase is skipped, so the NO edge contributes
    // no line op at all.
    expect(
      recording.ops.filter((o) => o.op === "line" && o.colour === COL_FAINT).length,
    ).toBe(0);
    expect(recording.ops.filter((o) => o.op === "line").length).toBe(
      shown.recording.ops.filter((o) => o.op === "line").length - 1,
    );
  });
});

describe("Loopy render scenarios: error highlighting", () => {
  it("reddens all three YES edges at a vertex of degree 3", () => {
    const { id, state } = board("squares", 0, 5, 5);
    // Degree 3 at a dot is a hard vertex error whatever else is on the board,
    // so all three edges light up — and nothing else does, since the rest of
    // the grid is untouched.
    const dot = state.grid.dots.find((d) => d.order >= 3);
    if (!dot) throw new Error("a square grid has interior dots of order 4");
    const edges = [0, 1, 2].map((j) => dot.edges[j].index);

    const { recording } = renderScenario({
      game: loopyGame,
      id,
      moves: [setEdges(edges, LINE_YES)],
    });
    const mistakes = recording.ops.filter(
      (o) => o.op === "line" && o.colour === COL_MISTAKE,
    );
    expect(mistakes.length).toBe(3);
    // No black lines survive: every laid edge on this board is one of the
    // three, and an errored edge is drawn in the error colour instead.
    expect(
      recording.ops.filter((o) => o.op === "line" && o.colour === COL_FOREGROUND)
        .length,
    ).toBe(0);

    const positions = new Set(
      mistakes.map((o) => (o.op === "line" ? `${o.x1},${o.y1},${o.x2},${o.y2}` : "")),
    );
    for (const i of edges) {
      const e = state.grid.edges[i];
      const [x1, y1] = screenPos(state, PREFERRED_TILE_SIZE, e.dot1.x, e.dot1.y);
      const [x2, y2] = screenPos(state, PREFERRED_TILE_SIZE, e.dot2.x, e.dot2.y);
      expect(positions.has(`${x1},${y1},${x2},${y2}`)).toBe(true);
    }
    expect(recording.ops).toMatchSnapshot();
  });

  it("reddens an underfilled clue the instant a single loop closes", () => {
    // The `exactlyOneLoop` rule: once the YES edges form one loop and nothing
    // else, UNKNOWN counts as NO for clue checking. Without it a player who
    // never right-clicks could close a loop over an unsatisfied clue and be
    // shown neither a victory flash nor a reason why not.
    const { id, state } = board("squares", 0, 5, 5);
    const g = state.grid;

    // A unit loop around face 0. Faces 1 and 5 share an edge with it, so any
    // *other* clued face still has zero YES edges around it.
    const loop = g.faces[0].edges.filter((e) => e !== null).map((e) => e.index);
    const clued = [...state.clues.keys()].filter((i) => state.clues[i] >= 0);
    const victim = clued.find((i) => i > 5 && state.clues[i] >= 1);
    if (victim === undefined) throw new Error("no clued face away from the unit loop");
    const nth = clued.indexOf(victim);

    // Before the loop closes the same clue is ordinary black: nothing about
    // the clue changed, only whether the board is one loop.
    const before = renderScenario({ game: loopyGame, id });
    const beforeText = before.recording.ops.filter((o) => o.op === "text")[nth];
    expect(beforeText).toMatchObject({
      text: String(state.clues[victim]),
      colour: COL_FOREGROUND,
    });

    const after = renderScenario({
      game: loopyGame,
      id,
      moves: [setEdges(loop, LINE_YES)],
    });
    const afterText = after.recording.ops.filter((o) => o.op === "text")[nth];
    expect(afterText).toMatchObject({
      text: String(state.clues[victim]),
      colour: COL_MISTAKE,
    });

    // The loop itself is a legal single component, so its edges stay black —
    // the error is the clue, not the lines.
    expect(
      after.recording.ops.filter((o) => o.op === "line" && o.colour === COL_MISTAKE)
        .length,
    ).toBe(0);
    expect(
      after.recording.ops.filter((o) => o.op === "line" && o.colour === COL_FOREGROUND)
        .length,
    ).toBe(loop.length);
  });
});

describe("Loopy render scenarios: clue-position cache", () => {
  it("moves the clues when the tile size changes", () => {
    // Design D6b. Upstream never invalidates the `textx`/`texty` cache because
    // its frontends set the size once; this project's ResizeController calls
    // `size()` on every layout perturbation, so a surviving cache would leave
    // every clue at its pre-resize position — the stale-cache class of bug
    // that cost Flip three iterations.
    const { p, id, state } = board("squares", 0, 5, 5);
    const g = state.grid;
    const palette = loopyGame.colours(DEFAULT_BACKGROUND);

    const midend = new Midend(loopyGame);
    expect(midend.newGameFromId(id)).toBeUndefined();

    const big = new RecordingDrawing(palette);
    midend.redraw(big);

    // Shrink to exactly half the preferred tile size. `size()` picks the
    // largest tile that fits, and computeSize is strictly increasing here, so
    // handing it the size of a 16px board pins the tile size at 16.
    const SMALL_TILE = PREFERRED_TILE_SIZE / 2;
    expect(midend.size(computeSize(p, SMALL_TILE), false, 1)).toEqual(
      computeSize(p, SMALL_TILE),
    );
    const small = new RecordingDrawing(palette);
    midend.redraw(small);

    const posOf = (r: RecordingDrawing) =>
      r.ops
        .filter((o) => o.op === "text")
        .map((o) => (o.op === "text" ? [o.x, o.y] : []));
    const bigPos = posOf(big);
    const smallPos = posOf(small);
    expect(smallPos.length).toBe(bigPos.length);
    expect(smallPos).not.toEqual(bigPos);

    // Not merely *different* — correct for the new tile size. A cache that
    // half-invalidated (say, only x) would still fail this.
    const clued = [...state.clues.keys()].filter((i) => state.clues[i] >= 0);
    clued.forEach((face, k) => {
      const f = g.faces[face];
      gridFindIncentre(f);
      expect(smallPos[k]).toEqual(screenPos(state, SMALL_TILE, f.ix, f.iy));
      expect(bigPos[k]).toEqual(screenPos(state, PREFERRED_TILE_SIZE, f.ix, f.iy));
    });
  });
});

